window.KS_COURSE={"title": "KS3 Science", "site": "ks3-science", "reviewed": "2026-10-24", "units": [{"id": "y7-unit-01", "year": 7, "number": 1, "title": "Working scientifically", "skills": ["safety", "variables", "planning", "burner", "data", "evaluate"]}, {"id": "y7-unit-02", "year": 7, "number": 2, "title": "Cells", "skills": ["microscope", "cell", "specialised", "diffusion"]}, {"id": "y7-unit-03", "year": 7, "number": 3, "title": "Movement", "skills": ["organisation", "muscles", "planning"]}, {"id": "y7-unit-04", "year": 7, "number": 4, "title": "Particle model", "skills": ["particles", "state", "diffusion", "gas", "atoms"]}, {"id": "y7-unit-05", "year": 7, "number": 5, "title": "Separating mixtures", "skills": ["atoms", "solution", "filter", "distil"]}, {"id": "y7-unit-06", "year": 7, "number": 6, "title": "Energy costs", "skills": ["energy", "food-energy", "resources", "power"]}, {"id": "y7-unit-07", "year": 7, "number": 7, "title": "Energy transfers", "skills": ["energy", "efficiency"]}, {"id": "y7-unit-08", "year": 7, "number": 8, "title": "Variation and adaptation", "skills": ["variation", "adaptation", "data"]}, {"id": "y7-unit-09", "year": 7, "number": 9, "title": "Human reproduction", "skills": ["puberty", "cycle", "pregnancy"]}, {"id": "y7-unit-10", "year": 7, "number": 10, "title": "Plant reproduction", "skills": ["flower", "seed", "germination"]}, {"id": "y7-unit-11", "year": 7, "number": 11, "title": "Acids and alkalis", "skills": ["reaction", "acid", "neutral"]}, {"id": "y7-unit-12", "year": 7, "number": 12, "title": "Metals and non-metals", "skills": ["metals", "metal-acid"]}, {"id": "y7-unit-13", "year": 7, "number": 13, "title": "Current and charge", "skills": ["charge", "current"]}, {"id": "y7-unit-14", "year": 7, "number": 14, "title": "Potential difference and resistance", "skills": ["voltage", "current"]}, {"id": "y8-unit-01", "year": 8, "number": 1, "title": "Interdependence", "skills": ["foodweb", "ecosystem"]}, {"id": "y8-unit-02", "year": 8, "number": 2, "title": "Speed", "skills": ["speed", "dt", "data"]}, {"id": "y8-unit-03", "year": 8, "number": 3, "title": "Gravity and forces", "skills": ["force", "gravity", "crater"]}, {"id": "y8-unit-04", "year": 8, "number": 4, "title": "Elements and materials", "skills": ["atoms", "elements", "metals", "polymer"]}, {"id": "y8-unit-05", "year": 8, "number": 5, "title": "Periodic table", "skills": ["periodic", "groups", "transition"]}, {"id": "y8-unit-06", "year": 8, "number": 6, "title": "Breathing and health", "skills": ["lungs", "drugs"]}, {"id": "y8-unit-07", "year": 8, "number": 7, "title": "Digestion and nutrition", "skills": ["nutrition", "food-tests", "digestion"]}, {"id": "y8-unit-08", "year": 8, "number": 8, "title": "Sound", "skills": ["sound", "ear"]}, {"id": "y8-unit-09", "year": 8, "number": 9, "title": "Light", "skills": ["light", "colour"]}, {"id": "y8-unit-10", "year": 8, "number": 10, "title": "Reaction types", "skills": ["reaction", "combustion", "mass"]}, {"id": "y8-unit-11", "year": 8, "number": 11, "title": "Chemical energy", "skills": ["chemical-energy", "catalyst"]}, {"id": "y8-unit-12", "year": 8, "number": 12, "title": "Respiration", "skills": ["respiration", "anaerobic", "planning"]}, {"id": "y8-unit-13", "year": 8, "number": 13, "title": "Photosynthesis", "skills": ["photosynthesis", "leaf", "plant-practical"]}, {"id": "y8-unit-14", "year": 8, "number": 14, "title": "Working scientifically investigations", "skills": ["investigate-candle", "investigate-bounce", "investigate-bungee", "investigate-conduction", "investigate-cupcake", "investigate-salt", "investigate-diffusion"]}, {"id": "y9-unit-01", "year": 9, "number": 1, "title": "Electromagnets", "skills": ["magnet", "electromagnet", "planning"]}, {"id": "y9-unit-02", "year": 9, "number": 2, "title": "Work and machines", "skills": ["work", "food-energy", "moments"]}, {"id": "y9-unit-03", "year": 9, "number": 3, "title": "Heating and cooling", "skills": ["thermal", "convection"]}, {"id": "y9-unit-04", "year": 9, "number": 4, "title": "Climate", "skills": ["atmosphere", "climate"]}, {"id": "y9-unit-05", "year": 9, "number": 5, "title": "Earth’s resources", "skills": ["extraction", "metals", "recycle"]}, {"id": "y9-unit-06", "year": 9, "number": 6, "title": "Evolution and biodiversity", "skills": ["selection", "evidence-evolution", "biodiversity"]}, {"id": "y9-unit-07", "year": 9, "number": 7, "title": "Inheritance", "skills": ["inheritance", "dna-practical", "cross", "gm"]}, {"id": "y9-unit-08", "year": 9, "number": 8, "title": "Waves and the EM spectrum", "skills": ["waves", "ultrasound", "em"]}, {"id": "y9-unit-09", "year": 9, "number": 9, "title": "Earth structure and rocks", "skills": ["earth", "sediment", "rock-cycle"]}, {"id": "y9-unit-10", "year": 9, "number": 10, "title": "The Universe", "skills": ["space", "orbits", "moon"]}, {"id": "y9-unit-11", "year": 9, "number": 11, "title": "Contact forces", "skills": ["friction", "spring", "moments"]}, {"id": "y9-unit-12", "year": 9, "number": 12, "title": "Pressure", "skills": ["pressure", "gas", "liquid-pressure"]}], "lessons": [{"key": "safety", "title": "Staying safe in the lab", "notes": ["A hazard is something that could hurt you. A risk is the chance of being hurt and how serious it could be. Follow your teacher's instructions in the lab.", "Wear goggles when liquids could splash. Use a measuring cylinder to measure liquid volume. Read the bottom of the water curve at eye level."], "worked": "Hot glass can burn skin. Leave it to cool before touching it. Use a heatproof mat to protect the bench.", "question": "How would you measure 25 cm³ of water? Give one way to protect your eyes from splashes.", "scheme": ["Use a measuring cylinder with a clear scale.", "Read the bottom of the water curve at eye level.", "Wear safety goggles."], "mistake": "Saying “be careful” is not enough. Say what you would do to stay safe.", "model": null, "id": "y7-unit-01-safety", "unit": "y7-unit-01", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Hazard", "definition": "Something that could cause harm."}, {"term": "Risk", "definition": "The chance of harm and how serious it could be."}], "quiz": {"q": "Which action protects your eyes from splashes?", "opts": ["Take no measurements.", "Wear safety goggles.", "Only write “be careful”."], "a": 1, "why": "Goggles help stop splashes reaching your eyes."}, "misconception": {"q": "Which action protects your eyes from splashes? Sam answers: “Only write “be careful”.” Explain why this is wrong.", "m": 2, "ms": ["Wear safety goggles.", "Goggles help stop splashes reaching your eyes."]}}, {"key": "variables", "title": "Questions, predictions and variables", "notes": ["A variable is something that can change in an experiment. The independent variable is the one you change. The dependent variable is the one you measure.", "Keep control variables the same to make the test fair. A prediction says what you think will happen. Use a science idea to explain your prediction."], "worked": "To test how temperature affects sugar dissolving, change the water temperature. Measure the time taken for the sugar to dissolve. Keep the sugar mass and water volume the same.", "question": "Test how light affects pondweed. Name what you change, what you measure and two things you keep the same.", "scheme": ["Change light level, for example by moving the lamp.", "Measure oxygen made in a set time.", "Keep water temperature and carbon dioxide supply the same."], "mistake": "A fair test changes one variable at a time.", "model": null, "id": "y7-unit-01-variables", "unit": "y7-unit-01", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Independent variable", "definition": "The thing you choose to change in a test."}, {"term": "Dependent variable", "definition": "The thing you measure in a test."}, {"term": "Control variable", "definition": "Something you keep the same to make a test fair."}], "quiz": {"q": "In a test of temperature and dissolving time, what do you measure?", "opts": ["Time taken for the solid to dissolve.", "The temperature you choose.", "The label on the beaker."], "a": 0, "why": "You change the temperature and measure the time taken to dissolve."}, "misconception": {"q": "In a test of temperature and dissolving time, what do you measure? Sam answers: “The temperature you choose.” Explain why this is wrong.", "m": 2, "ms": ["Time taken for the solid to dissolve.", "You change the temperature and measure the time taken to dissolve."]}}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y7-unit-01-planning", "unit": "y7-unit-01", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It makes the clock perfect.", "It reduces the effect of your reaction time on each swing's time.", "It fixes every equipment error."], "a": 1, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}}, {"key": "burner", "title": "Using a Bunsen burner", "notes": ["A Bunsen burner burns gas to heat things. Burning is called combustion. The gas needs oxygen from the air to burn.", "A closed air hole gives a yellow safety flame. An open air hole gives a hotter blue heating flame. Only change the air hole when your teacher tells you to."], "worked": "More air means more oxygen can mix with the gas. The gas can burn more completely. Tie back long hair and keep flammable items away.", "question": "Why does opening the air hole change the flame? Give one safety rule for heating.", "scheme": ["More air and oxygen can reach the gas.", "More complete burning produces a blue heating flame.", "Tie back hair, wear goggles or give another suitable safety rule."], "mistake": "The yellow safety flame is still hot enough to burn you.", "model": null, "id": "y7-unit-01-burner", "unit": "y7-unit-01", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Combustion", "definition": "Burning: a reaction with oxygen that transfers energy to the surroundings."}, {"term": "Safety flame", "definition": "The visible yellow Bunsen flame used when you are not heating."}], "quiz": {"q": "What does opening a Bunsen burner's air hole change?", "opts": ["The mass of the burner.", "The amount of air and oxygen entering.", "The type of gas fuel."], "a": 1, "why": "More oxygen helps the gas burn more completely, making a blue heating flame."}, "misconception": {"q": "What does opening a Bunsen burner's air hole change? Sam answers: “The type of gas fuel.” Explain why this is wrong.", "m": 2, "ms": ["The amount of air and oxygen entering.", "More oxygen helps the gas burn more completely, making a blue heating flame."]}}, {"key": "data", "title": "Tables, graphs and conclusions", "notes": ["Put measurements in a results table. Label each column with the quantity and its unit. A graph helps you spot a pattern.", "Use a line graph for measurements such as time and temperature. Use a bar chart for separate groups, such as different materials. A conclusion answers your question using your results."], "worked": "Suppose sugar dissolves in 40 seconds in cool water and 20 seconds in warm water. The warmer water gave a shorter dissolving time. Use these numbers as evidence in your conclusion.", "question": "What graph would show water temperature and sugar dissolving time? How would you write a good conclusion?", "scheme": ["Use a line or scatter graph with temperature on the horizontal axis.", "Put dissolving time on the vertical axis and label both units.", "Describe the pattern and use numbers from the results."], "mistake": "A conclusion needs evidence. Do not just say your prediction was right.", "model": null, "id": "y7-unit-01-data", "unit": "y7-unit-01", "year": 7, "number": 5, "marks": 3, "cards": [{"term": "Continuous data", "definition": "Measurements with values anywhere within a range, such as height."}, {"term": "Discrete data", "definition": "Separate counts or values, such as the number of leaves."}, {"term": "Conclusion", "definition": "An answer to your test question, supported by your results."}], "quiz": {"q": "What makes a good conclusion?", "opts": ["Choose your favourite result and ignore the others.", "Leave units off the graph.", "Describe a pattern and use numbers from the results."], "a": 2, "why": "Numbers from the results give evidence for the pattern you describe."}, "misconception": {"q": "What makes a good conclusion? Sam answers: “Choose your favourite result and ignore the others.” Explain why this is wrong.", "m": 2, "ms": ["Describe a pattern and use numbers from the results.", "Numbers from the results give evidence for the pattern you describe."]}}, {"key": "evaluate", "title": "Spotting errors and improving tests", "notes": ["Measurements can change slightly when you repeat them. These unpredictable changes are called random errors. An unusual result that does not fit the pattern is an anomaly.", "A systematic error makes readings wrong in the same way each time. Check equipment for a zero error before measuring. Choose an improvement that tackles the actual problem."], "worked": "A balance shows 2 g when nothing is on it. Every mass reading will be 2 g too high. Set it to zero before taking new readings.", "question": "A thermometer always reads 2°C too high. Name the error and explain why repeating readings will not fix it.", "scheme": ["This is a systematic error.", "Every reading is too high by the same amount.", "A mean of repeated readings will still be too high."], "mistake": "More repeats help with random errors. They do not remove a fixed error in the equipment.", "model": null, "id": "y7-unit-01-evaluate", "unit": "y7-unit-01", "year": 7, "number": 6, "marks": 3, "cards": [{"term": "Random error", "definition": "An unpredictable change between repeated measurements."}, {"term": "Systematic error", "definition": "An error that makes readings wrong in the same way each time."}, {"term": "Anomaly", "definition": "A result that does not fit the pattern."}], "quiz": {"q": "A balance always reads 2 g too high. What should you do?", "opts": ["Call it a random error.", "Check and correct its zero or calibration.", "Just take a mean of more wrong readings."], "a": 1, "why": "A mean will still be too high. The balance needs correcting before new measurements are made."}, "misconception": {"q": "A balance always reads 2 g too high. What should you do? Sam answers: “Just take a mean of more wrong readings.” Explain why this is wrong.", "m": 2, "ms": ["Check and correct its zero or calibration.", "A mean will still be too high. The balance needs correcting before new measurements are made."]}}, {"key": "microscope", "title": "Using a microscope", "notes": ["A microscope makes tiny objects look bigger. Start with the lowest-power lens. Adjust the focus until the image is clear.", "Total magnification = eyepiece magnification × objective magnification. Use the same units when comparing image size and actual size. Draw clear outlines and use straight label lines."], "worked": "A ×10 eyepiece and a ×40 objective give 10 × 40 = ×400 magnification. The image looks 400 times bigger than the object. Magnification does not tell you how much detail is clear.", "question": "A microscope has a ×10 eyepiece and ×20 objective. Find total magnification. Why must image and actual sizes use the same units?", "scheme": ["Multiply 10 × 20.", "Total magnification is ×200.", "Matching units makes the size comparison correct."], "mistake": "A bigger image is not always a clearer image.", "model": "cell", "id": "y7-unit-02-microscope", "unit": "y7-unit-02", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Magnification", "definition": "How many times bigger an image is than the real object."}, {"term": "Resolution", "definition": "How well an image shows two close details separately."}], "quiz": {"q": "What is the total magnification with a ×10 eyepiece and ×40 objective?", "opts": ["×400.", "×50.", "×4."], "a": 0, "why": "Multiply the lens magnifications: 10 × 40 = 400."}, "misconception": {"q": "What is the total magnification with a ×10 eyepiece and ×40 objective? Sam answers: “×50.” Explain why this is wrong.", "m": 2, "ms": ["×400.", "Multiply the lens magnifications: 10 × 40 = 400."]}}, {"key": "cell", "title": "Plant and animal cells", "notes": ["Cells are the small building blocks of living things. Plant and animal cells have a nucleus, cytoplasm and cell membrane. The nucleus contains genetic information.", "A plant cell also has a cell wall and a large permanent vacuole. Many leaf cells have chloroplasts that absorb light. Both plant and animal cells release energy by respiration. Cytoplasm is where many chemical reactions happen. The membrane controls what enters and leaves. Mitochondria are where aerobic respiration happens. Ribosomes make proteins. A cell wall supports a plant cell, and its vacuole contains cell sap."], "worked": "A leaf cell uses chloroplasts for photosynthesis. A root cell usually has no chloroplasts because it gets little light. An animal cell has no cell wall.", "question": "Compare a leaf cell with an animal cell. Name one structure they share and two differences.", "scheme": ["Both have a nucleus, cytoplasm or cell membrane.", "A leaf cell has a cell wall but an animal cell does not.", "A leaf cell has chloroplasts or a large permanent vacuole, unlike a typical animal cell."], "mistake": "Not every plant cell has chloroplasts. Root cells usually do not.", "model": "cell", "id": "y7-unit-02-cell", "unit": "y7-unit-02", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Nucleus", "definition": "The cell part containing genetic information."}, {"term": "Cell membrane", "definition": "A thin boundary that controls what enters and leaves a cell."}, {"term": "Chloroplast", "definition": "A cell part containing chlorophyll, which absorbs light for photosynthesis."}], "quiz": {"q": "Which statement about plant cells is correct?", "opts": ["Every plant cell has chloroplasts.", "Plant cells do not respire.", "Most root cells have no chloroplasts."], "a": 2, "why": "Most root cells receive little light and do not carry out photosynthesis."}, "misconception": {"q": "Which statement about plant cells is correct? Sam answers: “Every plant cell has chloroplasts.” Explain why this is wrong.", "m": 2, "ms": ["Most root cells have no chloroplasts.", "Most root cells receive little light and do not carry out photosynthesis."]}}, {"key": "specialised", "title": "Cells with special jobs", "notes": ["A specialised cell has features that help it do a particular job. A red blood cell carries oxygen. A root hair cell takes water and minerals into a plant.", "A root hair cell has a long, thin part that reaches into the soil. This gives it a large surface area for taking substances in. A unicellular organism is a living thing made of just one cell. A thin cell wall gives water a short distance to travel."], "worked": "The long part of a root hair cell touches more soil water. More water and dissolved minerals can enter the cell. The whole plant depends on these substances.", "question": "Describe two features of a root hair cell. Explain how they help it absorb water or minerals.", "scheme": ["Its long extension gives a large surface area.", "The large surface area helps water and minerals enter.", "A thin cell wall gives water a short distance to travel."], "mistake": "A specialised cell is still a cell. Its features help it do its job.", "model": null, "id": "y7-unit-02-specialised", "unit": "y7-unit-02", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Specialised cell", "definition": "A cell with features that help it do a particular job."}, {"term": "Unicellular organism", "definition": "A living thing made of one cell."}], "quiz": {"q": "Why does a root hair cell have a long, thin extension?", "opts": ["It turns it into an animal cell.", "It makes sunlight.", "It gives a bigger surface area for taking in water and minerals."], "a": 2, "why": "More surface area means more contact with the water around soil particles."}, "misconception": {"q": "Why does a root hair cell have a long, thin extension? Sam answers: “It turns it into an animal cell.” Explain why this is wrong.", "m": 2, "ms": ["It gives a bigger surface area for taking in water and minerals.", "More surface area means more contact with the water around soil particles."]}}, {"key": "diffusion", "title": "How particles spread out: diffusion", "notes": ["Particles in liquids and gases keep moving. They spread from a crowded area to a less crowded area. This spreading is called diffusion.", "Concentration means how much of a substance is in a space. More particles move away from a high concentration than towards it. Particles still move when they are evenly spread. A larger concentration difference can make diffusion faster. A higher temperature usually makes particles move faster."], "worked": "A cell uses oxygen during respiration. There is then less oxygen inside the cell than outside. Oxygen diffuses into the cell through its membrane.", "question": "A cell uses oxygen in respiration. Explain why oxygen moves into it by diffusion.", "scheme": ["The cell uses up oxygen.", "Oxygen concentration is higher outside than inside.", "More oxygen particles move into the cell than out."], "mistake": "Particles do not stop moving when they are evenly spread.", "model": "diffusion", "id": "y7-unit-02-diffusion", "unit": "y7-unit-02", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Diffusion", "definition": "Particles spreading from a higher concentration to a lower concentration."}, {"term": "Concentration gradient", "definition": "A difference in concentration between two places."}], "quiz": {"q": "What happens when diffusing particles are evenly spread?", "opts": ["They only move towards the most crowded area.", "They keep moving in both directions.", "They all stop moving."], "a": 1, "why": "Particles keep moving, but equal amounts move each way overall."}, "misconception": {"q": "What happens when diffusing particles are evenly spread? Sam answers: “They all stop moving.” Explain why this is wrong.", "m": 2, "ms": ["They keep moving in both directions.", "Particles keep moving, but equal amounts move each way overall."]}}, {"key": "organisation", "title": "Cells, organs and joints", "notes": ["Cells with similar jobs work together as a tissue. Different tissues work together to make an organ. Organs work together in an organ system.", "Your skeleton supports your body and protects organs. Joints are places where bones meet. Muscles pull on bones to move them."], "worked": "Cartilage makes smooth surfaces at the ends of bones. Ligaments hold bones together at a joint. Tendons join muscles to bones.", "question": "What do cartilage, ligaments and tendons do at a joint?", "scheme": ["Cartilage reduces rubbing between the ends of bones.", "Ligaments join bone to bone.", "Tendons join muscle to bone."], "mistake": "Ligaments and tendons have different jobs. Do not swap their names.", "model": null, "id": "y7-unit-03-organisation", "unit": "y7-unit-03", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Tissue", "definition": "A group of cells working together to do a job."}, {"term": "Organ", "definition": "A body part made of different tissues working together."}, {"term": "Ligament", "definition": "A strong band joining bone to bone."}], "quiz": {"q": "What joins a muscle to a bone?", "opts": ["A tendon.", "A ligament.", "Only cartilage."], "a": 0, "why": "Tendons join muscle to bone. Ligaments join bone to bone."}, "misconception": {"q": "What joins a muscle to a bone? Sam answers: “A ligament.” Explain why this is wrong.", "m": 2, "ms": ["A tendon.", "Tendons join muscle to bone. Ligaments join bone to bone."]}}, {"key": "muscles", "title": "How muscles move bones", "notes": ["Muscles pull on bones to make them move. A contracting muscle develops a pulling force. Muscles cannot actively push bones back.", "Muscles often work in pairs. One pulls a joint one way and the other pulls it back. This is called an antagonistic pair."], "worked": "To bend your elbow, your biceps contracts and your triceps relaxes. To straighten it, your triceps contracts and your biceps relaxes. The muscles pull in opposite directions.", "question": "Why do you need two opposing muscles to bend and straighten an elbow?", "scheme": ["Muscles move bones by pulling, not pushing.", "One muscle contracts to bend the elbow.", "The opposing muscle contracts to straighten it."], "mistake": "A relaxed muscle does not push a bone back into place.", "model": null, "id": "y7-unit-03-muscles", "unit": "y7-unit-03", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Antagonistic pair", "definition": "Two muscles that pull a joint in opposite directions."}, {"term": "Contraction", "definition": "When a muscle develops a pulling force, often becoming shorter."}], "quiz": {"q": "Why do two muscles work as an opposing pair at the elbow?", "opts": ["The bones contract.", "Muscles pull bones but cannot actively push them back.", "A relaxed muscle pushes the bone back."], "a": 1, "why": "One muscle pulls to bend the joint and the other pulls to straighten it."}, "misconception": {"q": "Why do two muscles work as an opposing pair at the elbow? Sam answers: “A relaxed muscle pushes the bone back.” Explain why this is wrong.", "m": 2, "ms": ["Muscles pull bones but cannot actively push them back.", "One muscle pulls to bend the joint and the other pulls to straighten it."]}}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y7-unit-03-planning", "unit": "y7-unit-03", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It reduces the effect of your reaction time on each swing's time.", "It fixes every equipment error.", "It makes the clock perfect."], "a": 0, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}}, {"key": "particles", "title": "Solids, liquids and gases", "notes": ["Everything around you is made of tiny particles. In a solid, particles are close together and vibrate in fixed positions. In a liquid, particles stay close but move past each other.", "Gas particles are far apart and move freely. A gas spreads out to fill its container. A liquid keeps its volume but takes the container's shape."], "worked": "Push a syringe full of air and the air takes up less space. The gaps between gas particles get smaller. A syringe full of liquid is much harder to squeeze.", "question": "Why can you squeeze a gas into a smaller space much more easily than a liquid?", "scheme": ["Gas particles have large gaps between them.", "Squeezing brings the particles closer together.", "Liquid particles are already close together."], "mistake": "Squeezing a gas makes the gaps smaller. It does not make the particles smaller.", "model": "particles", "id": "y7-unit-04-particles", "unit": "y7-unit-04", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Solid", "definition": "A state with close particles vibrating in fixed positions."}, {"term": "Liquid", "definition": "A state with close particles that move past each other."}, {"term": "Gas", "definition": "A state with widely spaced particles moving freely."}], "quiz": {"q": "Why is a gas easy to squeeze into a smaller space?", "opts": ["The particles shrink.", "It contains no particles.", "There are large gaps between particles."], "a": 2, "why": "Squeezing a gas reduces the gaps between its particles."}, "misconception": {"q": "Why is a gas easy to squeeze into a smaller space? Sam answers: “The particles shrink.” Explain why this is wrong.", "m": 2, "ms": ["There are large gaps between particles.", "Squeezing a gas reduces the gaps between its particles."]}}, {"key": "state", "title": "Melting, freezing, boiling and condensing", "notes": ["Melting changes a solid into a liquid. Freezing changes a liquid into a solid. These changes do not make a new substance.", "Evaporation happens at a liquid's surface, even below its boiling point. Boiling happens throughout a liquid at its boiling point. Condensation changes a gas into a liquid."], "worked": "A puddle slowly dries on a cool day by evaporation. Water in a boiling kettle forms bubbles throughout the liquid. Both changes turn liquid water into water vapour.", "question": "How is evaporation different from boiling? Give three differences or linked facts.", "scheme": ["Evaporation happens at the surface.", "Evaporation can happen below the boiling point.", "Boiling happens throughout the liquid at its boiling point."], "mistake": "Steam that you can see is tiny water droplets. Water vapour itself is invisible.", "model": "particles", "id": "y7-unit-04-state", "unit": "y7-unit-04", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Melting", "definition": "Changing from a solid to a liquid."}, {"term": "Evaporation", "definition": "Particles leaving a liquid's surface as a gas."}, {"term": "Condensation", "definition": "Changing from a gas to a liquid."}], "quiz": {"q": "How is evaporation different from boiling?", "opts": ["It turns water into a different element.", "It must happen throughout the liquid.", "It can happen at the surface below the boiling point."], "a": 2, "why": "Evaporation happens at the surface. Boiling happens throughout the liquid at its boiling point."}, "misconception": {"q": "How is evaporation different from boiling? Sam answers: “It turns water into a different element.” Explain why this is wrong.", "m": 2, "ms": ["It can happen at the surface below the boiling point.", "Evaporation happens at the surface. Boiling happens throughout the liquid at its boiling point."]}}, {"key": "diffusion", "title": "How particles spread out: diffusion", "notes": ["Particles in liquids and gases keep moving. They spread from a crowded area to a less crowded area. This spreading is called diffusion.", "Concentration means how much of a substance is in a space. More particles move away from a high concentration than towards it. Particles still move when they are evenly spread. A larger concentration difference can make diffusion faster. A higher temperature usually makes particles move faster."], "worked": "A cell uses oxygen during respiration. There is then less oxygen inside the cell than outside. Oxygen diffuses into the cell through its membrane.", "question": "A cell uses oxygen in respiration. Explain why oxygen moves into it by diffusion.", "scheme": ["The cell uses up oxygen.", "Oxygen concentration is higher outside than inside.", "More oxygen particles move into the cell than out."], "mistake": "Particles do not stop moving when they are evenly spread.", "model": "diffusion", "id": "y7-unit-04-diffusion", "unit": "y7-unit-04", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Diffusion", "definition": "Particles spreading from a higher concentration to a lower concentration."}, {"term": "Concentration gradient", "definition": "A difference in concentration between two places."}], "quiz": {"q": "What happens when diffusing particles are evenly spread?", "opts": ["They keep moving in both directions.", "They all stop moving.", "They only move towards the most crowded area."], "a": 0, "why": "Particles keep moving, but equal amounts move each way overall."}, "misconception": {"q": "What happens when diffusing particles are evenly spread? Sam answers: “They all stop moving.” Explain why this is wrong.", "m": 2, "ms": ["They keep moving in both directions.", "Particles keep moving, but equal amounts move each way overall."]}}, {"key": "gas", "title": "Gas pressure", "notes": ["Gas particles move in all directions. They hit the walls of their container. These hits cause gas pressure.", "Squeezing a gas puts the particles in a smaller space. They hit the walls more often. This increases pressure if the temperature stays the same."], "worked": "Seal the end of a syringe containing air. Push the plunger in to reduce the space. The trapped air pushes back more strongly.", "question": "Why does squeezing the air in a sealed syringe increase its pressure?", "scheme": ["The same gas is in a smaller volume.", "Particles hit the walls more often.", "More frequent hits increase pressure."], "mistake": "Pressure comes from particles hitting a surface. Particles do not grow when heated.", "model": "particles", "id": "y7-unit-04-gas", "unit": "y7-unit-04", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Gas pressure", "definition": "The force on each unit area caused by gas particles hitting a surface."}, {"term": "Compression", "definition": "Squeezing something into a smaller volume."}], "quiz": {"q": "What happens when you heat gas in a sealed container that cannot expand?", "opts": ["Its particles stop hitting the walls.", "Its pressure rises.", "Its number of particles falls."], "a": 1, "why": "The particles move faster and hit the walls more often and harder."}, "misconception": {"q": "What happens when you heat gas in a sealed container that cannot expand? Sam answers: “Its number of particles falls.” Explain why this is wrong.", "m": 2, "ms": ["Its pressure rises.", "The particles move faster and hit the walls more often and harder."]}}, {"key": "atoms", "title": "Atoms, elements, compounds and mixtures", "notes": ["An atom is a tiny building block of matter. An element contains only one type of atom. Iron and oxygen are elements.", "A compound has different elements chemically joined together. A mixture contains substances that are not chemically joined to each other. Mixtures can often be separated using physical methods."], "worked": "Water is a compound of hydrogen and oxygen. Salt water is a mixture of salt and water. You can collect the water from salt water by distillation.", "question": "Use water and salt water to explain the difference between a compound and a mixture.", "scheme": ["Water contains hydrogen and oxygen chemically joined.", "Salt water contains salt mixed with water without a new compound forming.", "The substances in salt water can be separated by physical methods."], "mistake": "A mixture is not the same as a compound.", "model": null, "id": "y7-unit-04-atoms", "unit": "y7-unit-04", "year": 7, "number": 5, "marks": 3, "cards": [{"term": "Element", "definition": "A substance containing just one type of atom."}, {"term": "Compound", "definition": "A substance with different elements chemically joined in a fixed ratio."}, {"term": "Mixture", "definition": "Substances together without being chemically joined to each other."}], "quiz": {"q": "Which substance is a compound?", "opts": ["Pure water.", "Air.", "Iron."], "a": 0, "why": "Water contains hydrogen and oxygen atoms chemically joined together."}, "misconception": {"q": "Which substance is a compound? Sam answers: “Air.” Explain why this is wrong.", "m": 2, "ms": ["Pure water.", "Water contains hydrogen and oxygen atoms chemically joined together."]}}, {"key": "atoms", "title": "Atoms, elements, compounds and mixtures", "notes": ["An atom is a tiny building block of matter. An element contains only one type of atom. Iron and oxygen are elements.", "A compound has different elements chemically joined together. A mixture contains substances that are not chemically joined to each other. Mixtures can often be separated using physical methods."], "worked": "Water is a compound of hydrogen and oxygen. Salt water is a mixture of salt and water. You can collect the water from salt water by distillation.", "question": "Use water and salt water to explain the difference between a compound and a mixture.", "scheme": ["Water contains hydrogen and oxygen chemically joined.", "Salt water contains salt mixed with water without a new compound forming.", "The substances in salt water can be separated by physical methods."], "mistake": "A mixture is not the same as a compound.", "model": null, "id": "y7-unit-05-atoms", "unit": "y7-unit-05", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Element", "definition": "A substance containing just one type of atom."}, {"term": "Compound", "definition": "A substance with different elements chemically joined in a fixed ratio."}, {"term": "Mixture", "definition": "Substances together without being chemically joined to each other."}], "quiz": {"q": "Which substance is a compound?", "opts": ["Air.", "Iron.", "Pure water."], "a": 2, "why": "Water contains hydrogen and oxygen atoms chemically joined together."}, "misconception": {"q": "Which substance is a compound? Sam answers: “Air.” Explain why this is wrong.", "m": 2, "ms": ["Pure water.", "Water contains hydrogen and oxygen atoms chemically joined together."]}}, {"key": "solution", "title": "Dissolving and solutions", "notes": ["A solute is the substance that dissolves. A solvent is the liquid it dissolves in. Together they make a solution.", "Stirring can make a solid dissolve faster. Solubility is how much can dissolve at a given temperature. A saturated solution cannot dissolve any more solute at that temperature."], "worked": "Sugar is the solute when you dissolve it in water. The water is the solvent. Stirring helps the sugar dissolve more quickly.", "question": "Why can stirring make sugar dissolve faster without changing how much can dissolve at that temperature?", "scheme": ["Stirring brings fresh water into contact with the sugar.", "The sugar dissolves more quickly.", "The maximum amount that can dissolve at that temperature stays the same."], "mistake": "Dissolving faster does not always mean that more can dissolve.", "model": null, "id": "y7-unit-05-solution", "unit": "y7-unit-05", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Solute", "definition": "A substance that dissolves in a solvent."}, {"term": "Solvent", "definition": "A liquid that dissolves a solute."}, {"term": "Saturated solution", "definition": "A solution that cannot dissolve more solute at that temperature."}], "quiz": {"q": "What does stirring usually increase?", "opts": ["How quickly a solid dissolves.", "How much can dissolve at a fixed temperature.", "The number of atoms in the solid."], "a": 0, "why": "Stirring brings fresh solvent to the solid. It helps dissolving happen faster."}, "misconception": {"q": "What does stirring usually increase? Sam answers: “How much can dissolve at a fixed temperature.” Explain why this is wrong.", "m": 2, "ms": ["How quickly a solid dissolves.", "Stirring brings fresh solvent to the solid. It helps dissolving happen faster."]}}, {"key": "filter", "title": "Filtering and making crystals", "notes": ["Filtering separates an insoluble solid from a liquid. Insoluble means it does not dissolve. Filter paper lets the liquid through but traps the solid.", "The trapped solid is called the residue. The liquid that passes through is the filtrate. Crystallisation makes solid crystals from a solution."], "worked": "Add water to a dry mixture of sand and salt. Filter out the sand because it does not dissolve. Evaporate some water, then leave the salt solution to cool and form crystals.", "question": "How would you separate a dry mixture of sand and salt?", "scheme": ["Add water to dissolve the salt.", "Filter the mixture to remove sand.", "Evaporate some water and leave the solution to form salt crystals."], "mistake": "Ordinary filter paper does not trap salt that is dissolved in water.", "model": null, "id": "y7-unit-05-filter", "unit": "y7-unit-05", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Residue", "definition": "The solid left on filter paper."}, {"term": "Filtrate", "definition": "The liquid that passes through filter paper."}, {"term": "Crystallisation", "definition": "Making solid crystals from a solution."}], "quiz": {"q": "Can ordinary filter paper remove dissolved salt from water?", "opts": ["Yes. It traps all the dissolved salt.", "Yes. It turns the salt into sand.", "No. Dissolved salt passes through with the water."], "a": 2, "why": "Filtering traps insoluble solids, such as sand. It does not trap dissolved salt."}, "misconception": {"q": "Can ordinary filter paper remove dissolved salt from water? Sam answers: “Yes. It traps all the dissolved salt.” Explain why this is wrong.", "m": 2, "ms": ["No. Dissolved salt passes through with the water.", "Filtering traps insoluble solids, such as sand. It does not trap dissolved salt."]}}, {"key": "distil", "title": "Distillation and chromatography", "notes": ["Distillation separates and collects a liquid from a mixture. Heat the mixture so the liquid evaporates. Cool the vapour so it condenses back into a liquid.", "The condenser is the part that cools the vapour. Chromatography separates dissolved substances, such as colours in ink. Different substances travel different distances along the paper."], "worked": "Heat salt water to make water vapour. Cool the vapour in a condenser and collect liquid water. The salt stays behind because it does not evaporate with the water.", "question": "How does distillation collect pure water from salt water?", "scheme": ["Heat the salt water so water evaporates.", "Cool the water vapour so it condenses.", "Collect the liquid water, leaving the salt behind."], "mistake": "Evaporating water without collecting the vapour will not give you the water back.", "model": null, "id": "y7-unit-05-distil", "unit": "y7-unit-05", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Distillation", "definition": "Separating a liquid by evaporating it and then condensing its vapour."}, {"term": "Chromatography", "definition": "Separating dissolved substances because they travel different distances in a solvent."}], "quiz": {"q": "What does a condenser do during distillation?", "opts": ["Filters salt from water.", "Makes new water molecules.", "Cools vapour so it becomes liquid."], "a": 2, "why": "Cooling turns the vapour back into liquid so you can collect it."}, "misconception": {"q": "What does a condenser do during distillation? Sam answers: “Filters salt from water.” Explain why this is wrong.", "m": 2, "ms": ["Cools vapour so it becomes liquid.", "Cooling turns the vapour back into liquid so you can collect it."]}}, {"key": "energy", "title": "Energy stores and transfers", "notes": ["Energy can be stored in different ways. A moving object has a kinetic energy store. A battery has a chemical energy store.", "Energy can move between stores by heating, waves, electricity or forces. Energy is conserved: it cannot be created or destroyed. Energy often spreads into the surroundings and becomes less useful."], "worked": "A battery-powered lamp transfers energy electrically from the battery. Light carries energy away and warms objects that absorb it. The lamp also heats the air around it.", "question": "Describe the energy changes when a battery-powered lamp lights a room.", "scheme": ["Energy starts in the battery's chemical store.", "It is transferred electrically to the lamp.", "Light and heating transfer energy to the room and its contents."], "mistake": "“Wasted” energy has not disappeared. It has spread to less useful places.", "model": null, "id": "y7-unit-06-energy", "unit": "y7-unit-06", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Energy store", "definition": "A way energy is held, such as in a moving object or a battery."}, {"term": "Dissipation", "definition": "Energy spreading into the surroundings and becoming less useful."}], "quiz": {"q": "What happens to energy we call “wasted”?", "opts": ["It stops being conserved.", "It spreads into less useful stores, often in the surroundings.", "It is destroyed."], "a": 1, "why": "The energy still exists, but it is less useful for the job we wanted."}, "misconception": {"q": "What happens to energy we call “wasted”? Sam answers: “It is destroyed.” Explain why this is wrong.", "m": 2, "ms": ["It spreads into less useful stores, often in the surroundings.", "The energy still exists, but it is less useful for the job we wanted."]}}, {"key": "food-energy", "title": "Comparing energy in foods", "notes": ["Food has a chemical energy store. Burning a food sample can heat water. A larger water temperature rise can suggest more energy was transferred.", "Compare energy for the same mass of food, such as one gram. Some energy heats the air and equipment instead of the water. Only use your teacher's method for burning foods."], "worked": "Two food samples may have different masses. A bigger sample could heat more water even if it gives less energy per gram. Divide the energy by the mass to compare them fairly.", "question": "Give two problems with comparing foods by burning them below water. Explain how one affects the result.", "scheme": ["Some energy heats the air or the equipment rather than the water.", "The food may not burn completely.", "These effects make the measured energy lower than the energy available in the food."], "mistake": "The temperature rise alone is not the total energy in the food.", "model": null, "id": "y7-unit-06-food-energy", "unit": "y7-unit-06", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Chemical energy store", "definition": "Energy stored in substances such as food, fuels and batteries."}, {"term": "Energy per gram", "definition": "The energy for each gram of a substance."}], "quiz": {"q": "Why compare food energy per gram?", "opts": ["A water temperature rise measures all the food's energy perfectly.", "Every food contains the same energy.", "The food samples might have different masses."], "a": 2, "why": "Comparing equal masses makes the comparison fairer."}, "misconception": {"q": "Why compare food energy per gram? Sam answers: “A water temperature rise measures all the food's energy perfectly.” Explain why this is wrong.", "m": 2, "ms": ["The food samples might have different masses.", "Comparing equal masses makes the comparison fairer."]}}, {"key": "resources", "title": "Energy resources", "notes": ["Renewable resources are replaced naturally as we use them. Wind, sunlight and moving water are examples. Fossil fuels will run out because they form much more slowly than we use them.", "Burning fossil fuels releases carbon dioxide. Wind turbines make electricity without burning fuel. Wind output changes because the wind does not always blow. Nuclear fuel is non-renewable and produces radioactive waste. Nuclear power gives little carbon dioxide during electricity generation, but costs and waste still matter."], "worked": "A wind farm can reduce the fossil fuel used for electricity. On a calm day it produces little electricity. Other supplies or energy storage are then needed.", "question": "Give one advantage and one drawback of wind power compared with fossil-fuel power. Explain one.", "scheme": ["Wind is renewable and does not need burning fuel.", "It produces no carbon dioxide from burning fuel while operating.", "Output falls when there is little wind, so backup or storage is needed."], "mistake": "Renewable does not mean that an energy source is available all the time.", "model": null, "id": "y7-unit-06-resources", "unit": "y7-unit-06", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Renewable resource", "definition": "An energy resource that nature replaces as we use it."}, {"term": "Non-renewable resource", "definition": "An energy resource used faster than nature replaces it."}], "quiz": {"q": "Which is a renewable energy resource?", "opts": ["Natural gas.", "Uranium fuel.", "Wind."], "a": 2, "why": "Wind is replaced naturally, although it does not blow all the time."}, "misconception": {"q": "Which is a renewable energy resource? Sam answers: “Natural gas.” Explain why this is wrong.", "m": 2, "ms": ["Wind.", "Wind is replaced naturally, although it does not blow all the time."]}}, {"key": "power", "title": "Power, energy and electricity bills", "notes": ["Power tells you how quickly energy is transferred. Power is measured in watts, W. A kilowatt, kW, is 1000 watts.", "Electricity bills measure energy in kilowatt-hours, kWh. Energy in kWh = power in kW × time in hours. Cost = energy used × price per kWh."], "worked": "A 500 W device has a power of 0.5 kW. Used for 3 hours, it transfers 0.5 × 3 = 1.5 kWh. At 20 p per kWh, it costs 1.5 × 20 = 30 p.", "question": "A 500 W device runs for 3 hours. Electricity costs 20 p per kWh. Find the energy used and the cost.", "scheme": ["500 W = 0.5 kW.", "Energy used = 0.5 × 3 = 1.5 kWh.", "Cost = 1.5 × 20 = 30 p."], "mistake": "kW measures power. kWh measures energy.", "model": null, "id": "y7-unit-06-power", "unit": "y7-unit-06", "year": 7, "number": 4, "marks": 3, "cards": [{"term": "Power", "definition": "Energy transferred each second."}, {"term": "Kilowatt-hour", "definition": "The energy transferred by a 1 kW device in one hour."}], "quiz": {"q": "What is measured in kilowatt-hours, kWh?", "opts": ["Energy.", "Power.", "Current."], "a": 0, "why": "Power × time gives energy. A kilowatt alone measures power."}, "misconception": {"q": "What is measured in kilowatt-hours, kWh? Sam answers: “Power.” Explain why this is wrong.", "m": 2, "ms": ["Energy.", "Power × time gives energy. A kilowatt alone measures power."]}}, {"key": "energy", "title": "Energy stores and transfers", "notes": ["Energy can be stored in different ways. A moving object has a kinetic energy store. A battery has a chemical energy store.", "Energy can move between stores by heating, waves, electricity or forces. Energy is conserved: it cannot be created or destroyed. Energy often spreads into the surroundings and becomes less useful."], "worked": "A battery-powered lamp transfers energy electrically from the battery. Light carries energy away and warms objects that absorb it. The lamp also heats the air around it.", "question": "Describe the energy changes when a battery-powered lamp lights a room.", "scheme": ["Energy starts in the battery's chemical store.", "It is transferred electrically to the lamp.", "Light and heating transfer energy to the room and its contents."], "mistake": "“Wasted” energy has not disappeared. It has spread to less useful places.", "model": null, "id": "y7-unit-07-energy", "unit": "y7-unit-07", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Energy store", "definition": "A way energy is held, such as in a moving object or a battery."}, {"term": "Dissipation", "definition": "Energy spreading into the surroundings and becoming less useful."}], "quiz": {"q": "What happens to energy we call “wasted”?", "opts": ["It spreads into less useful stores, often in the surroundings.", "It is destroyed.", "It stops being conserved."], "a": 0, "why": "The energy still exists, but it is less useful for the job we wanted."}, "misconception": {"q": "What happens to energy we call “wasted”? Sam answers: “It is destroyed.” Explain why this is wrong.", "m": 2, "ms": ["It spreads into less useful stores, often in the surroundings.", "The energy still exists, but it is less useful for the job we wanted."]}}, {"key": "efficiency", "title": "Useful and wasted energy", "notes": ["A device transfers energy in useful and unwanted ways. An efficient device transfers a larger share in the useful way. Efficiency cannot be more than 100%.", "Efficiency = useful energy out ÷ total energy in. Multiply by 100 to give a percentage. A Sankey diagram uses arrow widths to show how much energy goes each way."], "worked": "A motor takes in 600 J and gives 450 J of useful movement. Efficiency = 450 ÷ 600 × 100 = 75%. The other 150 J is transferred in unwanted ways, such as heating.", "question": "A motor takes in 600 J and gives 450 J of useful movement. Find its efficiency and the unwanted energy transfer.", "scheme": ["Efficiency = 450 ÷ 600.", "Efficiency = 75%.", "Unwanted transfer = 600 − 450 = 150 J."], "mistake": "Even a very efficient machine cannot give out more energy than it takes in.", "model": null, "id": "y7-unit-07-efficiency", "unit": "y7-unit-07", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Efficiency", "definition": "The useful energy output divided by the total energy input."}, {"term": "Sankey diagram", "definition": "A diagram with arrow widths showing amounts of energy transferred."}], "quiz": {"q": "A device gives 20 J of useful energy from 100 J input. What is its efficiency?", "opts": ["500%.", "20%.", "80%."], "a": 1, "why": "20 ÷ 100 × 100 = 20%."}, "misconception": {"q": "A device gives 20 J of useful energy from 100 J input. What is its efficiency? Sam answers: “80%.” Explain why this is wrong.", "m": 2, "ms": ["20%.", "20 ÷ 100 × 100 = 20%."]}}, {"key": "variation", "title": "Differences between living things", "notes": ["Variation means differences between living things of the same species. Some differences come from genes passed on by parents. Others come from surroundings and experiences.", "Height is continuous variation: people can have many values within a range. Blood group is discontinuous variation: people fit into separate groups. Many features depend on both genes and the environment."], "worked": "Arm span is measured on a scale with many possible values. ABO blood group has the groups A, B, AB and O. A scar is an example of a difference caused by experience.", "question": "Compare continuous and discontinuous variation. Give an example of each.", "scheme": ["Continuous variation has values across a range, such as arm span.", "Discontinuous variation has separate groups, such as ABO blood group.", "A measurement can have values between two others, but the blood groups are separate categories."], "mistake": "Most features are not caused by genes alone or the environment alone.", "model": null, "id": "y7-unit-08-variation", "unit": "y7-unit-08", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Variation", "definition": "Differences between living things of the same species."}, {"term": "Continuous variation", "definition": "Differences with values across a range, such as height."}, {"term": "Discontinuous variation", "definition": "Differences in separate groups, such as ABO blood group."}], "quiz": {"q": "Which shows continuous variation?", "opts": ["Whether a feature is present or absent.", "Arm span.", "ABO blood group."], "a": 1, "why": "Arm span can have many measured values within a range."}, "misconception": {"q": "Which shows continuous variation? Sam answers: “ABO blood group.” Explain why this is wrong.", "m": 2, "ms": ["Arm span.", "Arm span can have many measured values within a range."]}}, {"key": "adaptation", "title": "Adaptations for survival", "notes": ["An adaptation is a feature that helps a living thing survive and reproduce. Inherited adaptations can be passed on to offspring. Different environments favour different features.", "Thick fur helps a mammal keep warm. A cactus has features that reduce water loss. A useful feature in one place may be unhelpful somewhere else."], "worked": "Thick fur traps air near an animal's skin. This slows energy transfer to cold surroundings. In a hot place, thick fur could make cooling down harder.", "question": "How does thick fur help a mammal in a cold place? Why might it be less helpful in a hot place?", "scheme": ["Fur traps air and reduces heat loss.", "This helps the mammal stay warm in the cold.", "In hot conditions it can make losing unwanted heat harder."], "mistake": "Living things do not choose a new inherited feature because they need it.", "model": null, "id": "y7-unit-08-adaptation", "unit": "y7-unit-08", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Adaptation", "definition": "An inherited feature that helps a living thing survive and reproduce in its environment."}, {"term": "Selection pressure", "definition": "Something in the environment that affects which organisms survive and reproduce."}], "quiz": {"q": "Which statement about inherited adaptations is correct?", "opts": ["They can become more common over generations.", "An animal chooses a new gene when it needs one.", "They are helpful in every environment."], "a": 0, "why": "A helpful inherited feature can be passed on by survivors to their offspring."}, "misconception": {"q": "Which statement about inherited adaptations is correct? Sam answers: “An animal chooses a new gene when it needs one.” Explain why this is wrong.", "m": 2, "ms": ["They can become more common over generations.", "A helpful inherited feature can be passed on by survivors to their offspring."]}}, {"key": "data", "title": "Tables, graphs and conclusions", "notes": ["Put measurements in a results table. Label each column with the quantity and its unit. A graph helps you spot a pattern.", "Use a line graph for measurements such as time and temperature. Use a bar chart for separate groups, such as different materials. A conclusion answers your question using your results."], "worked": "Suppose sugar dissolves in 40 seconds in cool water and 20 seconds in warm water. The warmer water gave a shorter dissolving time. Use these numbers as evidence in your conclusion.", "question": "What graph would show water temperature and sugar dissolving time? How would you write a good conclusion?", "scheme": ["Use a line or scatter graph with temperature on the horizontal axis.", "Put dissolving time on the vertical axis and label both units.", "Describe the pattern and use numbers from the results."], "mistake": "A conclusion needs evidence. Do not just say your prediction was right.", "model": null, "id": "y7-unit-08-data", "unit": "y7-unit-08", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Continuous data", "definition": "Measurements with values anywhere within a range, such as height."}, {"term": "Discrete data", "definition": "Separate counts or values, such as the number of leaves."}, {"term": "Conclusion", "definition": "An answer to your test question, supported by your results."}], "quiz": {"q": "What makes a good conclusion?", "opts": ["Choose your favourite result and ignore the others.", "Leave units off the graph.", "Describe a pattern and use numbers from the results."], "a": 2, "why": "Numbers from the results give evidence for the pattern you describe."}, "misconception": {"q": "What makes a good conclusion? Sam answers: “Choose your favourite result and ignore the others.” Explain why this is wrong.", "m": 2, "ms": ["Describe a pattern and use numbers from the results.", "Numbers from the results give evidence for the pattern you describe."]}}, {"key": "puberty", "title": "Puberty and reproductive organs", "notes": ["Puberty is when a child's body develops towards an adult body. Chemical messages called hormones control these changes. The timing is different for different people.", "Testes produce sperm cells. Ovaries produce egg cells. A baby develops in the uterus, also called the womb. Sperm ducts carry sperm, and the penis delivers semen. Oviducts carry eggs, and the vagina connects the uterus to the outside of the body. Adolescence also includes emotional and social changes."], "worked": "Sperm and eggs are sex cells, called gametes. A sperm cell can join with an egg cell at fertilisation. The resulting embryo can later grow in the uterus.", "question": "What are the jobs of the testes, ovaries and uterus?", "scheme": ["Testes produce sperm.", "Ovaries produce egg cells.", "The uterus is where an embryo can develop into a baby."], "mistake": "Puberty does not happen at exactly the same age for everyone.", "model": null, "id": "y7-unit-09-puberty", "unit": "y7-unit-09", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Puberty", "definition": "Body changes that prepare a child for adulthood and reproduction."}, {"term": "Gamete", "definition": "A sex cell, such as a sperm or egg, with half the usual chromosome number."}], "quiz": {"q": "Where are sperm produced?", "opts": ["In the oviducts.", "In the testes.", "In the uterus."], "a": 1, "why": "Testes produce sperm and ovaries produce egg cells."}, "misconception": {"q": "Where are sperm produced? Sam answers: “In the uterus.” Explain why this is wrong.", "m": 2, "ms": ["In the testes.", "Testes produce sperm and ovaries produce egg cells."]}}, {"key": "cycle", "title": "The menstrual cycle", "notes": ["The menstrual cycle prepares the uterus for a possible pregnancy. The lining of the uterus thickens. Ovulation is the release of an egg from an ovary.", "If pregnancy does not happen, the lining breaks down. The lining and blood leave through the vagina during a period. This is called menstruation."], "worked": "Diagrams often show a 28-day cycle. Real cycles can be shorter or longer. The timing of ovulation can also change.", "question": "What are menstruation and ovulation? Why does a 28-day diagram not describe every cycle?", "scheme": ["Menstruation is when the uterus lining leaves the body during a period.", "Ovulation is the release of an egg from an ovary.", "Cycle length and ovulation timing vary between people and cycles."], "mistake": "Ovulation and a period are different events.", "model": null, "id": "y7-unit-09-cycle", "unit": "y7-unit-09", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Menstruation", "definition": "When the uterus lining leaves the body during a period."}, {"term": "Ovulation", "definition": "The release of an egg from an ovary."}], "quiz": {"q": "Why does a 28-day diagram not describe every menstrual cycle?", "opts": ["Every cycle is exactly 28 days.", "Ovulation is the same as a period.", "Cycle length and the timing of ovulation vary."], "a": 2, "why": "A diagram shows a typical pattern. Real cycles can be shorter or longer."}, "misconception": {"q": "Why does a 28-day diagram not describe every menstrual cycle? Sam answers: “Every cycle is exactly 28 days.” Explain why this is wrong.", "m": 2, "ms": ["Cycle length and the timing of ovulation vary.", "A diagram shows a typical pattern. Real cycles can be shorter or longer."]}}, {"key": "pregnancy", "title": "Fertilisation and pregnancy", "notes": ["Fertilisation happens when the nuclei of a sperm and an egg join. It usually happens in an oviduct, also called a fallopian tube. The fertilised egg starts dividing to form an embryo.", "The embryo travels to the uterus. It attaches to the uterus lining: this is implantation. The placenta exchanges substances between the mother and developing baby."], "worked": "Oxygen and nutrients pass towards the baby through the placenta. Waste substances pass away from the baby. The mother's blood and the baby's blood do not normally mix directly.", "question": "How are fertilisation and implantation different? Give one job of the placenta.", "scheme": ["Fertilisation joins sperm and egg nuclei, usually in an oviduct.", "Implantation is the embryo attaching to the uterus lining.", "The placenta passes oxygen or nutrients to the baby, or removes waste."], "mistake": "Fertilisation happens before implantation.", "model": null, "id": "y7-unit-09-pregnancy", "unit": "y7-unit-09", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Fertilisation", "definition": "The joining of a sperm-cell nucleus and an egg-cell nucleus."}, {"term": "Implantation", "definition": "An embryo attaching to the uterus lining."}, {"term": "Placenta", "definition": "An organ that exchanges nutrients, oxygen and waste between the mother and developing baby."}], "quiz": {"q": "Where does fertilisation usually happen in humans?", "opts": ["In the uterus lining during implantation.", "In the placenta.", "In an oviduct, also called a fallopian tube."], "a": 2, "why": "The embryo travels to the uterus and implants there after fertilisation."}, "misconception": {"q": "Where does fertilisation usually happen in humans? Sam answers: “In the uterus lining during implantation.” Explain why this is wrong.", "m": 2, "ms": ["In an oviduct, also called a fallopian tube.", "The embryo travels to the uterus and implants there after fertilisation."]}}, {"key": "flower", "title": "Flowers and pollination", "notes": ["Flowers contain the parts needed for plant reproduction. Anthers make pollen. The stigma is the surface that receives pollen.", "Pollination moves pollen from an anther to a stigma. Insects can carry pollen between flowers. Wind can also carry pollen."], "worked": "Insect-pollinated flowers often have bright petals, scent and nectar. These attract insects that carry pollen. Wind-pollinated flowers often release lots of small, light pollen grains.", "question": "Give one feature of a wind-pollinated flower and one of an insect-pollinated flower. Explain how a feature helps.", "scheme": ["Wind-pollinated flowers may produce lots of light pollen.", "Insect-pollinated flowers may have bright petals, nectar or scent.", "The feature helps wind or insects carry pollen to a stigma."], "mistake": "Pollination is moving pollen. Fertilisation happens later.", "model": null, "id": "y7-unit-10-flower", "unit": "y7-unit-10", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Pollination", "definition": "Moving pollen from an anther to a stigma."}, {"term": "Anther", "definition": "The part of a flower that makes pollen."}, {"term": "Stigma", "definition": "The flower surface that receives pollen."}], "quiz": {"q": "Which example is pollination?", "opts": ["A seed starting to grow.", "Pollen landing on a suitable stigma.", "Sperm and egg nuclei joining."], "a": 1, "why": "Pollination is moving pollen. Fertilisation is joining sex-cell nuclei later."}, "misconception": {"q": "Which example is pollination? Sam answers: “Sperm and egg nuclei joining.” Explain why this is wrong.", "m": 2, "ms": ["Pollen landing on a suitable stigma.", "Pollination is moving pollen. Fertilisation is joining sex-cell nuclei later."]}}, {"key": "seed", "title": "Making and spreading seeds", "notes": ["After pollination, a pollen tube grows towards an ovule. A male sex-cell nucleus travels down the tube. It joins the egg-cell nucleus at fertilisation.", "A fertilised ovule can develop into a seed. The ovary often develops into a fruit. Seeds can be spread by wind, water or animals."], "worked": "A dandelion seed has a light parachute-like structure. Wind carries it away from the parent plant. The new plant then has less competition with its parent.", "question": "Describe the steps from pollination to a seed forming.", "scheme": ["Pollen reaches the stigma.", "A pollen tube grows and a male nucleus joins the egg nucleus.", "The fertilised ovule develops into a seed."], "mistake": "A seed develops from an ovule, not from a petal.", "model": null, "id": "y7-unit-10-seed", "unit": "y7-unit-10", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Seed dispersal", "definition": "Spreading seeds away from the parent plant."}, {"term": "Ovule", "definition": "A part inside the flower's ovary that can become a seed after fertilisation."}], "quiz": {"q": "Which flower part develops into a seed after fertilisation?", "opts": ["The whole anther.", "A petal.", "An ovule."], "a": 2, "why": "A fertilised ovule becomes a seed. The ovary often becomes a fruit."}, "misconception": {"q": "Which flower part develops into a seed after fertilisation? Sam answers: “The whole anther.” Explain why this is wrong.", "m": 2, "ms": ["An ovule.", "A fertilised ovule becomes a seed. The ovary often becomes a fruit."]}}, {"key": "germination", "title": "When seeds start to grow", "notes": ["Germination is when a seed starts growing. Most seeds need water, oxygen and a suitable temperature. They use stored food to start with.", "Water starts processes inside the seed. Oxygen is needed for aerobic respiration. Respiration releases energy for growth."], "worked": "A seed can start growing on damp cotton wool. It does not need soil as its first food supply. Many seeds can germinate without light.", "question": "Why does a seed need water and oxygen to germinate?", "scheme": ["Water allows processes inside the seed to start.", "Oxygen is used in aerobic respiration.", "Respiration releases energy needed for growth."], "mistake": "Most seeds use stored food at first. Soil is not their food.", "model": null, "id": "y7-unit-10-germination", "unit": "y7-unit-10", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Germination", "definition": "When a seed starts to grow into a seedling."}, {"term": "Control group", "definition": "A comparison group used to help find the effect of the thing being tested."}], "quiz": {"q": "What do most seeds need to germinate?", "opts": ["Light in every case.", "Soil as their food supply.", "Water, oxygen and a suitable temperature."], "a": 2, "why": "Seeds use stored food at first. Many can germinate without light."}, "misconception": {"q": "What do most seeds need to germinate? Sam answers: “Light in every case.” Explain why this is wrong.", "m": 2, "ms": ["Water, oxygen and a suitable temperature.", "Seeds use stored food at first. Many can germinate without light."]}}, {"key": "reaction", "title": "Chemical reactions and physical changes", "notes": ["A chemical reaction makes one or more new substances. The starting substances are reactants. The new substances are products.", "A physical change does not make a new substance. Melting and freezing are physical changes. Bubbles or a colour change can be clues to a reaction, but check the evidence."], "worked": "Burning magnesium makes a new substance, magnesium oxide. Melting ice still leaves you with water. Boiling water makes bubbles without a chemical reaction.", "question": "Give one chemical reaction and one physical change. Explain the difference.", "scheme": ["Give a reaction that makes a new substance, such as burning magnesium.", "Give a physical change, such as melting ice.", "A physical change does not make a new substance."], "mistake": "Bubbles alone do not prove that a chemical reaction happened.", "model": null, "id": "y7-unit-11-reaction", "unit": "y7-unit-11", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Reactant", "definition": "A starting substance in a chemical reaction."}, {"term": "Product", "definition": "A new substance made in a chemical reaction."}, {"term": "Physical change", "definition": "A change that does not make a new substance."}], "quiz": {"q": "Which observation alone does not prove a chemical reaction?", "opts": ["Bubbles appearing.", "Clear evidence of a new substance forming.", "A test confirming a different chemical substance."], "a": 0, "why": "Boiling water also makes bubbles, without making a new substance."}, "misconception": {"q": "Which observation alone does not prove a chemical reaction? Sam answers: “Clear evidence of a new substance forming.” Explain why this is wrong.", "m": 2, "ms": ["Bubbles appearing.", "Boiling water also makes bubbles, without making a new substance."]}}, {"key": "acid", "title": "Acids, alkalis and pH", "notes": ["Acids have a pH below 7. Alkalis have a pH above 7. A neutral solution has a pH of 7 at room temperature.", "An indicator changes colour to show pH. Concentrated means a lot of dissolved substance in a given volume. Dilute means less dissolved substance in the same volume."], "worked": "Strength and concentration mean different things. Acid strength describes how much the acid splits into charged particles in water. A strong acid can still be dilute if it contains lots of water.", "question": "A pupil says “concentrated” and “strong” mean the same thing for acids. Explain the difference.", "scheme": ["Concentration describes how much acid is in a given volume of solution.", "Strength describes how much the acid splits into charged particles in water.", "A strong acid can be dilute, so the words do not mean the same thing."], "mistake": "A concentrated acid is not always a strong acid.", "model": null, "id": "y7-unit-11-acid", "unit": "y7-unit-11", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Acid", "definition": "A substance that gives a solution with pH below 7 in water."}, {"term": "Alkali", "definition": "A base that dissolves in water."}, {"term": "Concentration", "definition": "How much dissolved substance there is in a given volume of solution."}], "quiz": {"q": "What does “concentrated” tell you about an acid solution?", "opts": ["How much acid there is in a given volume of solution.", "How much of the acid splits into charged particles.", "That the acid must be strong."], "a": 0, "why": "Concentration describes the amount of acid. Strength describes a different property of the acid."}, "misconception": {"q": "What does “concentrated” tell you about an acid solution? Sam answers: “How much of the acid splits into charged particles.” Explain why this is wrong.", "m": 2, "ms": ["How much acid there is in a given volume of solution.", "Concentration describes the amount of acid. Strength describes a different property of the acid."]}}, {"key": "neutral", "title": "Neutralisation and salts", "notes": ["An acid reacts with a base in a neutralisation reaction. An alkali is a base that dissolves in water. Acid + metal oxide → salt + water.", "The acid helps decide the salt's name. Hydrochloric acid makes chlorides. Sulfuric acid makes sulfates and nitric acid makes nitrates."], "worked": "Magnesium oxide reacts with hydrochloric acid. The products are magnesium chloride and water. The acid and base have made a salt.", "question": "Magnesium oxide reacts with hydrochloric acid. Name the salt and the other product.", "scheme": ["The salt contains magnesium.", "The salt is magnesium chloride.", "The other product is water."], "mistake": "A salt does not always mean the table salt you put on food.", "model": null, "id": "y7-unit-11-neutral", "unit": "y7-unit-11", "year": 7, "number": 3, "marks": 3, "cards": [{"term": "Neutralisation", "definition": "A reaction between an acid and a base."}, {"term": "Salt", "definition": "A type of compound made in reactions such as acid reacting with a metal oxide."}], "quiz": {"q": "What type of salt does hydrochloric acid make?", "opts": ["A nitrate.", "A chloride.", "A sulfate."], "a": 1, "why": "Hydrochloric acid makes chlorides. Sulfuric acid makes sulfates."}, "misconception": {"q": "What type of salt does hydrochloric acid make? Sam answers: “A sulfate.” Explain why this is wrong.", "m": 2, "ms": ["A chloride.", "Hydrochloric acid makes chlorides. Sulfuric acid makes sulfates."]}}, {"key": "metals", "title": "Metals and reactivity", "notes": ["Metals usually conduct heat and electricity well. Many metals react with oxygen to make metal oxides. Gaining oxygen is called oxidation.", "Some metals react more easily than others. A more reactive metal can replace a less reactive metal in a compound. This is called displacement. Most metals can be shaped without breaking. Some non-metals are exceptions to the usual rules: graphite conducts electricity."], "worked": "Zinc is more reactive than copper. Zinc placed in copper sulfate solution can form zinc sulfate. Copper is left as a solid.", "question": "Zinc is more reactive than copper. What happens when zinc is put in copper sulfate solution? Explain why.", "scheme": ["Zinc displaces copper.", "Zinc sulfate and copper form.", "Zinc replaces copper because it is more reactive."], "mistake": "A less reactive metal cannot simply displace a more reactive one.", "model": null, "id": "y7-unit-12-metals", "unit": "y7-unit-12", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Displacement", "definition": "A more reactive element replacing a less reactive element in a compound."}, {"term": "Oxidation", "definition": "A reaction in which a substance gains oxygen, in these examples."}], "quiz": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate?", "opts": ["No.", "Yes, because all metals displace each other.", "Yes, because copper is coloured."], "a": 0, "why": "The more reactive metal displaces the less reactive metal, not the other way around."}, "misconception": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate? Sam answers: “Yes, because all metals displace each other.” Explain why this is wrong.", "m": 2, "ms": ["No.", "The more reactive metal displaces the less reactive metal, not the other way around."]}}, {"key": "metal-acid", "title": "Metals reacting with acids", "notes": ["Many metals react with dilute acids. These reactions make a salt and hydrogen gas. More reactive metals usually react faster under the same conditions.", "The acid helps decide which salt forms. Hydrochloric acid makes a chloride. Sulfuric acid makes a sulfate."], "worked": "Magnesium and dilute sulfuric acid make magnesium sulfate and hydrogen. A small sample of hydrogen makes a squeaky pop with a lighted splint. Only test gases using your teacher's safety instructions.", "question": "What forms when magnesium reacts with dilute sulfuric acid? How would you test the gas safely in the lab?", "scheme": ["Magnesium sulfate forms.", "Hydrogen gas forms.", "A teacher-supervised test with a lighted splint gives a squeaky pop."], "mistake": "The salt name depends on the acid, not just the metal.", "model": null, "id": "y7-unit-12-metal-acid", "unit": "y7-unit-12", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Reactivity series", "definition": "A list of metals ordered by how readily they react."}, {"term": "Hydrogen test", "definition": "A small gas sample makes a squeaky pop with a lighted splint in a teacher-supervised test."}], "quiz": {"q": "What forms when magnesium reacts with dilute hydrochloric acid?", "opts": ["Only water.", "Magnesium chloride and hydrogen.", "Magnesium sulfate and oxygen."], "a": 1, "why": "A suitable metal and dilute acid make a salt and hydrogen gas."}, "misconception": {"q": "What forms when magnesium reacts with dilute hydrochloric acid? Sam answers: “Magnesium sulfate and oxygen.” Explain why this is wrong.", "m": 2, "ms": ["Magnesium chloride and hydrogen.", "A suitable metal and dilute acid make a salt and hydrogen gas."]}}, {"key": "charge", "title": "Static electricity", "notes": ["Electrons are tiny particles with a negative charge. Rubbing some materials moves electrons from one surface to another. An object that gains electrons becomes negatively charged.", "An object that loses electrons becomes positively charged. Like charges repel: they push apart. Opposite charges attract: they pull together."], "worked": "Two plastic rods both gain electrons when rubbed. Both rods are negatively charged. They repel because their charges are alike.", "question": "Two rods both gain electrons. Explain why they push away from each other.", "scheme": ["Electrons carry negative charge.", "Both rods become negatively charged.", "Like charges repel."], "mistake": "In these examples, electrons move. Positive charge does not move from one rod to another.", "model": null, "id": "y7-unit-13-charge", "unit": "y7-unit-13", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Electron", "definition": "A tiny particle with a negative electric charge."}, {"term": "Static charge", "definition": "A build-up of electric charge on an object."}], "quiz": {"q": "An insulating rod gains electrons. What charge does it have?", "opts": ["Always zero.", "Negative.", "Positive."], "a": 1, "why": "Electrons are negative, so gaining extra electrons makes the rod negatively charged."}, "misconception": {"q": "An insulating rod gains electrons. What charge does it have? Sam answers: “Positive.” Explain why this is wrong.", "m": 2, "ms": ["Negative.", "Electrons are negative, so gaining extra electrons makes the rod negatively charged."]}}, {"key": "current", "title": "Electric current and circuits", "notes": ["An electric current is a flow of charge. A complete circuit is needed for a steady current. An ammeter measures current in amperes, A.", "Connect an ammeter in series: in the same path as the current. Current is the same all around a single series loop. At a junction, the current splits between branches. Circuit diagrams use standard symbols to show how parts are connected."], "worked": "Two parallel branches carry 0.4 A and 0.6 A. The current before the split is 0.4 + 0.6 = 1.0 A. The same total current returns after the branches join.", "question": "Two parallel branches carry 0.4 A and 0.6 A. Find the supply current and explain your method.", "scheme": ["Add the branch currents.", "0.4 + 0.6 = 1.0 A.", "The total current into a junction equals the total current out."], "mistake": "Current is not used up by a bulb.", "model": "circuit", "id": "y7-unit-13-current", "unit": "y7-unit-13", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Current", "definition": "The amount of electric charge flowing each second."}, {"term": "Ammeter", "definition": "An instrument connected in series to measure current."}], "quiz": {"q": "What happens to current at a junction?", "opts": ["Current is used up.", "Each branch always gets all the supply current.", "Total current in equals total current out."], "a": 2, "why": "Charge does not disappear. The branch currents add to the current before the split."}, "misconception": {"q": "What happens to current at a junction? Sam answers: “Current is used up.” Explain why this is wrong.", "m": 2, "ms": ["Total current in equals total current out.", "Charge does not disappear. The branch currents add to the current before the split."]}}, {"key": "voltage", "title": "Voltage and resistance", "notes": ["Potential difference is also called voltage. It tells us the energy transferred by each coulomb of charge. Voltage is measured in volts, V.", "A voltmeter measures voltage across a component. Resistance describes how much a component limits the current. Resistance = voltage ÷ current, measured in ohms, Ω. A coulomb is a unit of electric charge. Voltages across parts of a series circuit add up to the supply voltage. Parallel branches across the same two points have the same voltage."], "worked": "A resistor has 12 V across it and a current of 2 A. Its resistance is 12 ÷ 2 = 6 Ω. Connect the voltmeter across the resistor, in parallel.", "question": "A resistor has 12 V across it and carries 2 A. Find its resistance. How should the voltmeter be connected?", "scheme": ["Use resistance = voltage ÷ current.", "12 ÷ 2 = 6 Ω.", "Connect the voltmeter in parallel across the resistor."], "mistake": "A voltmeter goes across a component, not in the same path as an ammeter.", "model": "circuit", "id": "y7-unit-14-voltage", "unit": "y7-unit-14", "year": 7, "number": 1, "marks": 3, "cards": [{"term": "Potential difference", "definition": "Energy transferred per coulomb (a unit of charge), also called voltage."}, {"term": "Resistance", "definition": "How much a component limits current; calculated as voltage divided by current."}, {"term": "Voltmeter", "definition": "An instrument connected across a component to measure voltage."}], "quiz": {"q": "How should you connect a voltmeter?", "opts": ["With only one lead connected.", "In parallel across a component.", "In series in place of a wire."], "a": 1, "why": "Voltage is measured between two points, so the voltmeter goes across the component."}, "misconception": {"q": "How should you connect a voltmeter? Sam answers: “In series in place of a wire.” Explain why this is wrong.", "m": 2, "ms": ["In parallel across a component.", "Voltage is measured between two points, so the voltmeter goes across the component."]}}, {"key": "current", "title": "Electric current and circuits", "notes": ["An electric current is a flow of charge. A complete circuit is needed for a steady current. An ammeter measures current in amperes, A.", "Connect an ammeter in series: in the same path as the current. Current is the same all around a single series loop. At a junction, the current splits between branches. Circuit diagrams use standard symbols to show how parts are connected."], "worked": "Two parallel branches carry 0.4 A and 0.6 A. The current before the split is 0.4 + 0.6 = 1.0 A. The same total current returns after the branches join.", "question": "Two parallel branches carry 0.4 A and 0.6 A. Find the supply current and explain your method.", "scheme": ["Add the branch currents.", "0.4 + 0.6 = 1.0 A.", "The total current into a junction equals the total current out."], "mistake": "Current is not used up by a bulb.", "model": "circuit", "id": "y7-unit-14-current", "unit": "y7-unit-14", "year": 7, "number": 2, "marks": 3, "cards": [{"term": "Current", "definition": "The amount of electric charge flowing each second."}, {"term": "Ammeter", "definition": "An instrument connected in series to measure current."}], "quiz": {"q": "What happens to current at a junction?", "opts": ["Current is used up.", "Each branch always gets all the supply current.", "Total current in equals total current out."], "a": 2, "why": "Charge does not disappear. The branch currents add to the current before the split."}, "misconception": {"q": "What happens to current at a junction? Sam answers: “Current is used up.” Explain why this is wrong.", "m": 2, "ms": ["Total current in equals total current out.", "Charge does not disappear. The branch currents add to the current before the split."]}}, {"key": "foodweb", "title": "Food chains and food webs", "notes": ["A food chain shows what eats what. A producer, such as a green plant, makes its own food. A consumer gets food by eating other living things.", "Arrows point from the food towards the eater. They show the direction energy is transferred. Several linked food chains make a food web. Other food sources and competition can change the outcome in a real food web."], "worked": "Consider algae → water flea → small fish. Fewer water fleas may mean less algae is eaten. Small fish may have less food and their numbers may fall.", "question": "In algae → water flea → small fish, what might happen to algae and fish if water flea numbers fall?", "scheme": ["Less algae may be eaten, so algae may increase.", "Fish have fewer water fleas to eat.", "Fish numbers may fall if they cannot find enough other food."], "mistake": "An arrow points towards the animal eating the food, not towards its food.", "model": null, "id": "y8-unit-01-foodweb", "unit": "y8-unit-01", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Producer", "definition": "A living thing that makes its own food, usually by photosynthesis."}, {"term": "Consumer", "definition": "A living thing that gets food by eating other living things."}, {"term": "Food web", "definition": "Several food chains linked together."}], "quiz": {"q": "Which way does an arrow point in a food chain?", "opts": ["From the eater towards its food.", "Always towards the producer.", "From the food towards the eater."], "a": 2, "why": "Arrows show the direction that energy passes through the chain."}, "misconception": {"q": "Which way does an arrow point in a food chain? Sam answers: “From the eater towards its food.” Explain why this is wrong.", "m": 2, "ms": ["From the food towards the eater.", "Arrows show the direction that energy passes through the chain."]}}, {"key": "ecosystem", "title": "Habitats, competition and quadrats", "notes": ["An ecosystem includes living things and their surroundings. Living things compete when they need the same limited resource. Plants may compete for light, water and space.", "A quadrat is a square frame used to count plants in a small area. Place it at random points so you do not choose only plant-rich patches. Use several samples to make a better estimate."], "worked": "Five 1 m² quadrats contain 25 daisies in total. The mean is 25 ÷ 5 = 5 daisies per m². For a similar 100 m² field, estimate 5 × 100 = 500 daisies.", "question": "How could you use quadrats to estimate the number of daisies in a field?", "scheme": ["Place equal-sized quadrats at random points.", "Count daisies and calculate the mean number per square metre.", "Multiply by field area and say the answer is an estimate."], "mistake": "Choosing only places with lots of daisies will give an unfair estimate.", "model": null, "id": "y8-unit-01-ecosystem", "unit": "y8-unit-01", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Ecosystem", "definition": "Living things in an area and the surroundings they interact with."}, {"term": "Competition", "definition": "Living things needing the same limited resource."}, {"term": "Quadrat", "definition": "A frame marking a known area for counting plants or other organisms."}], "quiz": {"q": "Why place quadrats at random points?", "opts": ["To remove the need for repeats.", "To avoid choosing only patches that support your prediction.", "To make every count identical."], "a": 1, "why": "Random points reduce the effect of the person choosing where to count."}, "misconception": {"q": "Why place quadrats at random points? Sam answers: “To make every count identical.” Explain why this is wrong.", "m": 2, "ms": ["To avoid choosing only patches that support your prediction.", "Random points reduce the effect of the person choosing where to count."]}}, {"key": "speed", "title": "Measuring and calculating speed", "notes": ["Speed tells you how far something travels each second. Average speed = total distance ÷ total time. Use metres and seconds to get metres per second, m/s.", "Measure a known distance and time the journey. Repeat the test and compare the readings. Electronic timing can reduce errors caused by reaction time."], "worked": "A trolley travels 1.8 m in 3 seconds. Average speed = 1.8 ÷ 3 = 0.6 m/s. This does not mean it had exactly that speed at every moment.", "question": "A trolley travels 2.4 m in 4 seconds. Find its average speed and suggest a way to improve timing.", "scheme": ["Use average speed = distance ÷ time.", "2.4 ÷ 4 = 0.6 m/s.", "Use electronic timing or time a longer distance to reduce the effect of reaction time."], "mistake": "Average speed describes the whole journey, not every moment of it.", "model": null, "id": "y8-unit-02-speed", "unit": "y8-unit-02", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Average speed", "definition": "Total distance travelled divided by total time."}, {"term": "Repeat", "definition": "Taking another measurement using the same chosen conditions."}], "quiz": {"q": "A trolley travels 6 m in 3 seconds. What is its average speed?", "opts": ["2 m/s.", "18 m/s.", "0.5 m/s."], "a": 0, "why": "Average speed = 6 ÷ 3 = 2 m/s."}, "misconception": {"q": "A trolley travels 6 m in 3 seconds. What is its average speed? Sam answers: “18 m/s.” Explain why this is wrong.", "m": 2, "ms": ["2 m/s.", "Average speed = 6 ÷ 3 = 2 m/s."]}}, {"key": "dt", "title": "Distance–time graphs", "notes": ["A distance–time graph shows how far an object has travelled. Time goes on the horizontal axis. Distance goes on the vertical axis.", "A horizontal line means the object has stopped. A steeper straight line means a greater speed. Speed = change in distance ÷ change in time."], "worked": "A line goes from 3 m at 2 s to 15 m at 8 s. The changes are 12 m and 6 s. Speed = 12 ÷ 6 = 2 m/s.", "question": "A graph line goes from 10 m at 5 s to 40 m at 15 s. Find the speed.", "scheme": ["Distance change = 40 − 10 = 30 m.", "Time change = 15 − 5 = 10 s.", "Speed = 30 ÷ 10 = 3 m/s."], "mistake": "A graph line is not the shape of the road. A rising line can show a steady speed.", "model": null, "id": "y8-unit-02-dt", "unit": "y8-unit-02", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Gradient", "definition": "The steepness of a graph line, found from vertical change divided by horizontal change."}, {"term": "Distance–time graph", "definition": "A graph showing distance travelled as time passes."}], "quiz": {"q": "What does a horizontal distance–time line show?", "opts": ["The object is stationary.", "The object is speeding up.", "The object is travelling uphill."], "a": 0, "why": "Time passes but distance does not change, so the object is not moving."}, "misconception": {"q": "What does a horizontal distance–time line show? Sam answers: “The object is speeding up.” Explain why this is wrong.", "m": 2, "ms": ["The object is stationary.", "Time passes but distance does not change, so the object is not moving."]}}, {"key": "data", "title": "Tables, graphs and conclusions", "notes": ["Put measurements in a results table. Label each column with the quantity and its unit. A graph helps you spot a pattern.", "Use a line graph for measurements such as time and temperature. Use a bar chart for separate groups, such as different materials. A conclusion answers your question using your results."], "worked": "Suppose sugar dissolves in 40 seconds in cool water and 20 seconds in warm water. The warmer water gave a shorter dissolving time. Use these numbers as evidence in your conclusion.", "question": "What graph would show water temperature and sugar dissolving time? How would you write a good conclusion?", "scheme": ["Use a line or scatter graph with temperature on the horizontal axis.", "Put dissolving time on the vertical axis and label both units.", "Describe the pattern and use numbers from the results."], "mistake": "A conclusion needs evidence. Do not just say your prediction was right.", "model": null, "id": "y8-unit-02-data", "unit": "y8-unit-02", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Continuous data", "definition": "Measurements with values anywhere within a range, such as height."}, {"term": "Discrete data", "definition": "Separate counts or values, such as the number of leaves."}, {"term": "Conclusion", "definition": "An answer to your test question, supported by your results."}], "quiz": {"q": "What makes a good conclusion?", "opts": ["Describe a pattern and use numbers from the results.", "Choose your favourite result and ignore the others.", "Leave units off the graph."], "a": 0, "why": "Numbers from the results give evidence for the pattern you describe."}, "misconception": {"q": "What makes a good conclusion? Sam answers: “Choose your favourite result and ignore the others.” Explain why this is wrong.", "m": 2, "ms": ["Describe a pattern and use numbers from the results.", "Numbers from the results give evidence for the pattern you describe."]}}, {"key": "force", "title": "Forces and movement", "notes": ["A force is a push or pull, measured in newtons, N. Friction is a contact force. Gravity acts without objects touching.", "The resultant force is the overall force after combining all the forces. Balanced forces do not change an object's speed or direction. Unbalanced forces change speed, direction or both. An increase in speed is called acceleration."], "worked": "A trolley has a 9 N push right and a 4 N force left. The resultant is 9 − 4 = 5 N right. With balanced forces, it could stay still or move steadily.", "question": "A boat has a 120 N push forwards and 80 N drag backwards. Find the resultant and describe its effect.", "scheme": ["120 − 80 = 40 N.", "The resultant acts forwards.", "The boat accelerates forwards."], "mistake": "An object can move at a steady speed while forces are balanced.", "model": null, "id": "y8-unit-03-force", "unit": "y8-unit-03", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Resultant force", "definition": "The overall force after combining all forces and their directions."}, {"term": "Balanced forces", "definition": "Forces that cancel out to give zero overall force."}], "quiz": {"q": "What can an object do when its forces are balanced?", "opts": ["Stay still or move steadily in a straight line.", "Always speed up.", "Only stay still."], "a": 0, "why": "Balanced forces do not change speed or direction. An object can already be moving."}, "misconception": {"q": "What can an object do when its forces are balanced? Sam answers: “Always speed up.” Explain why this is wrong.", "m": 2, "ms": ["Stay still or move steadily in a straight line.", "Balanced forces do not change speed or direction. An object can already be moving."]}}, {"key": "gravity", "title": "Mass, weight and falling", "notes": ["Mass is the amount of matter in an object, measured in kilograms. Weight is the force of gravity on an object, measured in newtons. Mass stays the same on different planets, but weight can change.", "A falling object's weight acts downwards. Air resistance, also called drag, acts upwards. Drag increases as the object falls faster."], "worked": "A skydiver speeds up just after jumping. As drag grows, it can become equal to weight. The balanced forces give a steady falling speed, called terminal velocity.", "question": "Why can a falling skydiver reach a steady speed?", "scheme": ["Weight acts downwards and drag acts upwards.", "Drag grows until it equals weight.", "The forces balance, so the skydiver stops speeding up."], "mistake": "Steady falling speed does not mean there are no forces.", "model": null, "id": "y8-unit-03-gravity", "unit": "y8-unit-03", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Mass", "definition": "The amount of matter in an object, measured in kilograms."}, {"term": "Weight", "definition": "The force of gravity on an object, measured in newtons."}, {"term": "Terminal velocity", "definition": "Steady falling speed reached when weight and drag balance."}], "quiz": {"q": "At terminal velocity, how do drag and weight compare?", "opts": ["Drag is zero.", "Weight has disappeared.", "They are equal in size and opposite in direction."], "a": 2, "why": "Balanced forces mean the falling object stops speeding up."}, "misconception": {"q": "At terminal velocity, how do drag and weight compare? Sam answers: “Drag is zero.” Explain why this is wrong.", "m": 2, "ms": ["They are equal in size and opposite in direction.", "Balanced forces mean the falling object stops speeding up."]}}, {"key": "crater", "title": "Investigating craters", "notes": ["A dropped ball can make a crater in a tray of flour. The crater models a mark made by an object hitting a surface. A model helps us test an idea, but it is not an exact copy.", "Change one thing, such as drop height. Measure crater width. Keep the ball and the depth and type of flour the same."], "worked": "Drop the same ball from several measured heights. Level the flour between drops and repeat each height. Compare the mean crater width for each height.", "question": "For a ball-and-flour crater test, name what you change and measure. Give one way it differs from a real impact.", "scheme": ["Change drop height and measure crater width.", "Keep the ball or flour conditions the same.", "A classroom ball and flour do not exactly match a fast space rock and a planet's surface."], "mistake": "A model can be useful without matching every part of a real event.", "model": null, "id": "y8-unit-03-crater", "unit": "y8-unit-03", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Model", "definition": "A simpler version of something, used to explore an idea."}, {"term": "Control variable", "definition": "Something kept the same to make a test fair."}], "quiz": {"q": "When testing drop height and crater size, what should stay the same?", "opts": ["Nothing.", "The ball and the type and depth of the surface material.", "Drop height."], "a": 1, "why": "Keeping the ball and surface the same helps show the effect of drop height."}, "misconception": {"q": "When testing drop height and crater size, what should stay the same? Sam answers: “Drop height.” Explain why this is wrong.", "m": 2, "ms": ["The ball and the type and depth of the surface material.", "Keeping the ball and surface the same helps show the effect of drop height."]}}, {"key": "atoms", "title": "Atoms, elements, compounds and mixtures", "notes": ["An atom is a tiny building block of matter. An element contains only one type of atom. Iron and oxygen are elements.", "A compound has different elements chemically joined together. A mixture contains substances that are not chemically joined to each other. Mixtures can often be separated using physical methods."], "worked": "Water is a compound of hydrogen and oxygen. Salt water is a mixture of salt and water. You can collect the water from salt water by distillation.", "question": "Use water and salt water to explain the difference between a compound and a mixture.", "scheme": ["Water contains hydrogen and oxygen chemically joined.", "Salt water contains salt mixed with water without a new compound forming.", "The substances in salt water can be separated by physical methods."], "mistake": "A mixture is not the same as a compound.", "model": null, "id": "y8-unit-04-atoms", "unit": "y8-unit-04", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Element", "definition": "A substance containing just one type of atom."}, {"term": "Compound", "definition": "A substance with different elements chemically joined in a fixed ratio."}, {"term": "Mixture", "definition": "Substances together without being chemically joined to each other."}], "quiz": {"q": "Which substance is a compound?", "opts": ["Air.", "Iron.", "Pure water."], "a": 2, "why": "Water contains hydrogen and oxygen atoms chemically joined together."}, "misconception": {"q": "Which substance is a compound? Sam answers: “Air.” Explain why this is wrong.", "m": 2, "ms": ["Pure water.", "Water contains hydrogen and oxygen atoms chemically joined together."]}}, {"key": "elements", "title": "Symbols and chemical formulae", "notes": ["Each element has a chemical symbol, such as O for oxygen. The first letter is a capital. Some symbols have a second, lower-case letter, such as Mg.", "A chemical formula shows which atoms make up a substance. Small numbers show how many atoms of an element are present. No small number means one atom."], "worked": "CO₂ means one carbon atom joined to two oxygen atoms. It is the formula for carbon dioxide. A mixture of carbon and oxygen is different because they are not joined in this way.", "question": "What does CO₂ mean? How is it different from a mixture of carbon and oxygen?", "scheme": ["CO₂ has one carbon atom and two oxygen atoms in each molecule.", "These atoms are chemically joined.", "In a mixture, carbon and oxygen are not joined to each other as carbon dioxide."], "mistake": "Co and CO are different. Capital letters matter in chemical symbols.", "model": null, "id": "y8-unit-04-elements", "unit": "y8-unit-04", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Chemical symbol", "definition": "The one- or two-letter label for an element."}, {"term": "Chemical formula", "definition": "Symbols and numbers showing the atoms in a substance."}], "quiz": {"q": "What does CO₂ show?", "opts": ["A mixture of separate carbon and oxygen.", "One carbon atom joined to two oxygen atoms.", "Two carbon atoms joined to one oxygen atom."], "a": 1, "why": "The small 2 refers to oxygen. No number after C means one carbon atom."}, "misconception": {"q": "What does CO₂ show? Sam answers: “Two carbon atoms joined to one oxygen atom.” Explain why this is wrong.", "m": 2, "ms": ["One carbon atom joined to two oxygen atoms.", "The small 2 refers to oxygen. No number after C means one carbon atom."]}}, {"key": "metals", "title": "Metals and reactivity", "notes": ["Metals usually conduct heat and electricity well. Many metals react with oxygen to make metal oxides. Gaining oxygen is called oxidation.", "Some metals react more easily than others. A more reactive metal can replace a less reactive metal in a compound. This is called displacement. Most metals can be shaped without breaking. Some non-metals are exceptions to the usual rules: graphite conducts electricity."], "worked": "Zinc is more reactive than copper. Zinc placed in copper sulfate solution can form zinc sulfate. Copper is left as a solid.", "question": "Zinc is more reactive than copper. What happens when zinc is put in copper sulfate solution? Explain why.", "scheme": ["Zinc displaces copper.", "Zinc sulfate and copper form.", "Zinc replaces copper because it is more reactive."], "mistake": "A less reactive metal cannot simply displace a more reactive one.", "model": null, "id": "y8-unit-04-metals", "unit": "y8-unit-04", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Displacement", "definition": "A more reactive element replacing a less reactive element in a compound."}, {"term": "Oxidation", "definition": "A reaction in which a substance gains oxygen, in these examples."}], "quiz": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate?", "opts": ["Yes, because copper is coloured.", "No.", "Yes, because all metals displace each other."], "a": 1, "why": "The more reactive metal displaces the less reactive metal, not the other way around."}, "misconception": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate? Sam answers: “Yes, because all metals displace each other.” Explain why this is wrong.", "m": 2, "ms": ["No.", "The more reactive metal displaces the less reactive metal, not the other way around."]}}, {"key": "polymer", "title": "Polymers and useful materials", "notes": ["A polymer has very long molecules made from repeating small parts. Many plastics are polymers. Different polymers have different useful properties.", "Choose a material to suit the job. A cable coating must be flexible and an electrical insulator. Think about waste, reuse and recycling as well as usefulness. Starch and cellulose are natural polymers. A polymer is not automatically biodegradable or easy to recycle."], "worked": "A plastic coating stops your hand touching the conducting wire. It bends with the cable. If it is not recycled, it may remain as waste for a long time.", "question": "Give a useful polymer property for a cable coating and explain it. Give one environmental problem to consider.", "scheme": ["It should be an electrical insulator or flexible.", "Insulation protects users, or flexibility lets the cable bend.", "Some plastics are difficult to recycle or break down very slowly."], "mistake": "Not all polymers have the same properties or can be recycled in the same way.", "model": null, "id": "y8-unit-04-polymer", "unit": "y8-unit-04", "year": 8, "number": 4, "marks": 3, "cards": [{"term": "Polymer", "definition": "A substance made of long molecules with repeating small parts."}, {"term": "Biodegradable", "definition": "Able to be broken down by living things such as microorganisms in suitable conditions."}], "quiz": {"q": "Which statement about polymers is correct?", "opts": ["Different polymers have different useful properties.", "Every polymer is the same material.", "Every polymer breaks down quickly in soil."], "a": 0, "why": "Choose a polymer whose properties suit the job, such as a flexible electrical insulator."}, "misconception": {"q": "Which statement about polymers is correct? Sam answers: “Every polymer is the same material.” Explain why this is wrong.", "m": 2, "ms": ["Different polymers have different useful properties.", "Choose a polymer whose properties suit the job, such as a flexible electrical insulator."]}}, {"key": "periodic", "title": "Using the periodic table", "notes": ["The periodic table organises the elements. Each box gives an element's symbol. A group is a vertical column.", "A period is a horizontal row. Elements in a group often have similar chemical properties. These patterns help us predict how an element may react. Elements are ordered by atomic number: the number of protons in each atom. Metals are mostly on the left and centre, and non-metals mostly on the right."], "worked": "Lithium and sodium are both in Group 1. Both react with water to make hydrogen. Their shared group helps us spot a pattern.", "question": "What is a group in the periodic table? Why is grouping elements useful?", "scheme": ["A group is a vertical column.", "Elements in a group often have similar chemical properties.", "You can use the pattern to predict reactions or properties."], "mistake": "Elements in a group are similar, but they are not identical.", "model": null, "id": "y8-unit-05-periodic", "unit": "y8-unit-05", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Group", "definition": "A vertical column of the periodic table."}, {"term": "Period", "definition": "A horizontal row of the periodic table."}], "quiz": {"q": "Why is a periodic-table group useful?", "opts": ["Every element in it has exactly the same mass.", "Its elements are all the same substance.", "Its elements often have similar chemical properties."], "a": 2, "why": "Group patterns help predict properties and reactions."}, "misconception": {"q": "Why is a periodic-table group useful? Sam answers: “Every element in it has exactly the same mass.” Explain why this is wrong.", "m": 2, "ms": ["Its elements often have similar chemical properties.", "Group patterns help predict properties and reactions."]}}, {"key": "groups", "title": "Groups 1, 7 and 0", "notes": ["Group 1 contains reactive metals such as lithium and sodium. Group 7 contains non-metals called halogens. Group 0 contains noble gases that rarely react.", "Group 1 metals get more reactive down the group. Group 7 halogens get less reactive down the group. A more reactive halogen can displace a less reactive one from a compound."], "worked": "Chlorine is more reactive than iodine. Chlorine reacts with potassium iodide solution. Potassium chloride and iodine form.", "question": "Chlorine is more reactive than iodine. What happens when chlorine is added to potassium iodide solution?", "scheme": ["Chlorine displaces iodine.", "Potassium chloride forms.", "Iodine is produced because chlorine is more reactive."], "mistake": "The reactivity trend in Group 7 goes the opposite way to Group 1.", "model": null, "id": "y8-unit-05-groups", "unit": "y8-unit-05", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Halogen", "definition": "A reactive non-metal in Group 7, also numbered Group 17."}, {"term": "Noble gas", "definition": "A Group 0 element that rarely reacts, also numbered Group 18."}], "quiz": {"q": "How does reactivity change down Group 1?", "opts": ["Every element is unreactive.", "It generally increases.", "It generally decreases."], "a": 1, "why": "The lower Group 1 metals generally react more readily."}, "misconception": {"q": "How does reactivity change down Group 1? Sam answers: “It generally decreases.” Explain why this is wrong.", "m": 2, "ms": ["It generally increases.", "The lower Group 1 metals generally react more readily."]}}, {"key": "transition", "title": "Useful metals in the middle of the table", "notes": ["Many familiar metals are in the middle of the periodic table. Iron and copper are examples. Many are strong and conduct heat and electricity well.", "Copper is useful for wires because it conducts electricity. Iron is used to make strong steel. Some of these metals also speed up chemical reactions as catalysts."], "worked": "Copper wire carries current through a circuit. Steel beams support buildings. Each material is chosen because its properties suit the job.", "question": "Give two uses of these metals and explain which property makes each useful.", "scheme": ["Give a use such as copper in wires or iron in steel.", "Link copper wiring to good electrical conduction.", "Link steel structures to strength, or give another correct use and property."], "mistake": "Name a property and explain why it helps with the particular job.", "model": null, "id": "y8-unit-05-transition", "unit": "y8-unit-05", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Catalyst", "definition": "A substance that speeds up a reaction without being used up overall."}, {"term": "Transition metal", "definition": "A metal in the central part of the periodic table, such as iron or copper in school examples."}], "quiz": {"q": "Why is copper useful for electric wires?", "opts": ["It is an electrical insulator.", "It is a gas at room temperature.", "It conducts electricity well."], "a": 2, "why": "Copper lets charge flow easily through a wire."}, "misconception": {"q": "Why is copper useful for electric wires? Sam answers: “It is an electrical insulator.” Explain why this is wrong.", "m": 2, "ms": ["It conducts electricity well.", "Copper lets charge flow easily through a wire."]}}, {"key": "lungs", "title": "Breathing and gas exchange", "notes": ["Breathing moves air into and out of your lungs. Air reaches tiny air sacs called alveoli. Oxygen passes from the alveoli into the blood.", "Carbon dioxide passes from the blood into the alveoli. Thin walls and a large surface area help gases move quickly. The diaphragm is a sheet of muscle below the lungs. Air travels down the windpipe, or trachea, through bronchi and bronchioles to reach the alveoli. A good blood supply carries gases to and from the alveoli. During breathing out, the chest gets smaller and air is pushed out."], "worked": "When you breathe in, the diaphragm contracts and moves down. The space inside the chest gets larger and the pressure falls. Air moves into the lungs.", "question": "How does the diaphragm help you breathe in?", "scheme": ["It contracts and moves downwards.", "Chest volume increases and air pressure inside falls.", "Air moves into the lungs from outside."], "mistake": "Breathing moves air. Respiration is a chemical process inside cells.", "model": null, "id": "y8-unit-06-lungs", "unit": "y8-unit-06", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Ventilation", "definition": "Moving air into and out of the lungs."}, {"term": "Alveolus", "definition": "A tiny air sac in the lungs where gases move between air and blood."}, {"term": "Diaphragm", "definition": "A sheet of muscle below the lungs that helps breathing."}], "quiz": {"q": "What happens when you breathe in normally?", "opts": ["Air is pushed out of the lungs.", "The diaphragm contracts and moves down.", "The diaphragm moves up and chest space gets smaller."], "a": 1, "why": "The chest space gets larger, pressure falls and air moves in."}, "misconception": {"q": "What happens when you breathe in normally? Sam answers: “The diaphragm moves up and chest space gets smaller.” Explain why this is wrong.", "m": 2, "ms": ["The diaphragm contracts and moves down.", "The chest space gets larger, pressure falls and air moves in."]}}, {"key": "drugs", "title": "Smoking, vaping, alcohol and drugs", "notes": ["A drug changes how the body works. Some drugs are medicines and others can cause harm. Nicotine can make people dependent, so stopping is difficult.", "Cigarette smoke contains harmful substances. Tar damages the lungs and carbon monoxide reduces oxygen carried by the blood. Vaping is not harmless and is unsuitable for children and non-smokers. Alcohol affects the nervous system and can slow reactions and affect judgement. Smoke damages tiny hairs called cilia that help clean the airways."], "worked": "Damaged air sacs make gas exchange harder. Carbon monoxide attaches to haemoglobin, which normally carries oxygen. Both effects can reduce oxygen reaching body cells.", "question": "Give two ways cigarette smoke reduces the oxygen reaching body cells. Explain one.", "scheme": ["Tar can damage air sacs and reduce gas exchange.", "Carbon monoxide reduces the blood's ability to carry oxygen.", "Less oxygen then reaches cells for aerobic respiration."], "mistake": "Less harmful than smoking does not mean harmless. Young people should not start vaping.", "model": null, "id": "y8-unit-06-drugs", "unit": "y8-unit-06", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Drug", "definition": "A substance that changes how the body works."}, {"term": "Dependence", "definition": "Finding it difficult to stop using a substance, sometimes with withdrawal effects."}], "quiz": {"q": "Which statement about nicotine vaping is correct?", "opts": ["It is harmless for all young people.", "Everyone who does not smoke should start vaping.", "It is not harmless and nicotine can cause dependence."], "a": 2, "why": "Vaping is unsuitable for children and non-smokers. Nicotine can make stopping difficult."}, "misconception": {"q": "Which statement about nicotine vaping is correct? Sam answers: “It is harmless for all young people.” Explain why this is wrong.", "m": 2, "ms": ["It is not harmless and nicotine can cause dependence.", "Vaping is unsuitable for children and non-smokers. Nicotine can make stopping difficult."]}}, {"key": "nutrition", "title": "Nutrients and a balanced diet", "notes": ["A balanced diet gives the body the nutrients it needs. Carbohydrates and fats provide energy. Protein is needed for growth and repair.", "Vitamins and minerals are needed in small amounts. Fibre helps food move through the gut. A deficiency means you are not getting enough of a nutrient. Water is needed for transport and many processes inside cells. The amount of food needed depends on factors such as activity and growth."], "worked": "Iron helps make haemoglobin in red blood cells. Haemoglobin carries oxygen. Too little iron can cause tiredness because less oxygen reaches cells.", "question": "What are the jobs of protein, fibre and iron?", "scheme": ["Protein is used for growth and repair.", "Fibre helps food move through the gut.", "Iron is needed to make haemoglobin for carrying oxygen."], "mistake": "A balanced diet means a useful mix of nutrients, not equal amounts of every food.", "model": null, "id": "y8-unit-07-nutrition", "unit": "y8-unit-07", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Nutrient", "definition": "A substance needed for energy, growth, repair or health."}, {"term": "Deficiency", "definition": "Not getting enough of a needed nutrient."}, {"term": "Fibre", "definition": "Material in food that we do not digest and that helps food move through the gut."}], "quiz": {"q": "Why do you need iron in your diet?", "opts": ["To replace all the water in the body.", "To digest fibre into glucose.", "To make haemoglobin for carrying oxygen in blood."], "a": 2, "why": "Haemoglobin in red blood cells needs iron to carry oxygen."}, "misconception": {"q": "Why do you need iron in your diet? Sam answers: “To replace all the water in the body.” Explain why this is wrong.", "m": 2, "ms": ["To make haemoglobin for carrying oxygen in blood.", "Haemoglobin in red blood cells needs iron to carry oxygen."]}}, {"key": "food-tests", "title": "Testing foods", "notes": ["Food tests help identify nutrients in a sample. Iodine solution tests for starch. A blue-black colour is a positive starch result.", "Benedict's solution tests for some sugars when heated safely. The biuret test identifies protein. Use separate samples and follow your teacher's safety instructions."], "worked": "Add iodine to a food sample. If it stays orange-brown, starch has not been detected. Other carbohydrates, such as sugars, could still be present.", "question": "Describe a positive iodine test. Why does a negative result not show that all carbohydrates are missing?", "scheme": ["Iodine turns blue-black if starch is detected.", "A negative result only means starch was not detected.", "Other carbohydrates, such as sugars, may still be present."], "mistake": "A test for one nutrient cannot tell you that every other nutrient is absent.", "model": null, "id": "y8-unit-07-food-tests", "unit": "y8-unit-07", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Positive test", "definition": "A result showing that the substance being tested for was detected."}, {"term": "Reducing sugar", "definition": "A type of sugar, such as glucose, detected by Benedict's test with heating."}], "quiz": {"q": "What is a positive iodine test for starch?", "opts": ["Bubbles prove starch is present.", "The sample turns blue-black.", "The sample stays orange-brown."], "a": 1, "why": "Iodine turns blue-black when starch is detected."}, "misconception": {"q": "What is a positive iodine test for starch? Sam answers: “The sample stays orange-brown.” Explain why this is wrong.", "m": 2, "ms": ["The sample turns blue-black.", "Iodine turns blue-black when starch is detected."]}}, {"key": "digestion", "title": "Digestion, enzymes and absorption", "notes": ["Digestion breaks large food molecules into small ones. The small molecules can dissolve and pass into the blood. Enzymes speed up the chemical breakdown of food.", "The small intestine has many tiny folds called villi. These give a large surface area for absorption. Absorption is the movement of digested nutrients through the gut wall. Amylase breaks down starch, protease breaks down proteins and lipase breaks down fats. Bile breaks fat into small droplets and helps neutralise acid from the stomach. Bile is not an enzyme. The stomach mixes food, and the small intestine does most absorption. The large intestine absorbs water."], "worked": "An enzyme breaks starch into smaller sugar molecules. The sugars pass through the wall of the small intestine. Blood carries them to body cells.", "question": "How do enzymes and villi help nutrients get from food into the blood?", "scheme": ["Enzymes break large food molecules into small soluble molecules.", "Villi give a large surface area for absorption.", "Small nutrients pass through the gut wall into the blood."], "mistake": "Food does not simply fall through holes into the blood. It must be digested and absorbed.", "model": null, "id": "y8-unit-07-digestion", "unit": "y8-unit-07", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Digestion", "definition": "Breaking large food molecules into small molecules that can dissolve."}, {"term": "Enzyme", "definition": "A substance made by living things that speeds up a chemical reaction."}, {"term": "Absorption", "definition": "Digested nutrients passing through the gut wall."}], "quiz": {"q": "How do villi help absorption?", "opts": ["They stop nutrients reaching the blood.", "They provide a larger surface area.", "They make the intestine waterproof."], "a": 1, "why": "More surface area lets nutrients pass into the body more quickly."}, "misconception": {"q": "How do villi help absorption? Sam answers: “They make the intestine waterproof.” Explain why this is wrong.", "m": 2, "ms": ["They provide a larger surface area.", "More surface area lets nutrients pass into the body more quickly."]}}, {"key": "sound", "title": "Sound waves, loudness and pitch", "notes": ["Sound is made by vibrations. It travels through solids, liquids or gases. Particles pass the vibration from place to place.", "Amplitude is the size of a vibration. A larger amplitude usually makes a louder sound. Frequency is vibrations per second: a higher frequency gives a higher pitch. Sound cannot cross a vacuum because there are no particles to pass on the vibration."], "worked": "A guitar string can vibrate with a large or small amplitude. Plucking harder usually makes it louder. Changing how often it vibrates changes the pitch.", "question": "How is increasing amplitude different from increasing frequency for a sound?", "scheme": ["Increasing amplitude usually increases loudness.", "Increasing frequency increases pitch.", "Loudness and pitch can change separately."], "mistake": "Louder does not always mean higher-pitched.", "model": "wave", "id": "y8-unit-08-sound", "unit": "y8-unit-08", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Amplitude", "definition": "The greatest distance a vibrating part moves from its resting position."}, {"term": "Frequency", "definition": "The number of complete vibrations each second."}, {"term": "Longitudinal wave", "definition": "A wave whose vibrations are along the direction it travels."}], "quiz": {"q": "What changes when a sound has a higher pitch?", "opts": ["It must travel faster.", "Its frequency is higher.", "Its amplitude must be larger."], "a": 1, "why": "Pitch depends on frequency. Amplitude is linked to loudness."}, "misconception": {"q": "What changes when a sound has a higher pitch? Sam answers: “Its amplitude must be larger.” Explain why this is wrong.", "m": 2, "ms": ["Its frequency is higher.", "Pitch depends on frequency. Amplitude is linked to loudness."]}}, {"key": "ear", "title": "Hearing and echoes", "notes": ["Sound makes the eardrum vibrate. Small bones pass the vibrations towards the inner ear. The cochlea changes vibrations into nerve signals for the brain.", "An echo is a sound that reflects from a surface. The sound travels to the surface and back. Divide the total travel distance by two to find the distance to the surface."], "worked": "An echo takes 0.2 seconds to return. At 340 m/s, sound travels 340 × 0.2 = 68 m in total. The wall is 68 ÷ 2 = 34 m away.", "question": "An echo returns after 0.2 seconds. Sound travels at 340 m/s. How far away is the wall?", "scheme": ["Total distance = 340 × 0.2 = 68 m.", "Divide by two because the sound travels there and back.", "Wall distance = 34 m."], "mistake": "The echo time includes both journeys, not just the journey to the wall.", "model": null, "id": "y8-unit-08-ear", "unit": "y8-unit-08", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Echo", "definition": "A sound that reflects from a surface."}, {"term": "Cochlea", "definition": "The inner-ear part that turns vibrations into nerve signals."}], "quiz": {"q": "Why divide speed × echo time by two to find a wall's distance?", "opts": ["Sound only travels half the time.", "The wall absorbs exactly half the sound.", "The sound travels to the wall and back."], "a": 2, "why": "The calculation first gives the total length of both journeys."}, "misconception": {"q": "Why divide speed × echo time by two to find a wall's distance? Sam answers: “Sound only travels half the time.” Explain why this is wrong.", "m": 2, "ms": ["The sound travels to the wall and back.", "The calculation first gives the total length of both journeys."]}}, {"key": "light", "title": "Reflection and refraction", "notes": ["Light travels in straight lines through a uniform material. Reflection is light bouncing off a surface. Refraction is light changing direction as its speed changes between materials.", "Draw the normal at right angles to the surface. Measure ray angles from the normal. For reflection, the incoming angle equals the reflected angle. Light bends towards the normal when it enters glass from air at an angle."], "worked": "A ray hits a mirror at 40° to the normal. It reflects at 40° to the normal. It makes 90 − 40 = 50° with the mirror surface.", "question": "A ray hits a plane mirror at 40° to the normal. Find the reflection angle and the angle to the mirror surface.", "scheme": ["The reflection angle is 40° to the normal.", "The normal is at 90° to the mirror.", "The reflected ray is at 50° to the mirror surface."], "mistake": "Angles are measured from the normal, not from the mirror surface.", "model": "rays", "id": "y8-unit-09-light", "unit": "y8-unit-09", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Normal", "definition": "A line drawn at right angles to a surface where a ray hits it."}, {"term": "Reflection", "definition": "A wave bouncing back from a surface."}, {"term": "Refraction", "definition": "A wave changing direction as its speed changes between materials."}], "quiz": {"q": "Where do you measure reflection angles from?", "opts": ["Any line on the page.", "The normal.", "The mirror surface."], "a": 1, "why": "The normal is at 90° to the surface. Both ray angles are measured from it."}, "misconception": {"q": "Where do you measure reflection angles from? Sam answers: “The mirror surface.” Explain why this is wrong.", "m": 2, "ms": ["The normal.", "The normal is at 90° to the surface. Both ray angles are measured from it."]}}, {"key": "colour", "title": "Colours, lenses and light waves", "notes": ["White light is a mixture of colours. An object looks coloured because it reflects some colours and absorbs others. A filter lets some colours through and absorbs others.", "A red object reflects red light well. Under blue light it may look dark because little blue is reflected. A convex lens brings parallel light rays together."], "worked": "Put a red card under white light and it looks red. Shine only blue light on it and there is no red light to reflect. It may then look very dark.", "question": "Why can a red object look dark when only blue light shines on it?", "scheme": ["A red object mainly reflects red light.", "Blue light contains no red light for it to reflect.", "The object absorbs much of the blue light, so little reaches the eye."], "mistake": "An object cannot reflect a colour that is missing from the light shining on it.", "model": "rays", "id": "y8-unit-09-colour", "unit": "y8-unit-09", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Filter", "definition": "A material that lets some colours of light through and absorbs others."}, {"term": "Convex lens", "definition": "A lens that can bring parallel light rays together."}, {"term": "Spectrum", "definition": "A range of waves arranged by wavelength or frequency."}], "quiz": {"q": "Why can a red object look dark in blue light?", "opts": ["There is no red light to reflect and it absorbs much of the blue.", "It creates black light.", "It must turn into a blue material."], "a": 0, "why": "An object can only reflect colours that are present in the light reaching it."}, "misconception": {"q": "Why can a red object look dark in blue light? Sam answers: “It creates black light.” Explain why this is wrong.", "m": 2, "ms": ["There is no red light to reflect and it absorbs much of the blue.", "An object can only reflect colours that are present in the light reaching it."]}}, {"key": "reaction", "title": "Chemical reactions and physical changes", "notes": ["A chemical reaction makes one or more new substances. The starting substances are reactants. The new substances are products.", "A physical change does not make a new substance. Melting and freezing are physical changes. Bubbles or a colour change can be clues to a reaction, but check the evidence."], "worked": "Burning magnesium makes a new substance, magnesium oxide. Melting ice still leaves you with water. Boiling water makes bubbles without a chemical reaction.", "question": "Give one chemical reaction and one physical change. Explain the difference.", "scheme": ["Give a reaction that makes a new substance, such as burning magnesium.", "Give a physical change, such as melting ice.", "A physical change does not make a new substance."], "mistake": "Bubbles alone do not prove that a chemical reaction happened.", "model": null, "id": "y8-unit-10-reaction", "unit": "y8-unit-10", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Reactant", "definition": "A starting substance in a chemical reaction."}, {"term": "Product", "definition": "A new substance made in a chemical reaction."}, {"term": "Physical change", "definition": "A change that does not make a new substance."}], "quiz": {"q": "Which observation alone does not prove a chemical reaction?", "opts": ["Bubbles appearing.", "Clear evidence of a new substance forming.", "A test confirming a different chemical substance."], "a": 0, "why": "Boiling water also makes bubbles, without making a new substance."}, "misconception": {"q": "Which observation alone does not prove a chemical reaction? Sam answers: “Clear evidence of a new substance forming.” Explain why this is wrong.", "m": 2, "ms": ["Bubbles appearing.", "Boiling water also makes bubbles, without making a new substance."]}}, {"key": "combustion", "title": "Burning and breaking down compounds", "notes": ["Combustion is burning: a substance reacts with oxygen. Thermal decomposition is when heating breaks a compound into simpler substances. Both are chemical changes because new substances form.", "Melting is a physical change. The particles are still the same substance after melting. Use evidence of new substances to tell changes apart."], "worked": "Melting ice produces liquid water, so no new substance forms. Heating calcium carbonate makes calcium oxide and carbon dioxide. This is thermal decomposition because a compound breaks down when heated.", "question": "Is each change physical or chemical: melting ice, and heating calcium carbonate to make calcium oxide and carbon dioxide? Explain.", "scheme": ["Melting ice is physical because it is still water.", "Heating calcium carbonate is chemical because new substances form.", "The chemical change is thermal decomposition."], "mistake": "Not every change caused by heating is a chemical reaction.", "model": null, "id": "y8-unit-10-combustion", "unit": "y8-unit-10", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Thermal decomposition", "definition": "Breaking a compound into simpler substances by heating it."}, {"term": "Complete combustion", "definition": "A fuel burning fully with enough oxygen."}], "quiz": {"q": "Which is thermal decomposition?", "opts": ["Heating calcium carbonate to make calcium oxide and carbon dioxide.", "Melting ice.", "Filtering sand from water."], "a": 0, "why": "A compound breaks down into new substances when heated."}, "misconception": {"q": "Which is thermal decomposition? Sam answers: “Melting ice.” Explain why this is wrong.", "m": 2, "ms": ["Heating calcium carbonate to make calcium oxide and carbon dioxide.", "A compound breaks down into new substances when heated."]}}, {"key": "mass", "title": "Where does the mass go?", "notes": ["Atoms are rearranged in a chemical reaction. They are not created or destroyed. Total mass stays the same if you count everything.", "A gas can enter or leave an open container. This can make the measured mass change. A closed container keeps all the reacting matter inside."], "worked": "Magnesium burns by joining with oxygen from the air. The magnesium oxide includes the added oxygen. Its mass is greater than the starting magnesium alone.", "question": "Why does magnesium gain mass when it burns in air?", "scheme": ["Magnesium reacts with oxygen.", "Oxygen atoms join the magnesium to make magnesium oxide.", "The added oxygen makes the product heavier than the magnesium alone."], "mistake": "A lower reading after a reaction does not mean mass was destroyed. A gas may have escaped.", "model": null, "id": "y8-unit-10-mass", "unit": "y8-unit-10", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Closed system", "definition": "A setup where no matter can enter or leave."}, {"term": "Conservation of mass", "definition": "Total mass stays the same in a reaction when all matter is counted."}], "quiz": {"q": "Why can an open flask lose measured mass during a reaction?", "opts": ["Mass stops existing.", "A gas leaves the flask.", "Atoms are destroyed."], "a": 1, "why": "The gas still exists outside the flask. Counting it would keep the total mass unchanged."}, "misconception": {"q": "Why can an open flask lose measured mass during a reaction? Sam answers: “Atoms are destroyed.” Explain why this is wrong.", "m": 2, "ms": ["A gas leaves the flask.", "The gas still exists outside the flask. Counting it would keep the total mass unchanged."]}}, {"key": "chemical-energy", "title": "Reactions that heat or cool", "notes": ["An exothermic reaction transfers energy to the surroundings. The surroundings usually get warmer. An endothermic reaction takes energy from the surroundings, which usually cool down.", "Bonds are links between atoms. Breaking bonds takes in energy. Making new bonds releases energy. A lid and insulation reduce unwanted energy transfer in temperature-change tests. Keep starting temperatures and amounts the same for a fair comparison."], "worked": "In an exothermic reaction, making new bonds releases more energy than breaking old bonds takes in. The extra energy heats the surroundings. A thermometer can show the temperature rise.", "question": "Why can an exothermic reaction warm its surroundings? Use the ideas of breaking and making bonds.", "scheme": ["Breaking old bonds takes in energy.", "Making new bonds releases more energy than was taken in.", "The extra energy is transferred to the surroundings, warming them."], "mistake": "Breaking a bond takes energy. It does not release energy by itself.", "model": null, "id": "y8-unit-11-chemical-energy", "unit": "y8-unit-11", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Exothermic", "definition": "Transferring energy to the surroundings overall, usually warming them."}, {"term": "Endothermic", "definition": "Taking energy from the surroundings overall, usually cooling them."}, {"term": "Bond", "definition": "A chemical link between atoms."}], "quiz": {"q": "Which statement about bonds is correct?", "opts": ["Breaking bonds takes in energy and making bonds releases energy.", "Breaking bonds always releases energy.", "Making bonds always needs energy with none released."], "a": 0, "why": "Compare the energy taken in and released to decide whether the reaction heats or cools its surroundings."}, "misconception": {"q": "Which statement about bonds is correct? Sam answers: “Breaking bonds always releases energy.” Explain why this is wrong.", "m": 2, "ms": ["Breaking bonds takes in energy and making bonds releases energy.", "Compare the energy taken in and released to decide whether the reaction heats or cools its surroundings."]}}, {"key": "catalyst", "title": "Catalysts and enzymes", "notes": ["A catalyst makes a reaction happen faster. It is not used up overall in the reaction. An enzyme is a catalyst made by a living thing.", "A catalyst can help the reaction finish sooner. It does not necessarily make more product in total. Enzymes work best within suitable temperature and pH ranges."], "worked": "Two tests start with the same amounts of reactants. The one with a catalyst produces gas more quickly. Both can still finish with the same gas volume.", "question": "Why can a reaction make gas faster but still produce the same final gas volume?", "scheme": ["A catalyst speeds up the reaction.", "The same starting amounts can make the same total product.", "The gas is made sooner, rather than extra gas being made."], "mistake": "A faster reaction does not always make more product in total.", "model": null, "id": "y8-unit-11-catalyst", "unit": "y8-unit-11", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Activation energy", "definition": "The energy needed to get a reaction started."}, {"term": "Catalyst", "definition": "A substance that speeds up a reaction without being used up overall."}], "quiz": {"q": "What can a catalyst change when reactant amounts stay the same?", "opts": ["The total number of starting atoms.", "Whether atoms are conserved.", "How quickly the products form."], "a": 2, "why": "A catalyst can make the same amount of product form sooner."}, "misconception": {"q": "What can a catalyst change when reactant amounts stay the same? Sam answers: “The total number of starting atoms.” Explain why this is wrong.", "m": 2, "ms": ["How quickly the products form.", "A catalyst can make the same amount of product form sooner."]}}, {"key": "respiration", "title": "Aerobic respiration and exercise", "notes": ["Respiration is a chemical process inside living cells. It releases energy from food. Aerobic respiration uses oxygen.", "The word equation is glucose + oxygen → carbon dioxide + water. Plants and animals both respire. Breathing brings air to the lungs; it is not the same as respiration."], "worked": "Muscles need more energy during exercise. They use more glucose and oxygen for respiration. Breathing faster helps supply oxygen and remove carbon dioxide.", "question": "Why does breathing rate usually increase during exercise?", "scheme": ["Working muscles need more energy.", "They carry out more aerobic respiration and need more oxygen.", "Faster breathing supplies oxygen and removes extra carbon dioxide."], "mistake": "Plants respire in the light and in the dark.", "model": null, "id": "y8-unit-12-respiration", "unit": "y8-unit-12", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Aerobic respiration", "definition": "Releasing energy from glucose in cells using oxygen."}, {"term": "Respiration", "definition": "Chemical processes in cells that release energy from food."}], "quiz": {"q": "Which living things respire?", "opts": ["Only animals.", "Only things that have lungs.", "Plants and animals."], "a": 2, "why": "Plants and animals need energy for cell processes, so both respire."}, "misconception": {"q": "Which living things respire? Sam answers: “Only animals.” Explain why this is wrong.", "m": 2, "ms": ["Plants and animals.", "Plants and animals need energy for cell processes, so both respire."]}}, {"key": "anaerobic", "title": "Respiration without oxygen", "notes": ["Anaerobic respiration releases energy without using oxygen. It releases less energy from each glucose molecule than aerobic respiration. Different organisms can make different products.", "Yeast makes ethanol and carbon dioxide from glucose without oxygen. This process is called fermentation. It is used in bread making and some drinks production."], "worked": "Yeast in bread dough produces carbon dioxide. The gas makes bubbles that cause the dough to rise. Ethanol is also formed and mostly evaporates during baking.", "question": "What are the products of anaerobic respiration in yeast? Explain how one helps make bread.", "scheme": ["Yeast produces ethanol.", "It also produces carbon dioxide.", "Carbon dioxide bubbles make the dough rise."], "mistake": "Anaerobic respiration is not “no respiration”. It still releases energy.", "model": null, "id": "y8-unit-12-anaerobic", "unit": "y8-unit-12", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Anaerobic respiration", "definition": "Releasing energy from glucose without using oxygen."}, {"term": "Fermentation", "definition": "Anaerobic respiration in yeast that makes ethanol and carbon dioxide."}], "quiz": {"q": "Which gas makes bread dough rise?", "opts": ["Carbon dioxide.", "Oxygen.", "Nitrogen."], "a": 0, "why": "Yeast makes carbon dioxide bubbles that expand the dough."}, "misconception": {"q": "Which gas makes bread dough rise? Sam answers: “Oxygen.” Explain why this is wrong.", "m": 2, "ms": ["Carbon dioxide.", "Yeast makes carbon dioxide bubbles that expand the dough."]}}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y8-unit-12-planning", "unit": "y8-unit-12", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It fixes every equipment error.", "It makes the clock perfect.", "It reduces the effect of your reaction time on each swing's time."], "a": 2, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}}, {"key": "photosynthesis", "title": "Photosynthesis and plant food", "notes": ["Plants make glucose using light energy. This process is called photosynthesis. Carbon dioxide + water → glucose + oxygen.", "Chlorophyll is the green substance that absorbs light. Plants use glucose for respiration and growth. They can store extra glucose as starch."], "worked": "Carbon dioxide enters a leaf from the air. Roots take in water and light is absorbed in the leaf. The glucose made can be used to build cellulose for cell walls.", "question": "Write the photosynthesis word equation. Give two uses of the glucose made.", "scheme": ["Carbon dioxide + water → glucose + oxygen, using light.", "Glucose can be used in respiration.", "It can also be stored as starch or used to make cellulose for growth."], "mistake": "Plants make their food by photosynthesis. They do not get their food from soil.", "model": "photosynthesis", "id": "y8-unit-13-photosynthesis", "unit": "y8-unit-13", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Photosynthesis", "definition": "Using light to make glucose from carbon dioxide and water, releasing oxygen."}, {"term": "Chlorophyll", "definition": "The green substance that absorbs light for photosynthesis."}], "quiz": {"q": "Where does the carbon used to build much of a plant come from?", "opts": ["The light itself.", "Carbon dioxide in the air.", "Only minerals in the soil."], "a": 1, "why": "Photosynthesis uses carbon dioxide to make glucose that can be used for growth."}, "misconception": {"q": "Where does the carbon used to build much of a plant come from? Sam answers: “Only minerals in the soil.” Explain why this is wrong.", "m": 2, "ms": ["Carbon dioxide in the air.", "Photosynthesis uses carbon dioxide to make glucose that can be used for growth."]}}, {"key": "leaf", "title": "Leaves and plant growth", "notes": ["Leaves are broad, so they absorb lots of light. They are thin, so gases have a short distance to travel. Small pores called stomata let gases move in and out.", "A limiting factor is something in short supply that slows a process. Too little light or carbon dioxide can slow photosynthesis. An unsuitable temperature can also slow it. Many cells near the top of a leaf contain lots of chloroplasts. Veins carry water to the leaf and sugars away. Plants need nitrates to make proteins and magnesium to make chlorophyll."], "worked": "At first, brighter light can make photosynthesis faster. Eventually there may not be enough carbon dioxide to go faster. Adding more light alone then makes little difference.", "question": "Why might extra light eventually stop making photosynthesis faster?", "scheme": ["Light was in short supply at first.", "Another factor, such as carbon dioxide, is now in short supply.", "More light cannot solve the shortage of that other factor."], "mistake": "A limiting factor is the factor holding back the rate at that moment.", "model": "photosynthesis", "id": "y8-unit-13-leaf", "unit": "y8-unit-13", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Stoma", "definition": "A tiny pore in a leaf that lets gases pass in and out."}, {"term": "Limiting factor", "definition": "The thing in short supply that is holding back the rate."}], "quiz": {"q": "Why can extra light stop making photosynthesis faster?", "opts": ["Light has turned into soil minerals.", "Another factor, such as carbon dioxide, is now in short supply.", "The plant has stopped needing all energy."], "a": 1, "why": "Extra light does not fix a shortage of carbon dioxide or an unsuitable temperature."}, "misconception": {"q": "Why can extra light stop making photosynthesis faster? Sam answers: “The plant has stopped needing all energy.” Explain why this is wrong.", "m": 2, "ms": ["Another factor, such as carbon dioxide, is now in short supply.", "Extra light does not fix a shortage of carbon dioxide or an unsuitable temperature."]}}, {"key": "plant-practical", "title": "Investigating photosynthesis", "notes": ["Pondweed gives off oxygen during photosynthesis. You can compare oxygen made at different light levels. Keep temperature, time and carbon dioxide supply the same.", "Count bubbles for a simple estimate. Collecting gas volume can be better because bubbles have different sizes. Repeat measurements before comparing results."], "worked": "Move a lamp closer to pondweed and count bubbles for one minute. Use a ruler to set each lamp distance. Watch for lamp heating, which could change the water temperature.", "question": "Give two problems with counting pondweed bubbles. Suggest one improvement.", "scheme": ["Bubbles can have different sizes.", "Some bubbles may be missed or gas may dissolve in the water.", "Collect gas volume over a set time and repeat readings."], "mistake": "A bubble count is an estimate of gas production, not an exact oxygen volume.", "model": null, "id": "y8-unit-13-plant-practical", "unit": "y8-unit-13", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Proxy", "definition": "A measurement used to estimate something else."}, {"term": "Destarching", "definition": "Keeping a plant in the dark long enough for stored starch to be used up."}], "quiz": {"q": "Why can gas volume be better than a bubble count?", "opts": ["Every bubble has the same volume.", "Bubble counts measure every oxygen molecule.", "Bubbles can have different sizes."], "a": 2, "why": "Counting ten large bubbles and ten small bubbles does not give the same gas volume."}, "misconception": {"q": "Why can gas volume be better than a bubble count? Sam answers: “Every bubble has the same volume.” Explain why this is wrong.", "m": 2, "ms": ["Bubbles can have different sizes.", "Counting ten large bubbles and ten small bubbles does not give the same gas volume."]}}, {"key": "investigate-candle", "title": "Testing a candle under a container", "notes": ["A candle needs oxygen to keep burning. Covering it limits the supply of fresh air. Only do a real candle test with teacher supervision.", "Change the container volume and measure burning time. Keep the candle, starting conditions and timing rule the same. The flame can go out before every bit of oxygen has been used."], "worked": "Use the same candle and containers of different measured volumes. Start timing when the container covers the candle. Stop when the flame goes out.", "question": "For a test of container volume and candle burning time, name what you change, what you measure and one control.", "scheme": ["Change the volume of the container.", "Measure the time until the flame goes out.", "Keep the candle or starting conditions the same."], "mistake": "Do not assume the candle uses up all the oxygen before it goes out.", "model": null, "id": "y8-unit-14-investigate-candle", "unit": "y8-unit-14", "year": 8, "number": 1, "marks": 3, "cards": [{"term": "Independent variable", "definition": "The thing you choose to change in a test."}, {"term": "Endpoint", "definition": "The clear event that tells you when to stop measuring."}], "quiz": {"q": "What should stay the same in a candle and container-volume test?", "opts": ["The candle and the rule for when timing stops.", "The container volume.", "Nothing."], "a": 0, "why": "Keep other things the same so you can compare the effect of container volume."}, "misconception": {"q": "What should stay the same in a candle and container-volume test? Sam answers: “The container volume.” Explain why this is wrong.", "m": 2, "ms": ["The candle and the rule for when timing stops.", "Keep other things the same so you can compare the effect of container volume."]}}, {"key": "investigate-bounce", "title": "Testing bouncing balls", "notes": ["A dropped ball transfers energy as it falls and bounces. Some energy heats the ball, floor and air. Some is carried away by sound.", "The ball usually rises to a lower height after the bounce. Compare balls using the same drop height and surface. Release each ball without pushing it."], "worked": "Drop two balls from the same measured height. Record the highest point after the first bounce. Repeat and compare their mean rebound heights.", "question": "Why does a ball usually bounce lower than its drop height? How would you compare two balls fairly?", "scheme": ["Some energy transfers to heating and sound.", "Less remains for the ball to rise again.", "Use the same drop height and surface, and release without pushing."], "mistake": "Energy has not vanished when the bounce is lower. Some has moved to the surroundings.", "model": null, "id": "y8-unit-14-investigate-bounce", "unit": "y8-unit-14", "year": 8, "number": 2, "marks": 3, "cards": [{"term": "Rebound height", "definition": "The highest point a ball reaches after a bounce."}, {"term": "Dissipation", "definition": "Energy spreading to the surroundings and becoming less useful."}], "quiz": {"q": "Why does a ball usually bounce lower than its drop height?", "opts": ["Energy is destroyed.", "Gravity switches off during the bounce.", "Some energy transfers to heating and sound."], "a": 2, "why": "Less energy remains for lifting the ball, but total energy is still conserved."}, "misconception": {"q": "Why does a ball usually bounce lower than its drop height? Sam answers: “Energy is destroyed.” Explain why this is wrong.", "m": 2, "ms": ["Some energy transfers to heating and sound.", "Less energy remains for lifting the ball, but total energy is still conserved."]}}, {"key": "investigate-bungee", "title": "Testing a stretchy cord", "notes": ["A stretched cord becomes longer. Extension is the extra length, not the total length. Extension = stretched length − original length.", "Change the load and measure the extension. Use the same cord and allow it to settle. Use small safe loads and keep the landing space clear."], "worked": "A cord starts at 20 cm and stretches to 28 cm. Its extension is 28 − 20 = 8 cm. Check that a test load will not reach the floor.", "question": "How do you find a cord's extension? Give two things to keep the same when testing loads.", "scheme": ["Subtract original length from stretched length.", "Keep the same cord and its starting length.", "Keep the measuring method and settling time the same."], "mistake": "Use a small model. Do not test a homemade bungee with a person.", "model": null, "id": "y8-unit-14-investigate-bungee", "unit": "y8-unit-14", "year": 8, "number": 3, "marks": 3, "cards": [{"term": "Extension", "definition": "Stretched length minus original length."}, {"term": "Elastic deformation", "definition": "A change of shape that reverses when the force is removed."}], "quiz": {"q": "A cord stretches from 20 cm to 28 cm. What is its extension?", "opts": ["8 cm.", "28 cm.", "48 cm."], "a": 0, "why": "Extension is the extra length: 28 − 20 = 8 cm."}, "misconception": {"q": "A cord stretches from 20 cm to 28 cm. What is its extension? Sam answers: “28 cm.” Explain why this is wrong.", "m": 2, "ms": ["8 cm.", "Extension is the extra length: 28 − 20 = 8 cm."]}}, {"key": "investigate-conduction", "title": "Comparing heat transfer through metals", "notes": ["Conduction transfers energy through a material. Metals are usually good thermal conductors. A fair comparison changes the metal, not several other things.", "Use rods with the same length and thickness. Heat them in the same way for the same time. Use the same test for deciding how fast energy reaches the end."], "worked": "Two rods have matching sizes and start at the same temperature. One end of each receives the same heating. Compare what happens at the other ends.", "question": "Give two things to keep the same when comparing heat transfer through metal rods. Explain one.", "scheme": ["Use rods with the same length and thickness.", "Use the same heating and starting temperature.", "These controls stop size or heating differences from causing the result."], "mistake": "A thicker or shorter rod could change the result even if the metal stayed the same.", "model": null, "id": "y8-unit-14-investigate-conduction", "unit": "y8-unit-14", "year": 8, "number": 4, "marks": 3, "cards": [{"term": "Thermal conductor", "definition": "A material that transfers energy easily by conduction."}, {"term": "Fair comparison", "definition": "A test keeping other factors the same so one change can be compared."}], "quiz": {"q": "What must you control when comparing metal rods?", "opts": ["Rod size and the heating method.", "Nothing.", "Only the colour of the table."], "a": 0, "why": "A size or heating difference could change the result, even without changing the metal."}, "misconception": {"q": "What must you control when comparing metal rods? Sam answers: “Nothing.” Explain why this is wrong.", "m": 2, "ms": ["Rod size and the heating method.", "A size or heating difference could change the result, even without changing the metal."]}}, {"key": "investigate-cupcake", "title": "Testing falling paper cases", "notes": ["A falling paper case has weight downwards and air resistance upwards. Air resistance increases as it speeds up. At terminal velocity these forces balance and its speed stays steady.", "Measure time over a known falling distance. Distance ÷ time gives average speed. One average cannot show whether speed stayed steady throughout."], "worked": "Time a case over two equal sections of its fall. Similar times suggest a similar speed in those sections. Repeat before deciding whether it reached a steady speed.", "question": "Why does one average speed not prove a falling paper case reached terminal velocity?", "scheme": ["Average speed covers the whole timed section.", "The case could have changed speed during that section.", "Compare speeds in separate sections to check whether it became steady."], "mistake": "Terminal velocity means steady speed with balanced forces, not the highest speed in every fall.", "model": null, "id": "y8-unit-14-investigate-cupcake", "unit": "y8-unit-14", "year": 8, "number": 5, "marks": 3, "cards": [{"term": "Drag", "definition": "A force that opposes movement through air or water."}, {"term": "Terminal velocity", "definition": "Steady falling speed when weight and drag balance."}], "quiz": {"q": "Does one average falling speed prove terminal velocity was reached?", "opts": ["No. Speed could have changed during the timed part.", "Yes, every average is a terminal velocity.", "Yes, if the object is made of paper."], "a": 0, "why": "Compare speeds in different parts of the fall to check whether speed became steady."}, "misconception": {"q": "Does one average falling speed prove terminal velocity was reached? Sam answers: “Yes, every average is a terminal velocity.” Explain why this is wrong.", "m": 2, "ms": ["No. Speed could have changed during the timed part.", "Compare speeds in different parts of the fall to check whether speed became steady."]}}, {"key": "investigate-salt", "title": "Testing how quickly salt dissolves", "notes": ["Salt dissolves in water to make a solution. Dissolving time is the time until the solid has dissolved. Keep stirring, water volume and temperature the same.", "A saturated solution cannot dissolve more salt at that temperature. Extra salt then remains as solid. That makes a “time until all dissolved” test impossible to finish."], "worked": "Add a small measured salt mass and time it. Repeat with other masses using fresh water each time. Stop increasing the mass before the solution becomes saturated.", "question": "Why is a dissolving-time test difficult once the solution is saturated?", "scheme": ["The solution cannot dissolve any more salt at that temperature.", "Some solid salt remains.", "There is no finishing time when “all the salt has dissolved”."], "mistake": "Faster dissolving and greater solubility are different ideas.", "model": null, "id": "y8-unit-14-investigate-salt", "unit": "y8-unit-14", "year": 8, "number": 6, "marks": 3, "cards": [{"term": "Solubility", "definition": "The maximum amount that dissolves in a given amount of solvent at a set temperature."}, {"term": "Dissolving rate", "definition": "How quickly a substance dissolves."}], "quiz": {"q": "What happens if extra salt is added to a saturated solution?", "opts": ["The salt becomes a different element.", "Some salt remains undissolved.", "All extra salt dissolves instantly."], "a": 1, "why": "No more can dissolve at that temperature, so some stays as a solid."}, "misconception": {"q": "What happens if extra salt is added to a saturated solution? Sam answers: “All extra salt dissolves instantly.” Explain why this is wrong.", "m": 2, "ms": ["Some salt remains undissolved.", "No more can dissolve at that temperature, so some stays as a solid."]}}, {"key": "investigate-diffusion", "title": "Testing how colour spreads in water", "notes": ["Dissolved colour particles spread by diffusion. Particles usually move faster in warmer water. Moving currents in the water can also carry the colour.", "Use the same dye amount and water volume. Use matching containers and do not stir. Let the water settle before adding the dye."], "worked": "Put the same dye drop into warm and cool water. Compare how far the colour spreads after the same time. Remember that warm water currents may also move it.", "question": "Give two controls for comparing dye in warm and cool water. Give one reason the test is not a perfect measure of diffusion.", "scheme": ["Keep dye amount and water volume the same.", "Use matching containers and no stirring.", "Convection currents can also carry the colour, so not all spreading is due to diffusion."], "mistake": "Water moving as a whole is convection, not just diffusion.", "model": null, "id": "y8-unit-14-investigate-diffusion", "unit": "y8-unit-14", "year": 8, "number": 7, "marks": 3, "cards": [{"term": "Diffusion", "definition": "Particles spreading from higher to lower concentration."}, {"term": "Convection", "definition": "Energy transfer as a liquid or gas moves from place to place."}], "quiz": {"q": "What else can spread dye in a warm-water test besides diffusion?", "opts": ["The dye turning into light.", "The water particles becoming larger.", "Convection currents moving the coloured water."], "a": 2, "why": "Moving water carries dye with it, so the test does not show diffusion alone."}, "misconception": {"q": "What else can spread dye in a warm-water test besides diffusion? Sam answers: “The dye turning into light.” Explain why this is wrong.", "m": 2, "ms": ["Convection currents moving the coloured water.", "Moving water carries dye with it, so the test does not show diffusion alone."]}}, {"key": "magnet", "title": "Magnets and magnetic fields", "notes": ["Magnets have a north pole and a south pole. Like poles repel and opposite poles attract. A magnetic field is the region where magnetic forces act.", "A compass needle is a small magnet. It turns to line up with the field. Outside a bar magnet, field arrows run from north to south."], "worked": "A magnet attracts an unmagnetised iron nail. The nail does not have to be a permanent magnet. Repulsion gives stronger evidence that an object is itself a magnet.", "question": "Why does attraction alone not prove that a metal object is a permanent magnet?", "scheme": ["A magnet can attract unmagnetised iron.", "The iron can become temporarily magnetic near the magnet.", "Repulsion between like poles is better evidence that the object is a magnet."], "mistake": "Not every metal is attracted to a magnet.", "model": null, "id": "y9-unit-01-magnet", "unit": "y9-unit-01", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Magnetic field", "definition": "The region where magnetic forces act."}, {"term": "Induced magnet", "definition": "A material that becomes magnetic near another magnet."}], "quiz": {"q": "Which is better evidence that an object is a magnet?", "opts": ["It is attracted to a magnet.", "It looks shiny.", "It repels one pole of a known magnet."], "a": 2, "why": "Unmagnetised iron can be attracted, but repulsion shows the object has a like magnetic pole."}, "misconception": {"q": "Which is better evidence that an object is a magnet? Sam answers: “It is attracted to a magnet.” Explain why this is wrong.", "m": 2, "ms": ["It repels one pole of a known magnet.", "Unmagnetised iron can be attracted, but repulsion shows the object has a like magnetic pole."]}}, {"key": "electromagnet", "title": "Making an electromagnet", "notes": ["Current in a wire produces a magnetic field. Coiling the wire makes a stronger field. An iron core can make the electromagnet stronger still.", "More coil turns can make it stronger at the same current. A larger current can also make it stronger. Switching the current off lets you control the magnet."], "worked": "To test coil turns fairly, keep the current the same. Use the same iron core each time. A relay uses an electromagnet to operate a switch.", "question": "Give two ways to strengthen an electromagnet. Name one control for testing the number of turns.", "scheme": ["Increase the current.", "Add more coil turns or an iron core.", "Keep current and the core the same when comparing coil turns."], "mistake": "Do not assume the current stays the same when you change the coil.", "model": null, "id": "y9-unit-01-electromagnet", "unit": "y9-unit-01", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Electromagnet", "definition": "A magnet made by an electric current in a coil."}, {"term": "Relay", "definition": "A switch operated by an electromagnet."}], "quiz": {"q": "How can you make an electromagnet stronger?", "opts": ["Remove all the turns.", "Switch the current off.", "Increase current or add more turns under fair conditions."], "a": 2, "why": "More current and more coil turns can make a stronger field. Control other factors when testing one change."}, "misconception": {"q": "How can you make an electromagnet stronger? Sam answers: “Remove all the turns.” Explain why this is wrong.", "m": 2, "ms": ["Increase current or add more turns under fair conditions.", "More current and more coil turns can make a stronger field. Control other factors when testing one change."]}}, {"key": "planning", "title": "Planning tests and taking measurements", "notes": ["Write steps that someone else could follow. Say what to measure and which units to use. Choose equipment that can measure the small changes you expect.", "Check that your equipment reads zero before you start. Repeat each measurement to spot results that do not fit. Calculate a mean by adding the readings and dividing by their number."], "worked": "Suppose ten pendulum swings take 12 seconds. One swing takes 12 ÷ 10 = 1.2 seconds. Timing several swings reduces the effect of your reaction time.", "question": "How could you improve the time measurement for one pendulum swing? Give two ideas and explain one.", "scheme": ["Time several swings, then divide by the number of swings.", "Repeat the measurement and calculate a mean.", "Use the same point to start and stop timing."], "mistake": "Repeating readings will not fix a clock that always reads too high.", "model": null, "id": "y9-unit-01-planning", "unit": "y9-unit-01", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Resolution", "definition": "The smallest change a measuring instrument can show."}, {"term": "Repeatability", "definition": "Getting similar results when the same person repeats the same test."}], "quiz": {"q": "Why time ten swings instead of one?", "opts": ["It reduces the effect of your reaction time on each swing's time.", "It fixes every equipment error.", "It makes the clock perfect."], "a": 0, "why": "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."}, "misconception": {"q": "Why time ten swings instead of one? Sam answers: “It fixes every equipment error.” Explain why this is wrong.", "m": 2, "ms": ["It reduces the effect of your reaction time on each swing's time.", "Divide the longer total time by ten. Your reaction time then has a smaller effect on each swing's time."]}}, {"key": "work", "title": "Work done and simple machines", "notes": ["Work is done when a force moves an object. It transfers energy. Work done = force × distance moved in the force's direction.", "Work is measured in joules, J. A simple machine can reduce the force you need. You then have to move that force over a greater distance."], "worked": "A 25 N force moves a load 4 m in its direction. Work done = 25 × 4 = 100 J. A pulley cannot create extra energy.", "question": "A 25 N force moves a load 4 m in its direction. Find the work done. Why can a machine not create extra energy?", "scheme": ["Work done = 25 × 4.", "Work done = 100 J.", "Energy is conserved: a smaller effort force must move further, and real machines also waste some energy."], "mistake": "Reducing the force with a machine does not give free energy.", "model": null, "id": "y9-unit-02-work", "unit": "y9-unit-02", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Work done", "definition": "Energy transferred when a force moves something through a distance."}, {"term": "Simple machine", "definition": "A device that can reduce a force by making it act over a greater distance."}], "quiz": {"q": "A perfect pulley halves the lifting force. What else changes?", "opts": ["The load has no weight.", "You pull the rope twice as far.", "You get twice as much energy for free."], "a": 1, "why": "A smaller force acts over a longer distance. The machine does not create energy."}, "misconception": {"q": "A perfect pulley halves the lifting force. What else changes? Sam answers: “You get twice as much energy for free.” Explain why this is wrong.", "m": 2, "ms": ["You pull the rope twice as far.", "A smaller force acts over a longer distance. The machine does not create energy."]}}, {"key": "food-energy", "title": "Comparing energy in foods", "notes": ["Food has a chemical energy store. Burning a food sample can heat water. A larger water temperature rise can suggest more energy was transferred.", "Compare energy for the same mass of food, such as one gram. Some energy heats the air and equipment instead of the water. Only use your teacher's method for burning foods."], "worked": "Two food samples may have different masses. A bigger sample could heat more water even if it gives less energy per gram. Divide the energy by the mass to compare them fairly.", "question": "Give two problems with comparing foods by burning them below water. Explain how one affects the result.", "scheme": ["Some energy heats the air or the equipment rather than the water.", "The food may not burn completely.", "These effects make the measured energy lower than the energy available in the food."], "mistake": "The temperature rise alone is not the total energy in the food.", "model": null, "id": "y9-unit-02-food-energy", "unit": "y9-unit-02", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Chemical energy store", "definition": "Energy stored in substances such as food, fuels and batteries."}, {"term": "Energy per gram", "definition": "The energy for each gram of a substance."}], "quiz": {"q": "Why compare food energy per gram?", "opts": ["Every food contains the same energy.", "The food samples might have different masses.", "A water temperature rise measures all the food's energy perfectly."], "a": 1, "why": "Comparing equal masses makes the comparison fairer."}, "misconception": {"q": "Why compare food energy per gram? Sam answers: “A water temperature rise measures all the food's energy perfectly.” Explain why this is wrong.", "m": 2, "ms": ["The food samples might have different masses.", "Comparing equal masses makes the comparison fairer."]}}, {"key": "moments", "title": "Levers and turning forces", "notes": ["A force can turn an object around a pivot. The turning effect is called a moment. A pivot is the point the object turns about.", "Moment = force × perpendicular distance from the pivot. Perpendicular means at right angles to the force's line. A balanced lever has equal clockwise and anticlockwise moments."], "worked": "A 12 N force acts 0.5 m from a pivot. Its moment is 12 × 0.5 = 6 N m. A force on the other side at 0.3 m must be 6 ÷ 0.3 = 20 N.", "question": "A 12 N force acts 0.5 m from a pivot. What opposite turning force at 0.3 m will balance it?", "scheme": ["First moment = 12 × 0.5 = 6 N m.", "For balance, the other moment must also be 6 N m.", "Other force = 6 ÷ 0.3 = 20 N."], "mistake": "Use the right-angle distance to the force's line, not any distance from the pivot.", "model": "lever", "id": "y9-unit-02-moments", "unit": "y9-unit-02", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Moment", "definition": "The turning effect of a force around a pivot."}, {"term": "Pivot", "definition": "The point an object turns around."}], "quiz": {"q": "Which distance is used to calculate a moment?", "opts": ["The right-angle distance from the pivot to the force's line.", "Any sloping distance from the pivot.", "The total length of the object in every case."], "a": 0, "why": "Moment uses the perpendicular, or right-angle, distance."}, "misconception": {"q": "Which distance is used to calculate a moment? Sam answers: “Any sloping distance from the pivot.” Explain why this is wrong.", "m": 2, "ms": ["The right-angle distance from the pivot to the force's line.", "Moment uses the perpendicular, or right-angle, distance."]}}, {"key": "thermal", "title": "Temperature and heating", "notes": ["Temperature tells you how hot or cold something is. Heating transfers energy from a warmer object to a cooler one. A thermal energy store also depends on the amount and type of material.", "Conduction transfers energy through a material. Particles pass energy to nearby particles. Metals conduct well; many plastics and trapped air conduct poorly."], "worked": "A hot cup contains less water than a warm bath. Temperature alone cannot tell you which has the larger thermal energy store. You must also consider the mass and material.", "question": "Why can temperature alone not compare the thermal energy stores of a cup of water and a bath?", "scheme": ["Temperature shows how hot the water is.", "The amount of water also affects the energy store.", "A bath has much more water, so a cooler bath can have a larger store."], "mistake": "Temperature and the amount of stored energy are not the same quantity.", "model": null, "id": "y9-unit-03-thermal", "unit": "y9-unit-03", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Temperature", "definition": "A measure of how hot or cold something is."}, {"term": "Conduction", "definition": "Energy transfer through a material without the material flowing as a whole."}], "quiz": {"q": "Must a hot small cup have more thermal energy than a cooler bath?", "opts": ["Yes. Temperature is the only factor.", "Yes. Cups always hold more water than baths.", "No. The mass of water also matters."], "a": 2, "why": "A bath can have a larger energy store because it holds much more water."}, "misconception": {"q": "Must a hot small cup have more thermal energy than a cooler bath? Sam answers: “Yes. Temperature is the only factor.” Explain why this is wrong.", "m": 2, "ms": ["No. The mass of water also matters.", "A bath can have a larger energy store because it holds much more water."]}}, {"key": "convection", "title": "Convection, radiation and insulation", "notes": ["In convection, warmer liquid or gas rises as cooler fluid sinks. This movement transfers energy. Thermal radiation transfers energy by infrared waves.", "Radiation can travel through empty space. Insulation slows unwanted energy transfer. Trapped air reduces conduction and stops large convection currents. A warmer liquid or gas expands and becomes less dense, so it rises."], "worked": "A coat traps layers of air close to your body. A shiny surface reflects much infrared radiation. Both can slow energy transfer to cooler surroundings.", "question": "How do trapped air and a shiny surface help keep something warm?", "scheme": ["Air is a poor conductor.", "Trapping it prevents large convection currents.", "A shiny surface reduces energy transfer by infrared radiation."], "mistake": "Heat is not a substance that rises. Warm fluids rise during convection.", "model": null, "id": "y9-unit-03-convection", "unit": "y9-unit-03", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Convection", "definition": "Energy transfer by the movement of a liquid or gas."}, {"term": "Thermal radiation", "definition": "Energy transfer by infrared waves."}, {"term": "Insulator", "definition": "A material or arrangement that slows energy transfer."}], "quiz": {"q": "Which method can transfer energy across empty space?", "opts": ["Convection.", "Conduction.", "Radiation."], "a": 2, "why": "Radiation needs no particles between objects. Conduction and convection do."}, "misconception": {"q": "Which method can transfer energy across empty space? Sam answers: “Convection.” Explain why this is wrong.", "m": 2, "ms": ["Radiation.", "Radiation needs no particles between objects. Conduction and convection do."]}}, {"key": "atmosphere", "title": "The atmosphere and carbon cycle", "notes": ["The atmosphere is the layer of gases around Earth. Air is mainly nitrogen, with oxygen and small amounts of other gases. Carbon dioxide is one of those gases.", "Photosynthesis removes carbon dioxide from the air. Respiration and burning fuels add carbon dioxide. Carbon moves between air, living things, water and rocks in the carbon cycle."], "worked": "A tree takes carbon dioxide from the air as it grows. An animal eating plant food uses the carbon compounds. Respiration returns some carbon dioxide to the air.", "question": "Name two processes that add carbon dioxide to the air and one that removes it.", "scheme": ["Respiration adds carbon dioxide.", "Burning fuels adds carbon dioxide.", "Photosynthesis removes carbon dioxide."], "mistake": "Plants both photosynthesise and respire.", "model": null, "id": "y9-unit-04-atmosphere", "unit": "y9-unit-04", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Atmosphere", "definition": "The gases around a planet."}, {"term": "Carbon cycle", "definition": "Carbon moving between living things, air, water and rocks."}], "quiz": {"q": "Which process removes carbon dioxide from the air?", "opts": ["Photosynthesis.", "Burning fuels.", "Aerobic respiration."], "a": 0, "why": "Plants take in carbon dioxide and use it to make glucose."}, "misconception": {"q": "Which process removes carbon dioxide from the air? Sam answers: “Burning fuels.” Explain why this is wrong.", "m": 2, "ms": ["Photosynthesis.", "Plants take in carbon dioxide and use it to make glucose."]}}, {"key": "climate", "title": "The greenhouse effect and climate", "notes": ["Climate describes weather patterns over many years. Greenhouse gases absorb infrared radiation leaving Earth. They send infrared radiation out in all directions, including back towards the surface.", "The natural greenhouse effect keeps Earth warmer. Human activities add extra greenhouse gases, including carbon dioxide. This strengthens warming and changes the climate."], "worked": "Burning coal, oil and gas adds carbon dioxide to the air. More outgoing infrared radiation is absorbed. Earth warms until energy entering and leaving balance again.", "question": "How can adding carbon dioxide to the air cause global warming?", "scheme": ["Earth gives out infrared radiation.", "Extra carbon dioxide absorbs more of it and sends some back towards the surface.", "This changes the energy balance and warms Earth."], "mistake": "The greenhouse effect and the hole in the ozone layer are different issues.", "model": null, "id": "y9-unit-04-climate", "unit": "y9-unit-04", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Greenhouse gas", "definition": "A gas that absorbs infrared radiation and sends it out in all directions."}, {"term": "Climate", "definition": "The pattern of weather over many years."}], "quiz": {"q": "How do extra greenhouse gases increase warming?", "opts": ["They make a hole in the ozone layer as the main cause.", "They create sunlight.", "They absorb more outgoing infrared radiation and send some back towards the surface."], "a": 2, "why": "More energy is kept in Earth's surface and atmosphere until a new balance is reached."}, "misconception": {"q": "How do extra greenhouse gases increase warming? Sam answers: “They make a hole in the ozone layer as the main cause.” Explain why this is wrong.", "m": 2, "ms": ["They absorb more outgoing infrared radiation and send some back towards the surface.", "More energy is kept in Earth's surface and atmosphere until a new balance is reached."]}}, {"key": "extraction", "title": "Getting metals from rocks", "notes": ["An ore is rock containing enough useful material to make extraction worthwhile. Many ores contain metals joined to oxygen. Extraction separates the metal from its compound.", "Carbon can remove oxygen from oxides of metals less reactive than carbon. Removing oxygen is called reduction. More reactive metals may need electricity for extraction."], "worked": "Iron is less reactive than carbon, so carbon can help extract it from iron oxide. Aluminium is more reactive than carbon. Aluminium is commonly extracted using electricity instead.", "question": "Why can carbon extract some metals from their oxides but is not normally used to extract aluminium?", "scheme": ["Carbon removes oxygen from oxides of metals less reactive than carbon.", "Aluminium is more reactive than carbon.", "Aluminium oxide therefore needs another method, usually electrolysis."], "mistake": "The extraction method depends on the metal's reactivity.", "model": null, "id": "y9-unit-05-extraction", "unit": "y9-unit-05", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Ore", "definition": "Rock containing enough useful material to make extraction worthwhile."}, {"term": "Reduction", "definition": "Removing oxygen from a metal oxide in these examples."}], "quiz": {"q": "Why is carbon not normally used to extract aluminium from its oxide?", "opts": ["Aluminium is less reactive than every metal.", "Carbon can extract every metal.", "Aluminium is more reactive than carbon."], "a": 2, "why": "Carbon cannot remove the oxygen from aluminium oxide by the usual carbon extraction method."}, "misconception": {"q": "Why is carbon not normally used to extract aluminium from its oxide? Sam answers: “Aluminium is less reactive than every metal.” Explain why this is wrong.", "m": 2, "ms": ["Aluminium is more reactive than carbon.", "Carbon cannot remove the oxygen from aluminium oxide by the usual carbon extraction method."]}}, {"key": "metals", "title": "Metals and reactivity", "notes": ["Metals usually conduct heat and electricity well. Many metals react with oxygen to make metal oxides. Gaining oxygen is called oxidation.", "Some metals react more easily than others. A more reactive metal can replace a less reactive metal in a compound. This is called displacement. Most metals can be shaped without breaking. Some non-metals are exceptions to the usual rules: graphite conducts electricity."], "worked": "Zinc is more reactive than copper. Zinc placed in copper sulfate solution can form zinc sulfate. Copper is left as a solid.", "question": "Zinc is more reactive than copper. What happens when zinc is put in copper sulfate solution? Explain why.", "scheme": ["Zinc displaces copper.", "Zinc sulfate and copper form.", "Zinc replaces copper because it is more reactive."], "mistake": "A less reactive metal cannot simply displace a more reactive one.", "model": null, "id": "y9-unit-05-metals", "unit": "y9-unit-05", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Displacement", "definition": "A more reactive element replacing a less reactive element in a compound."}, {"term": "Oxidation", "definition": "A reaction in which a substance gains oxygen, in these examples."}], "quiz": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate?", "opts": ["Yes, because all metals displace each other.", "Yes, because copper is coloured.", "No."], "a": 2, "why": "The more reactive metal displaces the less reactive metal, not the other way around."}, "misconception": {"q": "Iron is more reactive than copper. Can copper displace iron from iron sulfate? Sam answers: “Yes, because all metals displace each other.” Explain why this is wrong.", "m": 2, "ms": ["No.", "The more reactive metal displaces the less reactive metal, not the other way around."]}}, {"key": "recycle", "title": "Reusing and recycling metals", "notes": ["Reusing means using an item again. Recycling means processing waste material to make new products. Metals are often valuable to recycle.", "Recycling saves limited metal ores. It often uses less energy than extracting new metal. Collecting, sorting and processing waste still use energy and resources."], "worked": "An aluminium can can be collected and melted for new products. This reduces the need to mine more aluminium ore. The cans still need transport and sorting.", "question": "Give two benefits and one drawback of recycling metals.", "scheme": ["It saves limited metal ores.", "It often saves energy and reduces mining damage.", "Collection, transport and processing still use resources."], "mistake": "Recycling has costs and impacts, even when it is better than extracting new material.", "model": null, "id": "y9-unit-05-recycle", "unit": "y9-unit-05", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Reuse", "definition": "Using an item again."}, {"term": "Recycling", "definition": "Processing waste materials to make new products."}, {"term": "Life cycle", "definition": "The stages from getting raw materials to making, using and disposing of a product."}], "quiz": {"q": "Which statement about metal recycling is fair?", "opts": ["It has no benefits.", "It saves ores but collection and processing still use resources.", "It uses no energy at all."], "a": 1, "why": "Recycling can save ores and energy, but transport and processing still have costs."}, "misconception": {"q": "Which statement about metal recycling is fair? Sam answers: “It uses no energy at all.” Explain why this is wrong.", "m": 2, "ms": ["It saves ores but collection and processing still use resources.", "Recycling can save ores and energy, but transport and processing still have costs."]}}, {"key": "selection", "title": "Evolution by natural selection", "notes": ["Living things in a species have inherited differences. Some differences help them survive in their environment. Survivors are more likely to reproduce and pass on their genes.", "Over many generations, a helpful inherited feature can become more common. This process is called natural selection. It acts on a population, not by changing one animal because it needs to adapt."], "worked": "In a cold place, animals with thicker inherited fur may survive better. More of them reproduce and pass on genes for thicker fur. The feature may become more common over generations.", "question": "How can a helpful inherited feature become more common after the environment changes?", "scheme": ["Individuals already have inherited differences.", "Those with a helpful feature are more likely to survive and reproduce.", "They pass the feature on, so it becomes more common over generations."], "mistake": "An animal does not grow a new gene just because the environment changes.", "model": null, "id": "y9-unit-06-selection", "unit": "y9-unit-06", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Natural selection", "definition": "Helpful inherited features becoming more common through survival and reproduction over generations."}, {"term": "Inherited variation", "definition": "Differences passed on through genes from parents to offspring."}], "quiz": {"q": "What is needed for natural selection to change a population?", "opts": ["All individuals being exactly the same.", "Animals choosing new genes when needed.", "Inherited differences that affect survival and reproduction."], "a": 2, "why": "Survivors can pass helpful inherited features to their offspring."}, "misconception": {"q": "What is needed for natural selection to change a population? Sam answers: “All individuals being exactly the same.” Explain why this is wrong.", "m": 2, "ms": ["Inherited differences that affect survival and reproduction.", "Survivors can pass helpful inherited features to their offspring."]}}, {"key": "evidence-evolution", "title": "Evidence for evolution", "notes": ["Evolution is change in inherited features over many generations. Fossils show that living things have changed over long periods. DNA similarities also help show how species are related.", "Darwin helped explain evolution by natural selection. Scientific explanations must be tested against evidence. A change during one lifetime is not always inherited."], "worked": "Training can make a person's muscles larger. That does not mean their children inherit those larger trained muscles. Inherited evolution depends on genes passed between generations.", "question": "Why is building bigger muscles through training not the same as inherited evolution?", "scheme": ["Training changes an individual during their lifetime.", "The larger trained muscles are not directly passed on in genes.", "Inherited evolution involves changes passed on across generations."], "mistake": "A scientific theory is an explanation supported by evidence, not just a guess.", "model": null, "id": "y9-unit-06-evidence-evolution", "unit": "y9-unit-06", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Scientific theory", "definition": "An explanation supported by evidence and testing."}, {"term": "Acquired characteristic", "definition": "A feature gained during a lifetime, such as a scar."}], "quiz": {"q": "Why is muscle training not the same as inherited evolution?", "opts": ["The larger trained muscles are not directly passed on in genes.", "All exercise creates a new species.", "Children inherit every change their parents experience."], "a": 0, "why": "Training changes an individual. Inherited evolution involves changes passed on across generations."}, "misconception": {"q": "Why is muscle training not the same as inherited evolution? Sam answers: “All exercise creates a new species.” Explain why this is wrong.", "m": 2, "ms": ["The larger trained muscles are not directly passed on in genes.", "Training changes an individual. Inherited evolution involves changes passed on across generations."]}}, {"key": "biodiversity", "title": "Protecting living things", "notes": ["Biodiversity means the variety of living things in an area or on Earth. A species becomes extinct when its last member dies. Habitat loss can put species at risk.", "Conservation protects living things and their habitats. Breeding programmes can help increase numbers of endangered animals. They also need suitable habitats and enough inherited variation."], "worked": "A breeding programme may produce more animals. If the wild habitat is still destroyed, releasing them may fail. Protecting habitat tackles part of the original problem.", "question": "Give one way to protect a habitat. Why might breeding endangered animals alone not save a species?", "scheme": ["Protect or restore the habitat, for example with a nature reserve.", "Animals also need a safe place with food and space.", "Breeding alone cannot remove threats such as habitat loss or may leave too little inherited variation."], "mistake": "Increasing animal numbers is only part of conservation.", "model": null, "id": "y9-unit-06-biodiversity", "unit": "y9-unit-06", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Biodiversity", "definition": "The variety of living things, including different species and inherited differences."}, {"term": "Extinction", "definition": "When the last living member of a species dies."}, {"term": "Conservation", "definition": "Protecting living things and their habitats."}], "quiz": {"q": "Why might captive breeding alone fail to save a species?", "opts": ["The animals still need a safe, suitable wild habitat.", "Habitat never matters.", "All released animals are guaranteed to survive."], "a": 0, "why": "Breeding more animals cannot by itself fix habitat loss or other threats in the wild."}, "misconception": {"q": "Why might captive breeding alone fail to save a species? Sam answers: “Habitat never matters.” Explain why this is wrong.", "m": 2, "ms": ["The animals still need a safe, suitable wild habitat.", "Breeding more animals cannot by itself fix habitat loss or other threats in the wild."]}}, {"key": "inheritance", "title": "DNA, genes and chromosomes", "notes": ["DNA carries genetic information. Chromosomes are long, packaged DNA molecules found in a cell's nucleus. A gene is a section of DNA.", "Genes help control how a body grows and works. Different versions of a gene are called alleles. Offspring inherit genetic information from their parents."], "worked": "Think of a chromosome as a long book of instructions. A gene is a section of those instructions. The comparison helps show the relationship, but real DNA is a molecule.", "question": "How are DNA, chromosomes and genes related?", "scheme": ["Chromosomes contain long DNA molecules.", "Genes are sections of DNA.", "Genes carry information that helps control features or how cells work."], "mistake": "A gene is part of DNA. It is not a tiny organism inside the nucleus.", "model": null, "id": "y9-unit-07-inheritance", "unit": "y9-unit-07", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Gene", "definition": "A section of DNA carrying information that helps control how cells work or features develop."}, {"term": "Allele", "definition": "A different version of a gene."}, {"term": "Chromosome", "definition": "A long, packaged DNA molecule."}], "quiz": {"q": "What is an allele?", "opts": ["A bone in a joint.", "A version of a gene.", "A whole animal cell."], "a": 1, "why": "A gene can have different versions called alleles."}, "misconception": {"q": "What is an allele? Sam answers: “A whole animal cell.” Explain why this is wrong.", "m": 2, "ms": ["A version of a gene.", "A gene can have different versions called alleles."]}}, {"key": "dna-practical", "title": "Extracting DNA", "notes": ["DNA carries genetic information in cells. A simple extraction can collect visible clumps containing DNA. The clumps contain many molecules, not one visible DNA strand.", "Detergent helps break open cell membranes. Salt helps the DNA clump together. Cold ethanol helps DNA come out of the liquid as a solid."], "worked": "Mash fruit to break up the tissue. Use the teacher's detergent and salt method, then add cold ethanol safely. Pale strands or clumps can appear.", "question": "What do detergent and ethanol do in a classroom DNA extraction?", "scheme": ["Detergent breaks open cell membranes.", "This releases DNA from cells.", "Ethanol makes DNA come out of the liquid so it can be collected."], "mistake": "The visible clumps are not a clear view of a single DNA double helix.", "model": null, "id": "y9-unit-07-dna-practical", "unit": "y9-unit-07", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "DNA", "definition": "The molecule that carries genetic information."}, {"term": "Precipitate", "definition": "A solid that comes out of a solution."}], "quiz": {"q": "What are visible clumps in a classroom DNA extraction?", "opts": ["Many DNA molecules collected together, with possible other material.", "One clearly visible double helix.", "A complete living organism."], "a": 0, "why": "One DNA molecule is too small to see like this. Many collected molecules form the visible clumps."}, "misconception": {"q": "What are visible clumps in a classroom DNA extraction? Sam answers: “One clearly visible double helix.” Explain why this is wrong.", "m": 2, "ms": ["Many DNA molecules collected together, with possible other material.", "One DNA molecule is too small to see like this. Many collected molecules form the visible clumps."]}}, {"key": "cross", "title": "Simple genetic crosses", "notes": ["Alleles are different versions of a gene. A genotype is the allele combination, such as Aa. A phenotype is the feature that results.", "In a simple dominant model, A shows its effect in AA and Aa. The recessive feature shows with aa. A genetic cross shows the chances for each offspring. A dominant allele can show its effect with one copy in this simple model."], "worked": "Cross Aa with aa and the possible combinations are Aa, Aa, aa and aa. Two of the four show the recessive feature. The chance is 2 out of 4, or 50%.", "question": "In a simple dominant model, cross Aa with aa. What is the chance of the recessive feature?", "scheme": ["One parent can pass on A or a and the other passes on a.", "The outcomes are Aa, Aa, aa and aa.", "The chance of aa is 2/4 = 50%."], "mistake": "A 50% chance does not promise exactly half of a small family will have a feature.", "model": "genetics", "id": "y9-unit-07-cross", "unit": "y9-unit-07", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Genotype", "definition": "The allele combination, such as Aa."}, {"term": "Phenotype", "definition": "The feature that results from genes and the environment."}, {"term": "Recessive allele", "definition": "An allele whose feature shows only with two copies in a simple dominant model."}], "quiz": {"q": "For Aa × Aa in a simple dominant model, what is the chance of aa?", "opts": ["1 in 2.", "Certain.", "1 in 4."], "a": 2, "why": "The four possible combinations are AA, Aa, Aa and aa."}, "misconception": {"q": "For Aa × Aa in a simple dominant model, what is the chance of aa? Sam answers: “1 in 2.” Explain why this is wrong.", "m": 2, "ms": ["1 in 4.", "The four possible combinations are AA, Aa, Aa and aa."]}}, {"key": "gm", "title": "Selective breeding and genetic modification", "notes": ["Selective breeding means choosing parents with useful inherited features. Breeders repeat this over generations. Genetic modification changes an organism's DNA using laboratory techniques.", "A gene can sometimes be moved from one organism into another. A new feature may be useful, but benefits and risks need checking. Different uses have different benefits and concerns."], "worked": "Bacteria can be genetically modified to make human insulin. The insulin is collected and used as a medicine. This is different from choosing parent animals for breeding.", "question": "How does genetic modification differ from selective breeding? Give a possible benefit of one named use.", "scheme": ["Genetic modification directly changes DNA using laboratory techniques.", "Selective breeding chooses parents and breeds them over generations.", "For example, modified bacteria can make insulin for medicine."], "mistake": "Genetic modification and selective breeding are different methods.", "model": null, "id": "y9-unit-07-gm", "unit": "y9-unit-07", "year": 9, "number": 4, "marks": 3, "cards": [{"term": "Genetic modification", "definition": "Changing DNA using laboratory techniques."}, {"term": "Selective breeding", "definition": "Choosing parents with useful inherited features and breeding them over generations."}], "quiz": {"q": "How is selective breeding different from genetic modification?", "opts": ["It needs no parents or offspring.", "It chooses parents instead of directly changing their DNA in a laboratory.", "It always moves a gene between unrelated species."], "a": 1, "why": "Breeders choose which organisms reproduce. Genetic modification directly changes genetic material."}, "misconception": {"q": "How is selective breeding different from genetic modification? Sam answers: “It always moves a gene between unrelated species.” Explain why this is wrong.", "m": 2, "ms": ["It chooses parents instead of directly changing their DNA in a laboratory.", "Breeders choose which organisms reproduce. Genetic modification directly changes genetic material."]}}, {"key": "waves", "title": "Wave shapes and wave speed", "notes": ["Waves transfer energy from place to place. In a transverse wave, vibrations are across the direction the wave travels. In a longitudinal wave, vibrations are along the direction it travels.", "Wavelength is the distance between matching points, such as two neighbouring crests. Frequency is the number of complete waves each second. Wave speed = frequency × wavelength."], "worked": "A wave has frequency 4 Hz and wavelength 1.5 m. Speed = 4 × 1.5 = 6 m/s. Its period, the time for one wave, is 1 ÷ 4 = 0.25 s.", "question": "A wave has frequency 4 Hz and wavelength 1.5 m. Find its speed and the time for one wave.", "scheme": ["Speed = 4 × 1.5 = 6 m/s.", "Period = 1 ÷ frequency.", "Period = 0.25 s."], "mistake": "The wave travels along, but the material only vibrates near its own position.", "model": "wave", "id": "y9-unit-08-waves", "unit": "y9-unit-08", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Transverse wave", "definition": "A wave whose vibrations are across the direction it travels."}, {"term": "Wavelength", "definition": "The distance between matching points on neighbouring waves."}, {"term": "Period", "definition": "The time for one complete wave or vibration."}], "quiz": {"q": "A wave has frequency 3 Hz and wavelength 2 m. What is its speed?", "opts": ["5 m/s.", "6 m/s.", "1.5 m/s."], "a": 1, "why": "Wave speed = frequency × wavelength = 3 × 2 = 6 m/s."}, "misconception": {"q": "A wave has frequency 3 Hz and wavelength 2 m. What is its speed? Sam answers: “1.5 m/s.” Explain why this is wrong.", "m": 2, "ms": ["6 m/s.", "Wave speed = frequency × wavelength = 3 × 2 = 6 m/s."]}}, {"key": "ultrasound", "title": "Ultrasound and echoes", "notes": ["Ultrasound is sound above about 20,000 Hz. Most people cannot hear it. Like other sound, it needs a material to travel through.", "Ultrasound reflects when it meets some boundaries between materials. Scanners use the returning signals to build an image. Echo timing can also measure a distance."], "worked": "Multiply sound speed by the time for the echo to return. This gives the distance there and back. Divide by two to find the distance to the reflecting surface.", "question": "Why must you divide speed × echo time by two when finding a distance with ultrasound?", "scheme": ["The time includes the outward and return journeys.", "Speed × time gives the total distance travelled.", "The reflecting surface is half that distance away."], "mistake": "Ultrasound is a sound wave, not an electromagnetic wave.", "model": null, "id": "y9-unit-08-ultrasound", "unit": "y9-unit-08", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Ultrasound", "definition": "Sound with a frequency above about 20,000 Hz."}, {"term": "Time of flight", "definition": "The time a signal takes to travel a particular distance."}], "quiz": {"q": "Can ultrasound travel across empty space?", "opts": ["Yes, because it is light.", "Yes, because it has a high pitch.", "No. Sound needs a material to travel through."], "a": 2, "why": "Ultrasound is still sound. It needs particles to pass on the vibrations."}, "misconception": {"q": "Can ultrasound travel across empty space? Sam answers: “Yes, because it is light.” Explain why this is wrong.", "m": 2, "ms": ["No. Sound needs a material to travel through.", "Ultrasound is still sound. It needs particles to pass on the vibrations."]}}, {"key": "em", "title": "The electromagnetic spectrum", "notes": ["The electromagnetic spectrum includes radio, microwave, infrared, visible, ultraviolet, X-ray and gamma waves. All can travel through empty space. They all have the same speed in a vacuum.", "Different waves have different uses. X-rays pass through soft tissue more easily than through bone. Some high-energy waves can damage cells, so exposure must be controlled."], "worked": "An X-ray image shows differences in how much radiation tissues absorb. Bones usually appear clearly against softer tissue. The dose is kept as low as needed for a useful image.", "question": "Why are X-rays useful for images of bones? Why must exposure be controlled?", "scheme": ["Bone and soft tissue absorb X-rays differently.", "A detector records the differences to make an image.", "X-rays can damage cells, so unnecessary exposure is avoided."], "mistake": "Higher-frequency electromagnetic waves do not travel faster in a vacuum.", "model": null, "id": "y9-unit-08-em", "unit": "y9-unit-08", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Electromagnetic wave", "definition": "A wave, such as light or radio, that can travel through empty space."}, {"term": "Ionisation", "definition": "An atom or particle becoming charged by losing or gaining electrons."}], "quiz": {"q": "Which electromagnetic waves travel at the same speed in a vacuum?", "opts": ["Only radio and sound.", "All types of electromagnetic wave.", "Only visible colours."], "a": 1, "why": "All electromagnetic waves have the same vacuum speed. Sound is not an electromagnetic wave."}, "misconception": {"q": "Which electromagnetic waves travel at the same speed in a vacuum? Sam answers: “Only visible colours.” Explain why this is wrong.", "m": 2, "ms": ["All types of electromagnetic wave.", "All electromagnetic waves have the same vacuum speed. Sound is not an electromagnetic wave."]}}, {"key": "earth", "title": "Inside Earth and types of rock", "notes": ["Earth has a thin solid crust and a thick mantle. The mantle is mostly solid rock that can slowly change shape. The outer core is liquid and the inner core is solid.", "Igneous rock forms when molten rock cools and becomes solid. Sedimentary rock often forms from layers of small pieces pressed and cemented together. Metamorphic rock forms when heat and pressure change existing rock without melting it."], "worked": "Magma that cools slowly can form large crystals. Lava that cools quickly usually forms smaller crystals. Melting and cooling a rock makes a new igneous rock.", "question": "How are igneous and metamorphic rocks made?", "scheme": ["Igneous rock forms when molten rock cools and becomes solid.", "Metamorphic rock forms when heat and pressure change existing rock.", "Metamorphic change happens without the rock melting."], "mistake": "The mantle is not a giant ocean of liquid magma.", "model": null, "id": "y9-unit-09-earth", "unit": "y9-unit-09", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Crust", "definition": "Earth's thin, solid outer layer."}, {"term": "Mantle", "definition": "The mostly solid rock layer below the crust that can slowly change shape."}, {"term": "Igneous rock", "definition": "Rock made when molten rock cools and becomes solid."}], "quiz": {"q": "Which statement about Earth is correct?", "opts": ["The crust is Earth's thickest layer.", "The mantle is mostly solid and the outer core is liquid.", "The whole mantle is liquid magma."], "a": 1, "why": "The mantle is mostly solid rock, even though it can move very slowly over long times."}, "misconception": {"q": "Which statement about Earth is correct? Sam answers: “The whole mantle is liquid magma.” Explain why this is wrong.", "m": 2, "ms": ["The mantle is mostly solid and the outer core is liquid.", "The mantle is mostly solid rock, even though it can move very slowly over long times."]}}, {"key": "sediment", "title": "Weathering, erosion and fossils", "notes": ["Weathering breaks rock into smaller pieces where it is. Erosion removes and carries rock material away. Water, wind and ice can move the pieces.", "Sediment settles in layers. Pressure and natural cements can turn layers into sedimentary rock. Fossils are remains or signs of past living things preserved in rock."], "worked": "An animal buried quickly in sediment may be protected from scavengers. Its remains may then be preserved as the sediment becomes rock. Most dead organisms do not become fossils.", "question": "How is weathering different from erosion? How can burial help a fossil form?", "scheme": ["Weathering breaks rock down in place.", "Erosion carries rock material away.", "Quick burial can protect remains so they have a better chance of being preserved."], "mistake": "Fossils can be traces such as footprints, not just bones.", "model": null, "id": "y9-unit-09-sediment", "unit": "y9-unit-09", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Weathering", "definition": "Rock breaking down where it is."}, {"term": "Erosion", "definition": "Rock material being removed and carried away."}, {"term": "Fossil", "definition": "Preserved remains or signs of a past living thing."}], "quiz": {"q": "How is erosion different from weathering?", "opts": ["They always mean exactly the same thing.", "Erosion only happens inside Earth's core.", "Erosion carries material away; weathering breaks it down in place."], "a": 2, "why": "A river carrying broken rock is erosion. Cracking rock in place is weathering."}, "misconception": {"q": "How is erosion different from weathering? Sam answers: “They always mean exactly the same thing.” Explain why this is wrong.", "m": 2, "ms": ["Erosion carries material away; weathering breaks it down in place.", "A river carrying broken rock is erosion. Cracking rock in place is weathering."]}}, {"key": "rock-cycle", "title": "The rock cycle", "notes": ["Rocks can change from one type into another. Weathering, erosion, heat, pressure, melting and cooling all play a part. These changes form the rock cycle.", "There is no single starting point or fixed route. Many rock changes take millions of years. Melting destroys the old rock's structure."], "worked": "A sedimentary rock may be buried and heated until it melts. The molten rock later cools and becomes solid. It is now igneous rock.", "question": "Describe how a sedimentary rock could become an igneous rock.", "scheme": ["The sedimentary rock is heated enough to melt.", "Molten rock then cools.", "It becomes solid igneous rock."], "mistake": "Heat and pressure without melting make metamorphic rock, not igneous rock.", "model": null, "id": "y9-unit-09-rock-cycle", "unit": "y9-unit-09", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Metamorphic rock", "definition": "Rock changed by heat and pressure without melting."}, {"term": "Rock cycle", "definition": "The processes that change rocks from one type into another."}], "quiz": {"q": "What forms when molten rock cools and becomes solid?", "opts": ["Liquid sediment.", "Igneous rock.", "Only a fossil."], "a": 1, "why": "Igneous rocks form by cooling and solidifying molten rock."}, "misconception": {"q": "What forms when molten rock cools and becomes solid? Sam answers: “Only a fossil.” Explain why this is wrong.", "m": 2, "ms": ["Igneous rock.", "Igneous rocks form by cooling and solidifying molten rock."]}}, {"key": "space", "title": "The Solar System and space distances", "notes": ["The Sun is a star at the centre of our Solar System. Planets orbit the Sun. The Solar System is part of the Milky Way galaxy.", "A galaxy contains huge numbers of stars. Distances in space are enormous. A light-year is the distance light travels in one year. Stars make their own light, but planets and moons mainly reflect starlight. An astronomical unit is about the distance from Earth to the Sun."], "worked": "A classroom Solar System diagram often makes planets too large. The gaps may also be much too small. Always check whether sizes and distances are drawn to scale.", "question": "What does a light-year measure? Give one problem with a typical classroom Solar System diagram.", "scheme": ["A light-year measures distance.", "It is how far light travels in one year.", "Planet sizes or distances may not be drawn to the same scale."], "mistake": "A light-year is a distance, not a time.", "model": null, "id": "y9-unit-10-space", "unit": "y9-unit-10", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Light-year", "definition": "The distance light travels in one year."}, {"term": "Solar System", "definition": "The Sun and the objects that orbit it."}, {"term": "Galaxy", "definition": "A huge collection of stars, gas and other matter held together by gravity."}], "quiz": {"q": "What does a light-year measure?", "opts": ["Mass.", "Distance.", "Time."], "a": 1, "why": "The word “year” is part of the name, but a light-year is a distance."}, "misconception": {"q": "What does a light-year measure? Sam answers: “Time.” Explain why this is wrong.", "m": 2, "ms": ["Distance.", "The word “year” is part of the name, but a light-year is a distance."]}}, {"key": "orbits", "title": "Days, years and seasons", "notes": ["Earth spins on its axis once in about 24 hours. Earth orbits the Sun once in about a year. Its axis is tilted.", "The tilt causes the seasons. A hemisphere tilted towards the Sun has longer days and more direct sunlight. The other hemisphere has shorter days and less direct sunlight. Gravity keeps changing the direction of an orbiting object. The orbit of the Moon is tilted, so eclipses do not happen every month."], "worked": "When the Northern Hemisphere has summer, the Southern Hemisphere has winter. Six months later the situation is reversed. Earth's tilt, rather than its distance from the Sun, explains this pattern.", "question": "Why do the Northern and Southern Hemispheres have opposite seasons?", "scheme": ["Earth's axis is tilted.", "One hemisphere gets longer days and more direct sunlight.", "At the same time the other gets shorter days and less direct sunlight."], "mistake": "Summer is not caused by Earth being much closer to the Sun.", "model": "orbit", "id": "y9-unit-10-orbits", "unit": "y9-unit-10", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Orbit", "definition": "The path of one object around another under gravity."}, {"term": "Axial tilt", "definition": "The lean of a planet's spin axis compared with its orbit."}], "quiz": {"q": "What mainly causes Earth's seasons?", "opts": ["A large yearly change in Earth–Sun distance.", "The Moon making its own light.", "Earth's tilted axis."], "a": 2, "why": "The tilt changes day length and how directly sunlight reaches each hemisphere."}, "misconception": {"q": "What mainly causes Earth's seasons? Sam answers: “A large yearly change in Earth–Sun distance.” Explain why this is wrong.", "m": 2, "ms": ["Earth's tilted axis.", "The tilt changes day length and how directly sunlight reaches each hemisphere."]}}, {"key": "moon", "title": "Moon phases and eclipses", "notes": ["The Moon reflects sunlight rather than making its own light. The Sun lights roughly half of the Moon. As it orbits Earth, we see different amounts of this lit half.", "These changing views are called Moon phases. A lunar eclipse happens when the Moon enters Earth's shadow. A solar eclipse happens when the Moon blocks sunlight from reaching part of Earth."], "worked": "A crescent Moon means we see only a small part of its sunlit half. Earth's shadow is not causing that ordinary phase. An eclipse needs the Sun, Earth and Moon to line up in a particular way.", "question": "How is an ordinary Moon phase different from a lunar eclipse?", "scheme": ["Phases happen because we see different amounts of the Moon's lit half.", "They happen as the Moon moves around Earth.", "A lunar eclipse happens when Earth's shadow falls on the Moon."], "mistake": "Earth's shadow does not cause normal Moon phases.", "model": "orbit", "id": "y9-unit-10-moon", "unit": "y9-unit-10", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Phase", "definition": "The amount of the Moon's sunlit half that we can see."}, {"term": "Lunar eclipse", "definition": "The Moon passing through Earth's shadow."}, {"term": "Solar eclipse", "definition": "The Moon blocking sunlight from reaching part of Earth."}], "quiz": {"q": "What causes normal Moon phases?", "opts": ["The Moon switches its own light on and off.", "We see different amounts of the sunlit half as the Moon orbits Earth.", "Earth's shadow covers it every night."], "a": 1, "why": "The Moon reflects sunlight. Its orbit changes our view of its lit half."}, "misconception": {"q": "What causes normal Moon phases? Sam answers: “Earth's shadow covers it every night.” Explain why this is wrong.", "m": 2, "ms": ["We see different amounts of the sunlit half as the Moon orbits Earth.", "The Moon reflects sunlight. Its orbit changes our view of its lit half."]}}, {"key": "friction", "title": "Friction, drag and changing shape", "notes": ["Friction acts between surfaces and opposes sliding. Drag opposes motion through air or water. Both can transfer energy to the surroundings by heating.", "An elastic change is reversed when the force is removed. A plastic change is permanent. At steady speed on a level road, driving and resisting forces balance."], "worked": "A cyclist pedals to balance air resistance and friction. The bicycle can then keep a steady speed. Without the driving force, the resisting forces slow it down.", "question": "Why must a cyclist keep applying a driving force to move at steady speed on a level road?", "scheme": ["Friction and air resistance act backwards.", "A forward driving force balances these forces.", "The resultant is zero, so the speed stays steady."], "mistake": "Steady speed can still need a driving force when resistance is present.", "model": null, "id": "y9-unit-11-friction", "unit": "y9-unit-11", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Friction", "definition": "A contact force that opposes sliding between surfaces."}, {"term": "Drag", "definition": "A force opposing movement through air or water."}, {"term": "Plastic deformation", "definition": "A permanent change of shape."}], "quiz": {"q": "Why does a cyclist need a driving force at steady speed?", "opts": ["Because balanced forces must make the cyclist stop.", "Because the bicycle has no weight.", "To balance friction and air resistance."], "a": 2, "why": "A forward driving force balances the backward forces, giving no change in speed."}, "misconception": {"q": "Why does a cyclist need a driving force at steady speed? Sam answers: “Because balanced forces must make the cyclist stop.” Explain why this is wrong.", "m": 2, "ms": ["To balance friction and air resistance.", "A forward driving force balances the backward forces, giving no change in speed."]}}, {"key": "spring", "title": "Stretching springs", "notes": ["A spring gets longer when a pulling force is added. Extension means the extra length. Extension = stretched length − original length.", "For a spring obeying Hooke's law, force = spring constant × extension. Use extension in metres with a spring constant in N/m. Too much force can stop the spring following this rule. To test a spring, measure its starting length and then add small loads. Wait for it to settle before recording length and calculating extension. Plot force against extension and look for a straight-line pattern."], "worked": "A spring has a spring constant of 200 N/m and extends by 0.03 m. Force = 200 × 0.03 = 6 N. The rule only works while force and extension stay proportional.", "question": "A spring has a spring constant of 200 N/m and extends by 0.03 m. Find the force and say when Hooke's law works.", "scheme": ["Use force = spring constant × extension.", "200 × 0.03 = 6 N.", "The spring must be within its limit of proportionality, before the graph stops being a straight line."], "mistake": "Use the extension, not the spring's total length.", "model": "spring", "id": "y9-unit-11-spring", "unit": "y9-unit-11", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Spring constant", "definition": "How much force is needed for each metre of extension while the spring follows Hooke's law."}, {"term": "Limit of proportionality", "definition": "The point where force and extension stop following a straight-line pattern."}], "quiz": {"q": "Which length goes into force = spring constant × extension?", "opts": ["The extra length beyond the original length.", "The total spring length.", "The original length alone."], "a": 0, "why": "Extension = stretched length − original length."}, "misconception": {"q": "Which length goes into force = spring constant × extension? Sam answers: “The total spring length.” Explain why this is wrong.", "m": 2, "ms": ["The extra length beyond the original length.", "Extension = stretched length − original length."]}}, {"key": "moments", "title": "Levers and turning forces", "notes": ["A force can turn an object around a pivot. The turning effect is called a moment. A pivot is the point the object turns about.", "Moment = force × perpendicular distance from the pivot. Perpendicular means at right angles to the force's line. A balanced lever has equal clockwise and anticlockwise moments."], "worked": "A 12 N force acts 0.5 m from a pivot. Its moment is 12 × 0.5 = 6 N m. A force on the other side at 0.3 m must be 6 ÷ 0.3 = 20 N.", "question": "A 12 N force acts 0.5 m from a pivot. What opposite turning force at 0.3 m will balance it?", "scheme": ["First moment = 12 × 0.5 = 6 N m.", "For balance, the other moment must also be 6 N m.", "Other force = 6 ÷ 0.3 = 20 N."], "mistake": "Use the right-angle distance to the force's line, not any distance from the pivot.", "model": "lever", "id": "y9-unit-11-moments", "unit": "y9-unit-11", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Moment", "definition": "The turning effect of a force around a pivot."}, {"term": "Pivot", "definition": "The point an object turns around."}], "quiz": {"q": "Which distance is used to calculate a moment?", "opts": ["The right-angle distance from the pivot to the force's line.", "Any sloping distance from the pivot.", "The total length of the object in every case."], "a": 0, "why": "Moment uses the perpendicular, or right-angle, distance."}, "misconception": {"q": "Which distance is used to calculate a moment? Sam answers: “Any sloping distance from the pivot.” Explain why this is wrong.", "m": 2, "ms": ["The right-angle distance from the pivot to the force's line.", "Moment uses the perpendicular, or right-angle, distance."]}}, {"key": "pressure", "title": "Pressure and area", "notes": ["Pressure tells you how spread out a force is over a surface. Pressure = force ÷ area. Pressure is measured in pascals, Pa, when force is in N and area in m².", "The same force on a smaller area gives higher pressure. A larger area spreads the force and lowers pressure. This helps explain sharp tools and wide snowshoes."], "worked": "A 120 N force acts over 0.04 m². Pressure = 120 ÷ 0.04 = 3000 Pa. Doubling the area with the same force halves the pressure.", "question": "A 120 N force acts over 0.04 m². Find the pressure. What happens if the area doubles with the force unchanged?", "scheme": ["Pressure = 120 ÷ 0.04.", "Pressure = 3000 Pa.", "Doubling the area halves pressure to 1500 Pa."], "mistake": "Pressure and force are different. The area matters too.", "model": null, "id": "y9-unit-12-pressure", "unit": "y9-unit-12", "year": 9, "number": 1, "marks": 3, "cards": [{"term": "Pressure", "definition": "Force spread over an area, calculated as force divided by area."}, {"term": "Pascal", "definition": "One newton of force per square metre."}], "quiz": {"q": "What happens to pressure if area doubles but force stays the same?", "opts": ["It halves.", "It doubles.", "It stays the same."], "a": 0, "why": "The same force is spread over twice the area, so pressure is half as large."}, "misconception": {"q": "What happens to pressure if area doubles but force stays the same? Sam answers: “It doubles.” Explain why this is wrong.", "m": 2, "ms": ["It halves.", "The same force is spread over twice the area, so pressure is half as large."]}}, {"key": "gas", "title": "Gas pressure", "notes": ["Gas particles move in all directions. They hit the walls of their container. These hits cause gas pressure.", "Squeezing a gas puts the particles in a smaller space. They hit the walls more often. This increases pressure if the temperature stays the same."], "worked": "Seal the end of a syringe containing air. Push the plunger in to reduce the space. The trapped air pushes back more strongly.", "question": "Why does squeezing the air in a sealed syringe increase its pressure?", "scheme": ["The same gas is in a smaller volume.", "Particles hit the walls more often.", "More frequent hits increase pressure."], "mistake": "Pressure comes from particles hitting a surface. Particles do not grow when heated.", "model": "particles", "id": "y9-unit-12-gas", "unit": "y9-unit-12", "year": 9, "number": 2, "marks": 3, "cards": [{"term": "Gas pressure", "definition": "The force on each unit area caused by gas particles hitting a surface."}, {"term": "Compression", "definition": "Squeezing something into a smaller volume."}], "quiz": {"q": "What happens when you heat gas in a sealed container that cannot expand?", "opts": ["Its pressure rises.", "Its number of particles falls.", "Its particles stop hitting the walls."], "a": 0, "why": "The particles move faster and hit the walls more often and harder."}, "misconception": {"q": "What happens when you heat gas in a sealed container that cannot expand? Sam answers: “Its number of particles falls.” Explain why this is wrong.", "m": 2, "ms": ["Its pressure rises.", "The particles move faster and hit the walls more often and harder."]}}, {"key": "liquid-pressure", "title": "Pressure in liquids and hydraulics", "notes": ["Liquid pressure acts in all directions. It increases with depth. Deeper water has more water above it pressing down.", "A hydraulic system uses liquid to pass on a pressure change. At the same pressure, a larger piston area gives a larger force. The larger piston moves a shorter distance, so no extra energy is created."], "worked": "A container has holes at different depths. The lower hole has a greater water pressure behind it. Its water jet can leave faster and travel further.", "question": "Why can a hole lower down a water container make a stronger water jet?", "scheme": ["There is more water above the lower hole.", "Liquid pressure is greater at a greater depth.", "The greater pressure pushes water out faster."], "mistake": "The same liquid pressure can give different forces on different areas.", "model": null, "id": "y9-unit-12-liquid-pressure", "unit": "y9-unit-12", "year": 9, "number": 3, "marks": 3, "cards": [{"term": "Hydraulic system", "definition": "A system using liquid to pass on a pressure change."}, {"term": "Liquid pressure", "definition": "The force from a liquid on each unit area."}], "quiz": {"q": "Why can a larger hydraulic output piston give a bigger force?", "opts": ["A bigger piston must move further than a smaller one.", "The same pressure acts on a larger area.", "The liquid creates extra energy."], "a": 1, "why": "Force = pressure × area. The bigger force is balanced by a shorter movement."}, "misconception": {"q": "Why can a larger hydraulic output piston give a bigger force? Sam answers: “The liquid creates extra energy.” Explain why this is wrong.", "m": 2, "ms": ["The same pressure acts on a larger area.", "Force = pressure × area. The bigger force is balanced by a shorter movement."]}}], "sources": [{"title": "Department 2026–27 teaching sequence", "kind": "curriculum", "detail": "Adapted from the lesson folders and planning workbooks supplied by the department. Revision pages consolidate related teaching periods; original slides, staff allocations and school tests are not reproduced."}, {"title": "National curriculum: science", "url": "https://www.gov.uk/government/publications/national-curriculum-in-england-science-programmes-of-study"}, {"title": "NHS: young people and vaping", "url": "https://www.nhs.uk/better-health/quit-smoking/help-others-quit/young-people-and-vaping/"}, {"title": "Met Office: causes of climate change", "url": "https://weather.metoffice.gov.uk/climate-change/causes-of-climate-change"}, {"title": "BBC Bitesize: KS3 Physics", "url": "https://www.bbc.co.uk/bitesize/subjects/ztjqfdm", "detail": "Reading-level and vocabulary reference for this original plain-language revision content."}, {"title": "BBC Bitesize: variables", "url": "https://www.bbc.co.uk/bitesize/topics/zrv3jfr/articles/zyc9r2p"}]};
window.KS_PAPERS=[{"id": "y7-paper-a", "year": 7, "paper": "A", "title": "Year 7 · Practice paper A", "minutes": 35, "marks": 30, "coverage": ["Working scientifically", "Cells", "Movement", "Particle model", "Separating mixtures", "Energy costs", "Energy transfers", "Variation and adaptation", "Human reproduction", "Plant reproduction", "Acids and alkalis", "Metals and non-metals", "Current and charge", "Potential difference and resistance"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "Test how water temperature affects sugar dissolving time. Name what you change, what you measure and one thing you keep the same.", "m": 3, "ms": ["Change water temperature.", "Measure time taken for sugar to dissolve.", "Keep sugar mass, water volume, stirring or sugar grain size the same."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "An empty balance reads 3 g. What type of error is this? How does it affect readings, and how would you fix it?", "m": 3, "ms": ["It is a systematic or zero error.", "Readings are all 3 g too high.", "Set the balance to zero or calibrate it before measuring."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A microscope has a ×12 eyepiece and ×10 objective. Find total magnification. Give one rule for drawing a clear cell diagram.", "m": 3, "ms": ["Multiply 12 × 10.", "Total magnification = ×120.", "Use clear single lines, straight label lines or suitable proportions."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Name three structures in a typical leaf cell that are not found in a typical animal cell.", "m": 3, "ms": ["A cell wall.", "Chloroplasts.", "A large permanent vacuole."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "Why do muscles work as an opposing pair to bend and straighten a joint?", "m": 3, "ms": ["Muscles pull rather than actively push.", "One muscle contracts to move the joint one way.", "The other contracts to move it back."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "Use particles to explain why a gas fills its container but a solid keeps its shape.", "m": 3, "ms": ["Gas particles move freely with large gaps.", "They spread throughout the available space.", "Solid particles vibrate around fixed positions."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "How would you get salt crystals from a dry mixture of salt and sand?", "m": 3, "ms": ["Add water to dissolve the salt.", "Filter out the sand.", "Evaporate some water and leave the solution to form crystals."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "A lamp takes in 240 J and gives 36 J as useful light. Find its efficiency and the unwanted energy transfer.", "m": 3, "ms": ["Efficiency = 36 ÷ 240 = 0.15.", "Efficiency = 15%.", "Unwanted energy = 240 − 36 = 204 J."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "A 1.5 kW heater runs for 2 hours. Electricity costs 24 p per kWh. Find the energy used and the cost.", "m": 3, "ms": ["Energy = 1.5 × 2 = 3 kWh.", "Cost = 3 × 24.", "Cost = 72 p."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "How are inherited and environmental differences different? Give one example of each.", "m": 3, "ms": ["Inherited differences come from genes passed on by parents.", "Environmental differences come from surroundings or experiences.", "Examples include inherited ABO blood group and an environmental scar; accept other correct examples."]}]}]}, {"id": "y7-paper-b", "year": 7, "paper": "B", "title": "Year 7 · Practice paper B", "minutes": 35, "marks": 30, "coverage": ["Working scientifically", "Cells", "Movement", "Particle model", "Separating mixtures", "Energy costs", "Energy transfers", "Variation and adaptation", "Human reproduction", "Plant reproduction", "Acids and alkalis", "Metals and non-metals", "Current and charge", "Potential difference and resistance"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "What are fertilisation and implantation in humans? Say where each usually happens.", "m": 3, "ms": ["Sperm and egg nuclei join at fertilisation.", "Fertilisation usually happens in an oviduct, also called a fallopian tube.", "The embryo later attaches to the uterus lining at implantation."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "Describe two features of an insect-pollinated flower. Explain how a feature helps pollination.", "m": 3, "ms": ["A feature such as bright petals or scent.", "It attracts insects that can carry pollen.", "Nectar attracts insects, or sticky pollen attaches to them; link a second feature to its job."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "How is pollination different from fertilisation in a flowering plant? Include the step that links them.", "m": 3, "ms": ["Pollination moves pollen from anther to stigma.", "A pollen tube grows towards an ovule.", "At fertilisation, male and egg nuclei join."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Name three conditions most seeds need to germinate. Explain why one is needed.", "m": 3, "ms": ["Water.", "Oxygen.", "A suitable temperature, plus an explanation such as oxygen being needed for aerobic respiration."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "A pupil says every strong acid must be concentrated. Why are these words different?", "m": 3, "ms": ["Strength describes how much the acid splits into charged particles in water.", "Concentration describes how much acid is in a given volume of solution.", "A strong acid can be dilute if mixed with plenty of water."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "Zinc reacts with dilute hydrochloric acid. Name the products and describe a test for the gas.", "m": 3, "ms": ["Zinc chloride.", "Hydrogen.", "A small sample makes a squeaky pop with a lighted splint in a teacher-supervised test."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Magnesium is more reactive than copper. What happens when magnesium is put into copper sulfate solution? Explain why.", "m": 3, "ms": ["Magnesium displaces copper.", "Magnesium sulfate and copper form.", "Magnesium replaces copper because it is more reactive."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "Two parallel branches carry 0.35 A and 0.45 A. Find the supply current and explain your method.", "m": 3, "ms": ["Add 0.35 + 0.45.", "Supply current = 0.80 A.", "Total current into a junction equals total current out."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "A resistor has 9 V across it and a current of 0.3 A. Find its resistance. How should the voltmeter be connected?", "m": 3, "ms": ["Resistance = voltage ÷ current.", "9 ÷ 0.3 = 30 Ω.", "Connect the voltmeter in parallel across the resistor."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "A ball bounces lower each time. Why is the total energy of the ball and its surroundings still conserved?", "m": 3, "ms": ["Less energy remains in the ball for movement and height.", "Energy transfers to heating and sound in the surroundings.", "The energy is not destroyed, so the total stays the same."]}]}]}, {"id": "y8-paper-a", "year": 8, "paper": "A", "title": "Year 8 · Practice paper A", "minutes": 35, "marks": 30, "coverage": ["Interdependence", "Speed", "Gravity and forces", "Elements and materials", "Periodic table", "Breathing and health", "Digestion and nutrition", "Sound", "Light", "Reaction types", "Chemical energy", "Respiration", "Photosynthesis", "Working scientifically investigations"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "In grass → grasshopper → bird, grasshopper numbers fall. What might happen to the grass and birds? Give one reason your prediction may not be exact.", "m": 3, "ms": ["Grass may increase because less is eaten.", "Birds may decline because they have less food.", "Other food sources or other changes in the food web could affect the result."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "How could you use quadrats to estimate how many plants grow in a field?", "m": 3, "ms": ["Place equal-sized quadrats at random points and count consistently.", "Calculate a mean number per square metre from several samples.", "Multiply by field area and state that the answer is an estimate."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A trolley travels 3.6 m in 6 seconds. Find its average speed. Give one way to reduce timing error.", "m": 3, "ms": ["Speed = 3.6 ÷ 6.", "Speed = 0.6 m/s.", "Use electronic timing or a longer timed distance to reduce the effect of reaction time."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Describe the forces on a skydiver falling at terminal velocity. Why is the speed steady?", "m": 3, "ms": ["Weight acts downwards.", "Drag acts upwards with the same size as weight.", "The forces balance, so speed does not change."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "What is an element, a compound and a mixture? Give an example of each.", "m": 3, "ms": ["An element contains one type of atom, such as iron.", "A compound has different elements chemically joined, such as water.", "A mixture contains substances not chemically joined to each other, such as air."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "How does reactivity change down Groups 1 and 7? Chlorine is more reactive than bromine. Can it displace bromine from a bromide solution?", "m": 3, "ms": ["Group 1 generally gets more reactive down the group.", "Group 7 generally gets less reactive down the group.", "Yes. Chlorine displaces the less reactive bromine."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Give three features that help alveoli exchange gases quickly.", "m": 3, "ms": ["A large surface area.", "Thin walls give a short distance for gases to travel.", "A good blood supply and fresh air maintain concentration differences."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "How do enzymes and villi help digested nutrients reach the blood?", "m": 3, "ms": ["Enzymes break large food molecules into small soluble ones.", "Villi give a large surface area for absorption.", "Small molecules pass through the thin gut wall into the blood."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "What does a positive iodine test look like? What can and cannot be concluded from a negative result?", "m": 3, "ms": ["A blue-black colour shows starch was detected.", "A negative result means starch was not detected in that test.", "Other carbohydrates, such as sugars, may still be present."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "Why should young people not describe nicotine vaping as harmless? Give three points.", "m": 3, "ms": ["Nicotine can cause dependence, making it difficult to stop.", "It can affect health and the developing body.", "Less harmful than smoking does not mean harmless or suitable for children and non-smokers."]}]}]}, {"id": "y8-paper-b", "year": 8, "paper": "B", "title": "Year 8 · Practice paper B", "minutes": 35, "marks": 30, "coverage": ["Interdependence", "Speed", "Gravity and forces", "Elements and materials", "Periodic table", "Breathing and health", "Digestion and nutrition", "Sound", "Light", "Reaction types", "Chemical energy", "Respiration", "Photosynthesis", "Working scientifically investigations"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "A wave has frequency 8 Hz and wavelength 0.5 m. Find its speed. What does frequency mean?", "m": 3, "ms": ["Speed = frequency × wavelength.", "Speed = 8 × 0.5 = 4 m/s.", "Frequency is the number of complete vibrations each second."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "How is a higher-pitched sound different from a louder sound?", "m": 3, "ms": ["A higher pitch means a higher frequency.", "A louder sound usually has a larger amplitude.", "Pitch and loudness can change separately."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A ray hits a plane mirror at 28° to the normal. Find the reflection angle and the angle to the mirror surface.", "m": 3, "ms": ["The reflection angle is 28° to the normal.", "The normal is at 90° to the mirror.", "The angle to the mirror surface is 90 − 28 = 62°."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "A reaction in an open flask gives off gas and the measured mass falls. Why has mass not been destroyed?", "m": 3, "ms": ["Gas leaves the flask.", "The gas still exists outside the flask.", "Counting all reactants and products, including the gas, gives the same total mass."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "Explain why an exothermic reaction warms its surroundings. Include breaking and making bonds.", "m": 3, "ms": ["Breaking old bonds takes in energy.", "Making new bonds releases energy.", "More energy is released than taken in, so the extra energy warms the surroundings."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "A catalyst gives more gas after 30 seconds but the same final gas volume. Explain why.", "m": 3, "ms": ["A catalyst speeds up the reaction.", "The same starting amounts can make the same total gas.", "The reaction finishes sooner rather than making extra product."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Write the word equation for aerobic respiration. How is respiration different from breathing?", "m": 3, "ms": ["Glucose + oxygen → carbon dioxide + water.", "Respiration is a chemical process in cells that releases energy.", "Breathing moves air into and out of the lungs."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "Name the two products of yeast fermentation. Explain how one helps bread making.", "m": 3, "ms": ["Ethanol.", "Carbon dioxide.", "Carbon dioxide bubbles make the dough rise."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "Why might brighter light stop increasing oxygen production by pondweed?", "m": 3, "ms": ["At first, too little light slowed photosynthesis.", "Another factor, such as carbon dioxide, may now be in short supply.", "Extra light alone cannot remove that other limit."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "Dye spreads faster in warm water. Give one control and explain why the result may not be due to diffusion alone.", "m": 3, "ms": ["Keep dye amount, water volume or container size the same and do not stir.", "Convection currents can carry the coloured water.", "The colour spreading therefore does not measure diffusion alone."]}]}]}, {"id": "y9-paper-a", "year": 9, "paper": "A", "title": "Year 9 · Practice paper A", "minutes": 35, "marks": 30, "coverage": ["Electromagnets", "Work and machines", "Heating and cooling", "Climate", "Earth’s resources", "Evolution and biodiversity", "Inheritance", "Waves and the EM spectrum", "Earth structure and rocks", "The Universe", "Contact forces", "Pressure"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "Why does a compass turn near a bar magnet? Which way do field arrows point outside the magnet?", "m": 3, "ms": ["A compass needle is a small magnet.", "It turns to line up with the magnetic field.", "Field arrows outside a magnet point from north to south."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "How does an electromagnet operate a relay switch? Give one benefit of this type of magnet.", "m": 3, "ms": ["Current in a coil makes a magnetic field.", "The magnet pulls a metal part to operate a switch.", "Switching the current lets you turn the magnet on and off."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "A 30 N force moves a load 2.5 m in its direction. Find the work done. What does the unit mean?", "m": 3, "ms": ["Work done = force × distance.", "30 × 2.5 = 75 J.", "A joule is a unit of energy transferred."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "A 15 N force acts 0.4 m from a pivot. What force on the opposite side, 0.6 m away, balances it?", "m": 3, "ms": ["First moment = 15 × 0.4 = 6 N m.", "The other force × 0.6 must equal 6 N m.", "Other force = 6 ÷ 0.6 = 10 N."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "How does a vacuum flask reduce conduction, convection and radiation?", "m": 3, "ms": ["The vacuum greatly reduces conduction across the gap because it has almost no particles.", "The vacuum prevents convection across the gap.", "Shiny surfaces reduce infrared radiation transfer."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "How can burning fossil fuels change the carbon cycle and warm Earth?", "m": 3, "ms": ["Burning moves carbon from fuel into the air as carbon dioxide.", "Extra carbon dioxide absorbs more outgoing infrared radiation and sends some back towards the surface.", "This changes the energy balance and causes warming."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Why can carbon extract some metals from their oxides, while aluminium is usually extracted using electricity?", "m": 3, "ms": ["The metal reactivity affects the extraction method.", "Carbon can remove oxygen from oxides of less reactive metals.", "Aluminium is more reactive than carbon, so electricity is used instead."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "Give two environmental benefits and one drawback of recycling metals.", "m": 3, "ms": ["It saves limited metal ores.", "It often uses less energy and reduces mining damage.", "Collection, sorting and processing still use resources."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "Describe natural selection in three linked steps.", "m": 3, "ms": ["Individuals have inherited differences.", "Those with helpful features are more likely to survive and reproduce.", "They pass on genes, so helpful features can become more common over generations."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "Why might a breeding programme alone not save an endangered species in the wild?", "m": 3, "ms": ["Enough animals must breed successfully with enough inherited variation.", "They also need a safe, suitable habitat.", "If threats remain, released animals may not survive and reproduce."]}]}]}, {"id": "y9-paper-b", "year": 9, "paper": "B", "title": "Year 9 · Practice paper B", "minutes": 35, "marks": 30, "coverage": ["Electromagnets", "Work and machines", "Heating and cooling", "Climate", "Earth’s resources", "Evolution and biodiversity", "Inheritance", "Waves and the EM spectrum", "Earth structure and rocks", "The Universe", "Contact forces", "Pressure"], "questions": [{"title": "Question 1", "stem": "", "parts": [{"title": "Question 1", "q": "How are DNA, chromosomes, genes and alleles related?", "m": 3, "ms": ["Chromosomes contain long DNA molecules.", "Genes are sections of DNA.", "Alleles are different versions of a gene."]}]}, {"title": "Question 2", "stem": "", "parts": [{"title": "Question 2", "q": "In a simple dominant model, cross Aa with Aa. Give the genotype ratio and the chance of the recessive feature.", "m": 3, "ms": ["Possible combinations are AA, Aa, Aa and aa.", "The genotype ratio is 1 AA : 2 Aa : 1 aa.", "The recessive feature has a 1 in 4 chance."]}]}, {"title": "Question 3", "stem": "", "parts": [{"title": "Question 3", "q": "An ultrasound echo returns after 0.00008 seconds. Sound speed is 1500 m/s. How deep is the reflecting surface?", "m": 3, "ms": ["Total distance = 1500 × 0.00008 = 0.12 m.", "Divide by two for the outward and return journeys.", "Depth = 0.06 m."]}]}, {"title": "Question 4", "stem": "", "parts": [{"title": "Question 4", "q": "Compare sound and electromagnetic waves. Which need a material to travel through, and which can be ionising?", "m": 3, "ms": ["Sound needs a material, but electromagnetic waves can cross empty space.", "Sound is not ionising.", "Some high-energy electromagnetic waves, such as X-rays, can ionise atoms and damage cells."]}]}, {"title": "Question 5", "stem": "", "parts": [{"title": "Question 5", "q": "How do igneous, sedimentary and metamorphic rocks form?", "m": 3, "ms": ["Igneous rock forms when molten rock cools and becomes solid.", "Sedimentary rock often forms when layers of sediment are pressed and cemented together.", "Metamorphic rock forms when heat and pressure change rock without melting it."]}]}, {"title": "Question 6", "stem": "", "parts": [{"title": "Question 6", "q": "Why do normal Moon phases happen? Why are they different from an eclipse?", "m": 3, "ms": ["The Moon reflects sunlight and roughly half is lit.", "Its orbit changes how much of the lit half we can see.", "The shadow of Earth causes a lunar eclipse, not normal phases."]}]}, {"title": "Question 7", "stem": "", "parts": [{"title": "Question 7", "q": "Explain the seasons on Earth using its tilted axis. Why does summer not depend mainly on Earth being closer to the Sun?", "m": 3, "ms": ["The axis of Earth is tilted.", "The hemisphere tilted towards the Sun has longer days.", "It also receives more direct sunlight, while the other hemisphere has winter."]}]}, {"title": "Question 8", "stem": "", "parts": [{"title": "Question 8", "q": "A 5 N force extends a spring by 0.025 m. Find the spring constant. State when this calculation is valid.", "m": 3, "ms": ["Spring constant = force ÷ extension.", "5 ÷ 0.025 = 200 N/m.", "The spring must be within the straight-line force–extension range, below its limit of proportionality."]}]}, {"title": "Question 9", "stem": "", "parts": [{"title": "Question 9", "q": "A 480 N force acts over 0.024 m². Find the pressure. What if the area doubles while force stays the same?", "m": 3, "ms": ["Pressure = 480 ÷ 0.024 = 20,000 Pa.", "Doubling area halves pressure at the same force.", "The new pressure is 10,000 Pa."]}]}, {"title": "Question 10", "stem": "", "parts": [{"title": "Question 10", "q": "How can a hydraulic system give a larger output force without creating extra energy?", "m": 3, "ms": ["A pressure change is passed through the enclosed liquid.", "A larger output piston area gives a larger force.", "The larger piston moves a shorter distance, so no extra energy is created."]}]}]}];
